_tube_cache: dict = {}


def get_tube_status(line: str = None) -> str:
    key = line or "all"
    cached = _tube_cache.get(key)
    if cached and (time.time() - cached["ts"]) < 120:
        return cached["v"]
    try:
        if line:
            url = f"https://api.tfl.gov.uk/Line/{line}/Status"
        else:
            url = "https://api.tfl.gov.uk/Line/Mode/tube,elizabeth-line,dlr,overground/Status"
        r = requests.get(url, timeout=8)
        r.raise_for_status()
        data = r.json()
    except Exception as e:
        return f"Couldn't fetch tube status: {e}"

    lines_out = []
    for entry in data:
        name = entry.get("name", "")
        statuses = entry.get("lineStatuses", [])
        if statuses:
            sev_desc = statuses[0].get("statusSeverityDescription", "Unknown")
            disruption = statuses[0].get("disruption") or {}
            reason = disruption.get("description", "") if isinstance(disruption, dict) else ""
            emoji = _TUBE_STATUS_EMOJI.get(sev_desc, "ℹ️")
            line_str = f"{emoji} {name}: {sev_desc}"
            if reason and sev_desc != "Good Service":
                reason = reason[:100] + "…" if len(reason) > 100 else reason
                line_str += f"\n   {reason}"
            lines_out.append(line_str)

    result = "🚇 *Tube Status*\n" + "\n".join(lines_out)
    _tube_cache[key] = {"v": result, "ts": time.time()}
    return result


_STATION_QUALIFIER_RE = re.compile(
    r'\b(national rail|dlr|tube|underground|overground|tfl|elizabeth line)\b', re.I
)

def _resolve_tube_station(name: str):
    """Return (naptan_id, display_name) for the best-matching TfL station, or (None, None)."""
    clean = _STATION_QUALIFIER_RE.sub('', name).strip()
    if not clean:
        clean = name.strip()

    def _tfl_search(q):
        r = requests.get(
            "https://api.tfl.gov.uk/StopPoint/Search/" + requests.utils.quote(q),
            params={"modes": "tube,dlr,elizabeth-line,overground", "includeHubs": "false", "maxResults": "6"},
            timeout=8,
        )
        r.raise_for_status()
        return r.json().get("matches", [])

    try:
        matches = _tfl_search(clean)
        # "London Waterloo" → try "Waterloo" if no results
        if not matches and clean.lower().startswith("london "):
            matches = _tfl_search(clean[7:])
        # Prefer 940G IDs (true TfL metro naptan — avoids NR 910G IDs in journey planner)
        for m in matches:
            if m["id"].startswith("940G"):
                return m["id"], m["name"].replace(" Underground Station", "").replace(" Station", "")
        if matches:
            return matches[0]["id"], matches[0]["name"].replace(" Underground Station", "").replace(" Station", "")
    except Exception:
        pass
    return None, None


def get_tube_journey(from_name: str, to_name: str) -> str:
    from_id, from_display = _resolve_tube_station(from_name)
    to_id, to_display = _resolve_tube_station(to_name)
    if not from_id:
        return f"Couldn't find tube station: {from_name}"
    if not to_id:
        return f"Couldn't find tube station: {to_name}"
    try:
        r = requests.get(
            f"https://api.tfl.gov.uk/Journey/JourneyResults/{from_id}/to/{to_id}",
            params={"mode": "tube,dlr,elizabeth-line,overground"},
            timeout=10,
        )
        r.raise_for_status()
        journeys = r.json().get("journeys", [])
    except Exception as e:
        return f"Journey planner error: {e}"

    if not journeys:
        return f"No tube journey found from {from_display} to {to_display}"

    j = journeys[0]
    duration = j.get("duration", "?")
    legs = j.get("legs", [])

    def _short(name):
        return name.replace(" Underground Station", "").replace(" Station", "")

    from_short = _short(from_display)
    to_short   = _short(to_display)

    parts = [f"🚇 *{from_short} → {to_short}*", f"⏱ {duration} min"]

    tube_legs = []
    for leg in legs:
        mode = leg.get("mode", {}).get("name", "")
        leg_dur = leg.get("duration", "?")
        dep = _short(leg.get("departurePoint", {}).get("commonName", ""))
        arr = _short(leg.get("arrivalPoint", {}).get("commonName", ""))
        route_opts = leg.get("routeOptions", [])
        line_name = route_opts[0].get("name", "") if route_opts else ""
        if mode in ("tube", "dlr", "elizabeth-line", "overground", "national-rail"):
            fallback_label = {"dlr": "DLR", "elizabeth-line": "Elizabeth", "overground": "Overground"}.get(mode, "Tube")
            # Only show leg detail if it's not trivially the same as the header
            if dep != from_short or arr != to_short or len(legs) > 1:
                parts.append(f"• {line_name or fallback_label}: {dep} → {arr} ({leg_dur} min)")
            else:
                parts.append(f"• {line_name or fallback_label} line ({leg_dur} min)")
            tube_legs.append({"line": line_name, "dep_id": from_id})
        elif mode == "walking":
            if leg_dur and int(leg_dur) > 1:
                parts.append(f"• Walk {leg_dur} min")

    # Append live next departures on the first tube leg from the origin
    if tube_legs:
        first_line = tube_legs[0]["line"]
        try:
            arr_r = requests.get(
                f"https://api.tfl.gov.uk/StopPoint/{from_id}/Arrivals",
                timeout=6,
            )
            arr_r.raise_for_status()
            arrivals = arr_r.json()
            arrivals.sort(key=lambda a: a.get("timeToStation", 9999))
            next_deps = []
            seen_dir = set()
            for a in arrivals:
                if first_line and a.get("lineName", "").lower() != first_line.lower():
                    continue
                secs = a.get("timeToStation", 0)
                mins = secs // 60
                platform = a.get("platformName", "")
                dir_key = platform
                if dir_key in seen_dir:
                    continue
                seen_dir.add(dir_key)
                due = "Due" if mins < 1 else f"{mins} min"
                dest = a.get("destinationName", "").replace(" Underground Station", "")
                next_deps.append(f"  {due} → {dest}")
                if len(next_deps) >= 3:
                    break
            if next_deps:
                parts.append(f"\n*Next {first_line} from {from_short}:*")
                parts.extend(next_deps)
        except Exception:
            pass

    return "\n".join(parts)


def _get_wa_home_postcode(from_number: str):
    """Return the user's stored home postcode — checks my_area_places then v2_prefs."""
    try:
        plain = from_number.replace("whatsapp:", "").strip()
        wa    = from_number if from_number.startswith("whatsapp:") else f"whatsapp:{from_number}"
        rows = (lib._sb().table("my_area_places").select("postcode")
                .eq("category", "_home")
                .in_("from_number", [from_number, plain, wa])
                .limit(1).execute().data)
        if rows:
            return rows[0]["postcode"]
    except Exception:
        pass
    # Fallback: identity postcode stored in v2_prefs
    try:
        for did in [plain, wa]:
            prows = lib._sb().table("ma_details").select("data") \
                .eq("device_id", did).eq("type", "v2_prefs").limit(1).execute().data or []
            if prows:
                prefs = prows[0].get("data") or {}
                pc = prefs.get("fuel_postcode") or prefs.get("home_postcode") or ""
                if pc:
                    return pc
    except Exception:
        pass
    return None


def _set_wa_pending_intent(from_number: str, intent: dict):
    """Store a pending intent in Supabase so it survives Railway redeploys."""
    plain = from_number.replace("whatsapp:", "").strip()
    try:
        sb = lib._sb()
        sb.table("wa_saves").delete().eq("from_number", plain).eq("status", "pending_intent").execute()
        sb.table("wa_saves").insert({
            "from_number": plain,
            "status": "pending_intent",
            "url": "pending:" + json.dumps(intent),
            "title": "Pending intent: " + intent.get("type", ""),
        }).execute()
    except Exception as e:
        print(f"[pending_intent set] {e}")


def _get_wa_pending_intent(from_number: str):
    """Return stored pending intent dict, or None."""
    plain = from_number.replace("whatsapp:", "").strip()
    wa    = f"whatsapp:{plain}"
    try:
        rows = (lib._sb().table("wa_saves")
                .select("url,created_at")
                .in_("from_number", [from_number, plain, wa])
                .eq("status", "pending_intent")
                .order("created_at", desc=True)
                .limit(1).execute().data)
        if not rows:
            return None
        url = rows[0].get("url", "")
        if url.startswith("pending:"):
            return json.loads(url[8:])
    except Exception:
        pass
    return None


def _clear_wa_pending_intent(from_number: str):
    plain = from_number.replace("whatsapp:", "").strip()
    wa    = f"whatsapp:{plain}"
    try:
        lib._sb().table("wa_saves").delete().in_("from_number", [from_number, plain, wa]).eq("status", "pending_intent").execute()
    except Exception:
        pass


# ── Frequent places — learn regular destinations from drive queries ──────────

def _get_frequent_places(from_number: str) -> dict:
    plain = from_number.replace("whatsapp:", "").strip()
    try:
        row = lib._sb().table("ma_details").select("data").eq("device_id", plain).eq("type", "frequent_places").maybe_single().execute()
        if row.data:
            d = row.data.get("data") or {}
            return d if isinstance(d, dict) else {}
    except Exception:
        pass
    return {"places": []}


def _log_place_visit(from_number: str, name: str, query: str, lat: float = None, lng: float = None):
    """Increment visit count for a destination; does not confirm it as a regular."""
    import datetime as _dt
    plain = from_number.replace("whatsapp:", "").strip()
    if not plain:
        return
    try:
        rec    = _get_frequent_places(from_number)
        places = rec.get("places", [])
        today  = _dt.date.today().isoformat()
        dow    = _dt.datetime.now().weekday()
        name_l = name.lower(); query_l = query.lower()
        for p in places:
            if p.get("query", "").lower() == query_l or p.get("name", "").lower() == name_l:
                p["count"]      = p.get("count", 0) + 1
                p["last_visit"] = today
                days = p.get("days", [])
                if dow not in days:
                    days.append(dow)
                p["days"] = days
                if lat is not None and lng is not None:
                    p["lat"] = lat; p["lng"] = lng
                break
        else:
            entry = {"name": name, "query": query_l, "count": 1, "confirmed": False, "last_visit": today, "days": [dow]}
            if lat is not None and lng is not None:
                entry["lat"] = lat; entry["lng"] = lng
            places.append(entry)
        rec["places"] = places
        lib._sb().table("ma_details").upsert({"device_id": plain, "type": "frequent_places", "data": rec, "label": "frequent_places"}).execute()
    except Exception as _e:
        app.logger.warning(f"[frequent_places] log error: {_e}")


def _confirm_frequent_place(from_number: str, name: str):
    """Mark a destination as a confirmed regular."""
    import datetime as _dt
    plain = from_number.replace("whatsapp:", "").strip()
    if not plain:
        return
    try:
        rec    = _get_frequent_places(from_number)
        places = rec.get("places", [])
        name_l = name.lower()
        matched = False
        for p in places:
            if p.get("name", "").lower() == name_l or p.get("query", "").lower() == name_l:
                p["confirmed"] = True
                matched = True
                break
        if not matched:
            today = _dt.date.today().isoformat()
            places.append({"name": name, "query": name_l, "count": 1, "confirmed": True, "last_visit": today, "days": [_dt.datetime.now().weekday()]})
        rec["places"] = places
        lib._sb().table("ma_details").upsert({"device_id": plain, "type": "frequent_places", "data": rec, "label": "frequent_places"}).execute()
    except Exception as _e:
        app.logger.warning(f"[frequent_places] confirm error: {_e}")


def _nearest_tube_station(lat: float, lon: float, radius_m: int = 2000):
    """Return (naptan_id, display_name, distance_m) for nearest tube station, or (None,None,None)."""
    try:
        r = requests.get(
            "https://api.tfl.gov.uk/StopPoint",
            params={
                "lat": lat, "lon": lon,
                "stopTypes": "NaptanMetroStation,NaptanRailAccessArea",
                "radius": radius_m,
                "modes": "tube,dlr,elizabeth-line,overground",
                "returnLines": "false",
            },
            timeout=8,
        )
        r.raise_for_status()
        stops = r.json().get("stopPoints", [])
        if stops:
            s = stops[0]
            return s["id"], s["commonName"], round(s.get("distance", 0))
    except Exception as e:
        print(f"[tube nearest] {e}")
    return None, None, None


def get_tube_arrivals(naptan_id: str, station_name: str) -> str:
    """Return WhatsApp-formatted next arrivals at a tube station."""
    try:
        r = requests.get(
            f"https://api.tfl.gov.uk/StopPoint/{naptan_id}/Arrivals",
            timeout=8,
        )
        r.raise_for_status()
        arrivals = r.json()
    except Exception as e:
        return f"Couldn't fetch arrivals: {e}"

    if not arrivals:
        return f"🚇 *{station_name}*\nNo arrivals data right now."

    arrivals.sort(key=lambda a: a.get("timeToStation", 9999))

    seen, lines = set(), []
    for a in arrivals:
        line    = a.get("lineName", "")
        dest    = a.get("destinationName", "").replace(" Underground Station", "")
        platform = a.get("platformName", "")
        secs    = a.get("timeToStation", 0)
        mins    = secs // 60
        due     = "Due" if mins < 1 else f"{mins} min"
        key     = (line, platform)
        if key in seen:
            continue
        seen.add(key)
        dir_part = f"  _{platform}_" if platform else ""
        lines.append(f"• *{line}* → {dest}  {due}{dir_part}")
        if len(lines) >= 8:
            break

    short_name = station_name.replace(" Underground Station", "")
    return f"🚇 *{short_name}*\n" + "\n".join(lines)


def handle_tube_command(text: str, from_number: str = None) -> str:
    """Route a 'tube ...' WhatsApp message to the right TfL function."""
    remainder = text[4:].strip().lower()  # strip 'tube'

    if " to " in remainder:
        parts = remainder.split(" to ", 1)
        return get_tube_journey(parts[0].strip(), parts[1].strip())

    for alias, tfl_id in TFL_LINE_ALIASES.items():
        if remainder == alias or remainder.startswith(alias + " "):
            return get_tube_status(tfl_id)

    if remainder == "status":
        return get_tube_status()

    # "tube" or "tube near me" — show nearest station arrivals from home postcode
    if not remainder or remainder in ("near me", "nearest", "local"):
        if from_number:
            postcode = _get_wa_home_postcode(from_number)
            if postcode:
                latlon = postcode_to_latlon(postcode)
                if latlon:
                    lat, lon = latlon
                    naptan_id, name, dist_m = _nearest_tube_station(lat, lon)
                    if naptan_id:
                        dist_str = f"{dist_m}m away" if dist_m < 1000 else f"{dist_m/1000:.1f}km away"
                        header = get_tube_arrivals(naptan_id, name)
                        return header + f"\n\n_{dist_str} from {postcode}_"
                    return "No tube station found within 2km of your home postcode.\n\nTry: *tube Kings Cross to Waterloo*"
        return get_tube_status()

    return get_tube_status()


# ── Search & Format ───────────────────────────────────────────────────────────

def search_and_format(postcode: str, fuel: str, radius_miles: float, retailer: str = None) -> str:
    """Run search and format result as a concise SMS reply."""

    latlon = postcode_to_latlon(postcode)
    if not latlon:
        return f"Sorry, couldn't find postcode {postcode}. Please check and try again."

    lat, lon = latlon
    radius_km = radius_miles * 1.60934
    nearby = _nearby_stations(lat, lon, fuel, radius_km, retailer)

    if not nearby:
        retailer_msg = f" {retailer.title()}" if retailer else ""
        return (
            f"No{retailer_msg} {fuel} stations found within {radius_miles:.0f} miles of {postcode}.\n"
            f"Try: {postcode} {fuel} 10"
        )

    nearby.sort(key=lambda x: (x["price"], x["dist_mi"]))
    log_postcode_snapshot(postcode, fuel, nearby)
    avg = sum(s["price"] for s in nearby) / len(nearby)
    cheapest = nearby[0]
    tank_saving = (avg - cheapest["price"]) * 55 / 100

    fuel_label = "Petrol" if fuel == "petrol" else "Diesel"
    now = datetime.now().strftime("%d %b %Y %H:%M")
    weather = get_weather(lat, lon)

    # Today / date / time / weather
    lines = [
        f"Today {now}",
        weather if weather else "",
        "",
    ]

    # Petrol Prices
    retailer_label = f" — {retailer.title()}" if retailer else ""
    lines += [
        f"-- {fuel_label}{retailer_label} near {postcode} --",
        f"Radius: {radius_miles:.0f}mi | {len(nearby)} stations",
        "",
    ]
    for i, s in enumerate(nearby[:5], 1):
        marker = ">>>" if i == 1 else f" {i}."
        maps_url = f"https://maps.google.com/?q={s['lat']},{s['lon']}"
        lines.append(f"{marker} {s['brand']} {s['price']:.1f}p ({s['dist_mi']:.1f}mi)")
        if s["address"]:
            lines.append(f"    {s['address'][:30]}")
        lines.append(f"    {maps_url}")
    lines += [
        "",
        f"Avg: {avg:.1f}p | Save: {avg - cheapest['price']:.1f}p/L",
        f"Full tank: £{tank_saving:.2f} saving",
    ]

    # Supermarkets & Coffee (fetch with timeout so SMS isn't delayed)
    try:
        with ThreadPoolExecutor(max_workers=1) as ex:
            future = ex.submit(fetch_nearby_amenities, lat, lon, radius_miles * 1.60934)
            amenities = future.result(timeout=6)
    except (FuturesTimeoutError, Exception):
        amenities = {"supermarkets": [], "cafes": []}
    if amenities["supermarkets"]:
        lines += ["", "-- Supermarkets --"]
        for s in amenities["supermarkets"][:5]:
            lines.append(f"  {s['name']}{s['rating']} ({s['dist_mi']:.1f}mi)")
    if amenities["cafes"]:
        lines += ["", "-- Coffee --"]
        for c in amenities["cafes"][:5]:
            lines.append(f"  {c['name']}{c['rating']} ({c['dist_mi']:.1f}mi)")

    return "\n".join(l for l in lines if l is not None)


def whatsapp_search_and_format(postcode: str, fuel: str, radius_miles: float, retailer: str = None) -> str:
    """Lean WhatsApp reply — fuel prices + weather only, no amenities fetch."""
    latlon = postcode_to_latlon(postcode)
    if not latlon:
        return f"Sorry, couldn't find postcode {postcode}. Please check and try again."

    lat, lon = latlon
    radius_km = radius_miles * 1.60934
    nearby = _nearby_stations(lat, lon, fuel, radius_km, retailer)

    if not nearby:
        retailer_msg = f" {retailer.title()}" if retailer else ""
        return (f"No{retailer_msg} {fuel} stations found within {radius_miles:.0f} miles of {postcode}.\n"
                f"Try: {postcode} {fuel} 10")

    nearby.sort(key=lambda x: (x["price"], x["dist_mi"]))
    log_postcode_snapshot(postcode, fuel, nearby)
    avg = sum(s["price"] for s in nearby) / len(nearby)
    cheapest = nearby[0]
    tank_saving = (avg - cheapest["price"]) * 55 / 100

    fuel_label = "Petrol" if fuel == "petrol" else "Diesel"
    now = datetime.now().strftime("%d %b %Y %H:%M")
    weather = get_weather(lat, lon)

    lines = [f"FuelWatch 🇬🇧 {now}"]
    if weather:
        lines.append(weather)
    lines += ["", f"-- {fuel_label} near {postcode} --",
              f"Radius: {radius_miles:.0f}mi | {len(nearby)} stations", ""]

    for i, s in enumerate(nearby[:5], 1):
        marker = ">>>" if i == 1 else f" {i}."
        maps_url = f"https://maps.google.com/?q={s['lat']},{s['lon']}"
        lines.append(f"{marker} {s['brand']} {s['price']:.1f}p ({s['dist_mi']:.1f}mi)")
        if s["address"]:
            lines.append(f"    {s['address'][:35]}")
        lines.append(f"    {maps_url}")

    lines += ["", f"Avg: {avg:.1f}p | Save vs avg: {avg - cheapest['price']:.1f}p/L",
              f"Full tank saving: £{tank_saving:.2f}",
              "", "Reply with postcode [diesel] [radius]",
              "🔗 miru.humanagency.co"]
    return "\n".join(lines)


# ── Ask Miru Context Builder ──────────────────────────────────────────────────

def _build_ask_miru_context(from_number: str) -> str:
    """Build personalized user context for Ask Miru AI responses."""
    context_parts = []

    try:
        # Commutes
        commutes = _commuteLoad() if callable(globals().get("_commuteLoad")) else None
        if commutes:
            context_parts.append(f"User's commutes: {'; '.join(c.get('label','') for c in commutes[:3])}")
    except Exception:
        pass

    try:
        # Fuel postcode from preferences
        _fn_plain = from_number.replace("whatsapp:", "").strip()
        _fn_wa = f"whatsapp:{_fn_plain}"
        rows = lib._sb().table("ma_details").select("data").in_("device_id", [_fn_plain, _fn_wa]).eq("type", "v2_prefs").limit(1).execute().data or []
        if rows and rows[0].get("data", {}).get("fuel_postcode"):
            fuel_pc = rows[0]["data"]["fuel_postcode"]
            context_parts.append(f"Home postcode for fuel/travel: {fuel_pc}")
    except Exception:
        pass

    try:
        # School info
        school_rows = lib._sb().table("school_profiles").select("school_name,child_name").eq("from_number", from_number).eq("active", True).execute().data or []
        if school_rows:
            children = ", ".join(set(p.get("school_name","") for p in school_rows if p.get("school_name")))
            context_parts.append(f"Children's schools: {children}")
    except Exception:
        pass

    try:
        # Recent spend summary
        from datetime import date
        month_start = date.today().replace(day=1).isoformat()
        spend_rows = lib._sb().table("wa_saves").select("category").eq("from_number", from_number).gte("created_at", month_start).ilike("title", "🧾%").execute().data or []
        if spend_rows:
            categories = set(r.get("category","") for r in spend_rows if r.get("category"))
            if categories:
                context_parts.append(f"This month's spend categories: {', '.join(sorted(categories)[:5])}")
    except Exception:
        pass

    return "\n".join(context_parts) if context_parts else ""


def _cache_ask_miru_context(from_number: str) -> None:
    """Build and cache Ask Miru context for a user in ma_details."""
    try:
        if not from_number:
            return
        context_text = _build_ask_miru_context(from_number)
        from datetime import datetime
        lib._sb().table("ma_details").upsert({
            "device_id": from_number,
            "type": "ask_miru_context",
            "data": {
                "context": context_text,
                "built_at": datetime.utcnow().isoformat()
            }
        }, on_conflict="device_id,type").execute()
    except Exception as e:
        app.logger.debug(f"[cache_context] Failed for {from_number}: {e}")


def _get_cached_ask_miru_context(from_number: str) -> str:
    """Retrieve cached Ask Miru context for a user, or build fresh if missing."""
    try:
        if not from_number:
            return ""
        rows = lib._sb().table("ma_details").select("data").eq("device_id", from_number).eq("type", "ask_miru_context").limit(1).execute().data or []
        if rows and rows[0].get("data", {}).get("context"):
            return rows[0]["data"]["context"]
    except Exception:
        pass
    # Fallback: build fresh
    return _build_ask_miru_context(from_number)


# ── Ask Miru Intelligence Tools (for agentic RAG) ────────────────────────────

def _tool_get_receipts(merchant_name: str, from_number: str) -> str:
    """Get receipts for a specific merchant."""
    try:
        plain = from_number.replace("whatsapp:", "").strip()
        rows = lib._sb().table("wa_saves").select("title,summary,created_at") \
            .eq("from_number", plain).ilike("title", f"%🧾%{merchant_name}%") \
            .order("created_at", desc=True).limit(5).execute().data or []

        if not rows:
            return f"No receipts found for {merchant_name}."

        results = []
        for r in rows:
            merchant = (r.get("title","").replace("🧾","").strip())
            summary = r.get("summary","")
            date_str = (r.get("created_at","")[:10])
            results.append(f"• {merchant} on {date_str}: {summary[:60]}")
        return "\n".join(results) if results else f"No receipts found for {merchant_name}."
    except Exception as e:
        return f"Error retrieving receipts: {str(e)}"


def _tool_get_spend(period: str, from_number: str) -> str:
    """Get spending summary for a period (this month, last month, this quarter, etc)."""
    try:
        from datetime import date, timedelta
        plain = from_number.replace("whatsapp:", "").strip()

        # Parse period
        today = date.today()
        if "this month" in period.lower():
            start = today.replace(day=1)
            end = date(today.year, today.month + 1, 1) if today.month < 12 else date(today.year + 1, 1, 1)
        elif "last month" in period.lower():
            first = today.replace(day=1)
            last_month = first - timedelta(days=1)
            start = last_month.replace(day=1)
            end = first
        elif "this quarter" in period.lower():
            quarter = (today.month - 1) // 3 + 1
            start = date(today.year, (quarter-1)*3 + 1, 1)
            end = date(today.year, quarter*3 + 1, 1) if quarter < 4 else date(today.year + 1, 1, 1)
        else:
            start = today.replace(day=1)
            end = date(today.year, today.month + 1, 1) if today.month < 12 else date(today.year + 1, 1, 1)

        # Fetch spend data
        rows = lib._sb().table("wa_saves").select("title,summary,category") \
            .eq("from_number", plain).ilike("title", "🧾%") \
            .gte("created_at", start.isoformat()).lt("created_at", end.isoformat()) \
            .execute().data or []

        if not rows:
            return f"No spending found for {period}."

        total = 0.0
        by_category = {}
        import re as _re_sp
        for r in rows:
            summary = r.get("summary", "")
            category = r.get("category", "Other")
            m = _re_sp.search(r'£([\d,]+\.?\d*)', summary)
            if m:
                amount = float(m.group(1).replace(",", ""))
                total += amount
                if category not in by_category:
                    by_category[category] = 0
                by_category[category] += amount

        result = f"Spending for {period}: £{total:.2f}\n"
        for cat in sorted(by_category.keys(), key=lambda x: -by_category[x])[:5]:
            result += f"• {cat}: £{by_category[cat]:.2f}\n"
        return result
    except Exception as e:
        return f"Error retrieving spend: {str(e)}"


def _tool_get_schools(from_number: str) -> str:
    """Get active schools and children."""
    try:
        rows = lib._sb().table("school_profiles").select("child_name,school_name") \
            .eq("from_number", from_number).eq("active", True).execute().data or []

        if not rows:
            return "No active schools configured."

        result = "Active schools:\n"
        for r in rows:
            child = r.get("child_name", "Unknown")
            school = r.get("school_name", "Unknown")
            result += f"• {child} — {school}\n"
        return result
    except Exception as e:
        return f"Error retrieving schools: {str(e)}"


def _tool_get_commutes(from_number: str) -> str:
    """Get user's saved commute routes."""
    try:
        rows = lib._sb().table("commutes").select("label,dest,duration") \
            .eq("from_number", from_number).execute().data or []

        if not rows:
            return "No commutes configured."

        result = "Your commutes:\n"
        for r in rows:
            label = r.get("label", "Unknown")
            dest = r.get("dest", "")
            duration = r.get("duration", "")
            result += f"• {label} → {dest}" + (f" ({duration})" if duration else "") + "\n"
        return result
    except Exception as e:
        return f"Error retrieving commutes: {str(e)}"


def _refresh_all_ask_miru_contexts() -> dict:
    """Background task: rebuild Ask Miru context for all active users."""
    try:
        # Get all unique users (from school_profiles, v2_prefs, etc.)
        users = set()
        try:
            sp_rows = lib._sb().table("school_profiles").select("from_number").eq("active", True).execute().data or []
            users.update(r.get("from_number") for r in sp_rows if r.get("from_number"))
        except Exception:
            pass
        try:
            vp_rows = lib._sb().table("ma_details").select("device_id").eq("type", "v2_prefs").execute().data or []
            users.update(r.get("device_id") for r in vp_rows if r.get("device_id"))
        except Exception:
            pass

        updated = 0
        for user in users:
            _cache_ask_miru_context(user)
            updated += 1

        app.logger.info(f"[background] Ask Miru contexts refreshed for {updated} users")
        return {"users_updated": updated, "total_users": len(users)}
    except Exception as e:
        app.logger.error(f"[background] Context refresh failed: {e}")
        return {"error": str(e)}


# ── Webhook ───────────────────────────────────────────────────────────────────

@app.route("/sms", methods=["POST"])
def sms_reply():
    body = request.form.get("Body", "").strip()
    # Normalise smart/curly quotes to ASCII so regex matching works on mobile input
    body = body.replace("\u2018", "'").replace("\u2019", "'").replace("\u201c", '"').replace("\u201d", '"')
    from_number = request.form.get("From", "unknown")

    print(f"SMS from {from_number}: {body}")

    resp = MessagingResponse()

    if not body:
        resp.message("FuelWatch UK\nText your postcode to get fuel prices.\nExample: KT16 0DA\nOr: KT16 0DA diesel 10")
        return str(resp)

    if body.lower().startswith("tube"):
        resp.message(handle_tube_command(body))
        return str(resp)

    postcode, fuel, radius, retailer = parse_sms(body)

    if not postcode:
        resp.message(
            "FuelWatch UK\nCouldn't read that postcode.\n"
            "Try: KT16 0DA\nOr: KT16 0DA tesco diesel 10"
        )
        return str(resp)

    reply = search_and_format(postcode, fuel, radius, retailer)
    resp.message(reply)
    return str(resp)


