@app.route("/api/campaign/<brand>")
def api_campaign(brand):
    """API: Campaign data for a specific brand"""
    try:
        from supabase import create_client
        supabase = create_client(
            os.getenv("SUPABASE_URL", "https://uqwidlptkgmbxgaivafi.supabase.co"),
            os.getenv("SUPABASE_KEY", "sb_publishable_9aLorWl9R3jKAItspJstXQ_Fb47gOat")
        )

        # Get all creatives regardless of brand first
        all_creatives = supabase.table("campaign_creatives").select("*").execute().data or []
        creatives = [c for c in all_creatives if c.get("brand", "").lower() == brand.lower()]

        # Get sentiment data - filter by brand_name if available
        all_sentiment = supabase.table("campaign_sentiment").select("*").limit(100).execute().data or []
        brand_lower = brand.lower()

        # Try to filter by brand_name field first
        sentiment = [s for s in all_sentiment if s.get("brand_name", "").lower() == brand_lower][:10]

        # Fallback: filter by keywords if no brand_name field exists
        if not sentiment:
            brand_keywords = {
                "rexona": ["rexona", "fourth official", "pressure is visible", "added time", "brasil"],
                "sure": ["sure", "pressure makes you", "uk", "penalty", "pub"],
                "degree": ["degree", "do not sweat", "usa", "usmnt", "motion sense"],
            }
            keywords = brand_keywords.get(brand_lower, [brand_lower])
            for s in all_sentiment:
                text_lower = (s.get("text", "") + " " + s.get("author", "")).lower()
                if any(kw in text_lower for kw in keywords):
                    sentiment.append(s)
                    if len(sentiment) >= 10:
                        break

        # Last resort: return first 10
        if not sentiment:
            sentiment = all_sentiment[:10]

        all_metrics = supabase.table("campaign_metrics").select("*").execute().data or []
        metrics = [m for m in all_metrics if m.get("brand_variant", "").lower() == brand.lower()]

        all_variants = supabase.table("campaign_variants").select("*").execute().data or []
        variants = [v for v in all_variants if v.get("brand_name", "").lower() == brand.lower()]

        return jsonify({
            "creatives": creatives,
            "sentiment": sentiment,
            "metrics": metrics,
            "variants": variants,
            "debug": {"total_creatives": len(all_creatives), "brand_filter": brand}
        })
    except Exception as e:
        return jsonify({"error": str(e), "type": type(e).__name__}), 500

