@app.route("/brand/compare")
def brand_compare():
    """Compare 2-3 brands side by side"""
    brands_param = request.args.get("brands", "").strip()
    market = request.args.get("market", "UK").strip()

    if not brands_param:
        return render_template("intel_brand_phase1_tabbed.html", brand=None, skus=[])

    try:
        sb = lib._sb()
        brand_names = [b.strip() for b in brands_param.split(",")][:3]

        # Fetch all brand data
        brands_data = []
        category = None
        for brand_name in brand_names:
            result = sb.table("brand_phase1_intelligence").select("*").eq(
                "brand_name", brand_name
            ).eq("market_country", market).execute()

            if result.data:
                brand_data = result.data[0]
                brand_category = brand_data.get("category", "").strip().lower()

                # Ensure all brands in comparison are from same category
                if category is None:
                    category = brand_category
                    brands_data.append(brand_data)
                elif brand_category == category:
                    brands_data.append(brand_data)
                else:
                    app.logger.warning(f"[brand_compare] Skipping {brand_name}: category '{brand_category}' != '{category}'")

        if not brands_data or len(brands_data) < 2:
            return redirect(f"/brand/full?search={brand_names[0]}&market={market}")

        # Fetch market economics to get category-level data (market size, CAGR)
        market_econ = {}
        if category:
            try:
                econ_result = sb.table("brand_phase1_market_economics").select("*").eq(
                    "market_country", market
                ).eq("category", category).execute()
                if econ_result.data:
                    market_econ = econ_result.data[0]
            except Exception as econ_err:
                app.logger.warning(f"[brand_compare] Could not fetch market economics: {econ_err}")

        # Merge market economics into each brand for template access
        # Also calculate market entry scores for each brand
        for brand in brands_data:
            brand["market_size_millions"] = market_econ.get("category_market_size_usd_millions")
            brand["category_cagr_3yr"] = market_econ.get("category_cagr_3yr")

            # Calculate market entry scores
            try:
                scorer = MarketEntryScorer()
                score_result = scorer.score_market(
                    brand_name=brand.get("brand_name"),
                    market_country=market,
                    category=category,
                    brand_data={
                        "positioning_tier": brand.get("positioning_tier", "mass-market"),
                        "distribution_strategy": brand.get("distribution_strategy", "mass_market"),
                    },
                    market_data=market_econ,
                    competitive_data={
                        "competitive_intensity": market_econ.get("competitive_intensity", "medium"),
                        "direct_competitors": [
                            c for c in [
                                brand.get("direct_competitor_1"),
                                brand.get("direct_competitor_2"),
                                brand.get("direct_competitor_3")
                            ] if c
                        ],
                    },
                )
                brand["brand_strength_score"] = score_result.get("brand_strength_score", 5.0)
                brand["growth_opportunity_score"] = score_result.get("growth_opportunity_score", 5.0)
            except Exception as score_err:
                app.logger.warning(f"[brand_compare] Could not calculate scores for {brand.get('brand_name')}: {score_err}")
                brand["brand_strength_score"] = 5.0
                brand["growth_opportunity_score"] = 5.0

            # Fetch social media data
            try:
                social_result = sb.table("brand_social_media").select("*").eq(
                    "brand_name", brand.get("brand_name")
                ).execute()
                brand["social_media"] = social_result.data if social_result.data else []
            except Exception as social_err:
                app.logger.warning(f"[brand_compare] Could not fetch social for {brand.get('brand_name')}: {social_err}")
                brand["social_media"] = []

            # Fetch recent news/campaigns
            try:
                news_result = sb.table("brand_news").select("*").eq(
                    "brand_name", brand.get("brand_name")
                ).order("published_date", desc=True).limit(5).execute()
                brand["recent_news"] = news_result.data if news_result.data else []
            except Exception as news_err:
                app.logger.warning(f"[brand_compare] Could not fetch news for {brand.get('brand_name')}: {news_err}")
                brand["recent_news"] = []

        return render_template("intel_brand_compare.html",
                             brands=brands_data,
                             market=market,
                             comparison=True)
    except Exception as e:
        app.logger.error(f"Compare error: {str(e)}")
        if brand_names:
            return redirect(f"/brand/full?search={brand_names[0]}&market={market}")
        return redirect("/")


