@app.route("/brand/full")
def brand_full_intelligence():
    """Brand Intelligence page - Phase 1: Real Data Only"""
    search = request.args.get("search", "").strip()
    market = request.args.get("market", "UK").strip()

    if not search:
        return render_template("intel_brand_phase1_tabbed.html", brand=None, skus=[])

    try:
        sb = lib._sb()
        result = sb.table("brand_phase1_intelligence").select("*").eq(
            "brand_name", search
        ).eq(
            "market_country", market
        ).execute()

        # Initialize defaults
        competitors_list = []
        market_econ = {}
        market_entry_score = None

        if result.data:
            row = result.data[0]
            category = row.get("category", "").lower()

            # Fetch competitor data
            comp_names = [
                row.get("direct_competitor_1"),
                row.get("direct_competitor_2"),
                row.get("direct_competitor_3"),
            ]

            for comp_name in comp_names:
                if comp_name:
                    try:
                        comp_result = sb.table("brand_phase1_intelligence").select("*").eq(
                            "brand_name", comp_name
                        ).eq("market_country", market).execute()

                        if comp_result.data:
                            comp_row = comp_result.data[0]
                            # Only add if same category (prevents cross-category competitors)
                            if comp_row.get("category", "").lower() == row.get("category", "").lower():
                                your_price_usd = float(row.get("price_usd_equivalent", 0))
                                comp_price_usd = float(comp_row.get("price_usd_equivalent", 0))

                                price_delta = 0
                                if your_price_usd > 0:
                                    price_delta = round(((comp_price_usd - your_price_usd) / your_price_usd) * 100)

                                competitors_list.append({
                                    "name": comp_row.get("brand_name"),
                                    "positioning_tier": comp_row.get("positioning_tier", "").lower(),
                                    "currency": comp_row.get("price_currency"),
                                    "price": comp_row.get("price_local"),
                                    "price_usd": round(comp_price_usd, 2),
                                    "target_demographic": comp_row.get("target_demographic"),
                                    "distribution_strategy": comp_row.get("distribution_strategy", "").replace("_", " ").title(),
                                    "price_delta": price_delta,
                                })
                    except Exception as comp_err:
                        app.logger.warning(f"Could not fetch competitor {comp_name}: {comp_err}")
                        continue

            # Category-based typical SKU descriptions
            sku_map = {
                "skincare": "Bar Soap, Moisturizing Cream, or Facial Wash",
                "beverages": "330ml Can, 2L Bottle, or Multipak",
                "snacks": "Standard Pack (50-100g) or Multipack",
                "qsr": "Standard Meal or Individual Item",
                "beauty": "Makeup Set or Single Product",
            }
            typical_sku = sku_map.get(category, "Standard Product")

            # Transform to match template expectations
            brand = {
                "name": row.get("brand_name"),
                "description": row.get("positioning_summary"),
                "founded": row.get("founded_year"),
                "headquarters": f"{row.get('headquarters_city')}, {row.get('headquarters_country')}" if row.get('headquarters_city') else None,
                "website": row.get("official_website"),
                "parent_company": row.get("parent_company"),
                "category": category,
                "typical_sku": typical_sku,
                "positioning_tier": row.get("positioning_tier"),
                "tagline": row.get("brand_tagline"),
                "primary_benefit": row.get("primary_benefit"),
                "emotional_benefit": row.get("emotional_benefit"),
                "competitive_claim": row.get("competitive_claim"),
                "marketing_tone": row.get("marketing_tone"),
                "target_demographic": row.get("target_demographic"),
                "target_income_tier": row.get("target_income_tier"),
                "segment_size_millions": row.get("segment_size_millions"),
                "price_local": row.get("price_local"),
                "price_currency": row.get("price_currency"),
                "ppp_index": row.get("ppp_index"),
                "price_usd_equivalent": row.get("price_usd_equivalent"),
                "category_growth_cagr": row.get("category_growth_cagr_3yr"),
                "market_status": row.get("market_status"),
                "growth_driver": row.get("growth_driver"),
                "distribution_channels": row.get("distribution_channels", []),
                "distribution_strategy": row.get("distribution_strategy"),
                "marketing_channels": row.get("marketing_channels", []),
                "data_completeness": row.get("data_completeness"),
                "confidence_score": row.get("confidence_score"),
            }

            # Fetch market economics (Phase 2)
            try:
                econ_result = sb.table("brand_phase1_market_economics").select("*").eq(
                    "market_country", market
                ).eq(
                    "category", category
                ).execute()
                market_econ = econ_result.data[0] if econ_result.data else {}
            except Exception as econ_err:
                app.logger.warning(f"[brand_full] Could not fetch market economics: {econ_err}")
                market_econ = {}

            # Calculate market entry score (Phase 2)
            try:
                scorer = MarketEntryScorer()
                market_entry_score = scorer.score_market(
                    brand_name=search,
                    market_country=market,
                    category=category,
                    brand_data={
                        "positioning_tier": row.get("positioning_tier"),
                        "distribution_strategy": row.get("distribution_strategy"),
                    },
                    market_data=market_econ,
                    competitive_data={
                        "competitive_intensity": market_econ.get("competitive_intensity", "medium"),
                        "direct_competitors": [c["name"] for c in competitors_list],
                    },
                )
            except Exception as score_err:
                app.logger.warning(f"[brand_full] Could not calculate market entry score: {score_err}")
                market_entry_score = None

            # Deduplicate competitors (remove duplicates by name)
            seen_competitors = set()
            unique_competitors = []
            for comp in competitors_list:
                if comp["name"] not in seen_competitors:
                    seen_competitors.add(comp["name"])
                    unique_competitors.append(comp)

            # Fetch social media data
            social_media = []
            try:
                social_result = sb.table("brand_social_media").select("*").eq(
                    "brand_name", search
                ).execute()
                social_media = social_result.data if social_result.data else []
            except Exception as social_err:
                app.logger.warning(f"[brand_full] Could not fetch social for {search}: {social_err}")

            # Fetch recent news/campaigns
            news = []
            try:
                news_result = sb.table("brand_news").select("*").eq(
                    "brand_name", search
                ).order("published_date", desc=True).limit(5).execute()
                news = news_result.data if news_result.data else []
            except Exception as news_err:
                app.logger.warning(f"[brand_full] Could not fetch news for {search}: {news_err}")

            resp = make_response(render_template("intel_brand_phase1_tabbed.html", brand=brand, skus=[], market=market, market_econ=market_econ, competitors=unique_competitors, market_score=market_entry_score, social_media=social_media, brand_news=news))
        else:
            resp = make_response(render_template("intel_brand_phase1_tabbed.html", brand=None, skus=[], market=market, market_econ={}))
    except Exception as e:
        import traceback
        error_msg = f"[brand_full] EXCEPTION: {str(e)}\n{traceback.format_exc()}"
        app.logger.error(error_msg)
        print(error_msg)  # Also print to stdout
        resp = make_response(render_template("intel_brand_phase1_tabbed.html", brand=None, skus=[], market=market, market_econ={}))

    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0, private"
    return resp


@app.route("/api/brand/debug-full")
def brand_debug_full():
    """Debug endpoint - shows full flow"""
    search = request.args.get("search", "Dove").strip()
    market = request.args.get("market", "UK").strip()

    debug = {"search": search, "market": market, "steps": []}

    try:
        sb = lib._sb()

        # Step 1: Query
        debug["steps"].append({"step": "Query database", "status": "started"})
        result = sb.table("brand_phase1_intelligence").select("*").eq("brand_name", search).eq("market_country", market).execute()

        if not result.data:
            debug["steps"][-1]["status"] = "FAILED - no data found"
            return jsonify(debug)

        debug["steps"][-1]["status"] = f"SUCCESS - found {len(result.data)} records"
        row = result.data[0]

        # Step 2: Transform
        debug["steps"].append({"step": "Transform data", "status": "started"})
        category = row.get("category", "").lower()
        brand = {
            "name": row.get("brand_name"),
            "price_currency": row.get("price_currency"),
            "price_local": row.get("price_local"),
            "market_status": row.get("market_status"),
        }
        debug["steps"][-1]["status"] = f"SUCCESS - brand name: {brand.get('name')}"

        # Step 3: Competitors
        debug["steps"].append({"step": "Fetch competitors", "status": "started"})
        competitors_list = []
        comp_names = [row.get("direct_competitor_1"), row.get("direct_competitor_2"), row.get("direct_competitor_3")]
        for comp_name in comp_names:
            if comp_name:
                comp_result = sb.table("brand_phase1_intelligence").select("*").eq("brand_name", comp_name).eq("market_country", market).execute()
                if comp_result.data:
                    competitors_list.append({"name": comp_name, "found": True})
        debug["steps"][-1]["status"] = f"SUCCESS - found {len(competitors_list)} competitors"

        # Step 4: Market economics
        debug["steps"].append({"step": "Fetch market economics", "status": "started"})
        econ_result = sb.table("brand_phase1_market_economics").select("*").eq("market_country", market).eq("category", category).execute()
        market_econ = econ_result.data[0] if econ_result.data else None
        debug["steps"][-1]["status"] = f"SUCCESS - data found: {bool(market_econ)}"

        # Step 5: Scoring
        debug["steps"].append({"step": "Calculate score", "status": "started"})
        try:
            from scoring_engine import MarketEntryScorer
            scorer = MarketEntryScorer()
            score = scorer.score_market(search, market, category,
                {"positioning_tier": row.get("positioning_tier")},
                market_econ or {},
                {"competitive_intensity": "medium", "direct_competitors": [c["name"] for c in competitors_list]})
            debug["steps"][-1]["status"] = f"SUCCESS - score: {score.get('score')}/10"
        except Exception as score_err:
            debug["steps"][-1]["status"] = f"WARNING - {str(score_err)[:100]}"

        debug["final_status"] = "SUCCESS - All steps passed!"

    except Exception as e:
        import traceback
        debug["final_status"] = f"FAILED - {str(e)}"
        debug["traceback"] = traceback.format_exc()

    return jsonify(debug)


@app.route("/api/brands/search")
def brands_search():
    """Search for brands by name - returns matching brands for autocomplete"""
    query = request.args.get("q", "").strip().lower()

    if not query or len(query) < 1:
        return jsonify([])

    try:
        sb = lib._sb()
        # Get all unique brands
        result = sb.table("brand_phase1_intelligence").select("brand_name, category").execute()

        if not result.data:
            return jsonify([])

        # Get unique brands and filter by query
        brands_dict = {}
        for row in result.data:
            brand_name = row.get("brand_name")
            category = row.get("category")
            if brand_name.lower().startswith(query) or query in brand_name.lower():
                if brand_name not in brands_dict:
                    brands_dict[brand_name] = category

        # Return sorted list
        suggestions = [
            {"name": name, "category": cat}
            for name, cat in sorted(brands_dict.items())
        ]

        return jsonify(suggestions[:10])  # Max 10 suggestions

    except Exception as e:
        app.logger.error(f"[brands_search] Error: {e}")
        return jsonify([])


