@app.route("/api/geocode")
def api_geocode():
    """Proxy Nominatim place search — avoids browser User-Agent blocks."""
    q = request.args.get("q", "").strip()
    if not q:
        return jsonify({"results": []})
    try:
        r = requests.get(
            "https://nominatim.openstreetmap.org/search",
            params={"q": q + " UK", "format": "json", "limit": 5, "countrycodes": "gb", "addressdetails": 1},
            headers={"User-Agent": "Miru/1.0 (miru.humanagency.co)"},
            timeout=8,
        )
        places = r.json()
        results = [
            {
                "display": ", ".join(p["display_name"].split(",")[:3]),
                "lat": float(p["lat"]),
                "lon": float(p["lon"]),
                "type": p.get("type", ""),
            }
            for p in places
        ]
        return jsonify({"results": results})
    except Exception as e:
        return jsonify({"results": [], "error": str(e)})

@app.route("/api/commute/live")
def api_commute_live():
    """Drive time + traffic for a named destination. Uses Google Maps with live traffic."""
    from_q = request.args.get("from", "").strip()
    to_q   = request.args.get("to",   "").strip()
    if not from_q or not to_q:
        return jsonify({"error": "from and to required"}), 400

    from_geo = _geocode_place(from_q)
    to_geo   = _geocode_place(to_q)
    if not from_geo or not to_geo:
        return jsonify({"error": "Could not resolve one or both locations"}), 404

    key = os.environ.get("GOOGLE_DIRECTIONS_KEY") or os.environ.get("GOOGLE_API_KEY", "")
    if not key:
        return jsonify({"error": "not configured"}), 503

    try:
        r = requests.get(
            "https://maps.googleapis.com/maps/api/directions/json",
            params={
                "origin":        f"{from_geo[0]},{from_geo[1]}",
                "destination":   f"{to_geo[0]},{to_geo[1]}",
                "mode":          "driving",
                "departure_time":"now",
                "traffic_model": "best_guess",
                "key":           key,
            },
            timeout=10,
        )
        d = r.json()
        if d.get("status") != "OK":
            return jsonify({"error": f"Route not found: {d.get('status')}"}), 404

        leg = d["routes"][0]["legs"][0]
        dur_traffic = leg.get("duration_in_traffic", leg["duration"])["value"]
        dur_normal  = leg["duration"]["value"]
        delay       = max(0, dur_traffic - dur_normal)
        traffic     = "heavy" if delay > 600 else "moderate" if delay > 180 else "clear"
        traffic_emoji = "🔴" if traffic == "heavy" else "🟡" if traffic == "moderate" else "🟢"

        return jsonify({
            "duration_min":  dur_traffic // 60,
            "normal_min":    dur_normal  // 60,
            "delay_min":     delay       // 60,
            "traffic":       traffic,
            "traffic_emoji": traffic_emoji,
            "distance":      leg["distance"]["text"],
            "via":           d["routes"][0].get("summary", ""),
            "to_name":       to_geo[2],
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/commute")
def api_commute():
    """Compare train vs drive for a commute. Returns train departures + HERE drive time."""
    from_crs = request.args.get("from_crs", "").strip().upper()[:3]
    to_crs   = request.args.get("to_crs",   "").strip().upper()[:3]

    # Accept lat/lon directly (from frontend geocoding) or fallback to postcodes
    from_pc = to_pc = ""
    try:
        from_lat = float(request.args.get("from_lat", ""))
        from_lon = float(request.args.get("from_lon", ""))
        to_lat   = float(request.args.get("to_lat",   ""))
        to_lon   = float(request.args.get("to_lon",   ""))
    except (ValueError, TypeError):
        from_pc = request.args.get("from_pc", "").strip().replace(" ", "").upper()
        to_pc   = request.args.get("to_pc",   "").strip().replace(" ", "").upper()
        from_res = _resolve_postcode(from_pc)
        to_res   = _resolve_postcode(to_pc)
        if not from_res or not to_res:
            return jsonify({"error": "Could not resolve locations"}), 400
        _, from_lat, from_lon, _ = from_res
        _, to_lat,   to_lon,   _ = to_res

    import concurrent.futures as _cf_cm

    def _get_drive():
        here_key = os.environ.get("HERE_API_KEY", "")
        if not here_key:
            return {"error": "not_configured"}
        try:
            r = requests.get(
                "https://router.hereapi.com/v8/routes",
                params={
                    "transportMode": "car",
                    "origin": f"{from_lat},{from_lon}",
                    "destination": f"{to_lat},{to_lon}",
                    "return": "summary,typicalDuration",
                    "apikey": here_key,
                },
                timeout=12,
            )
            d = r.json()
            sec = d["routes"][0]["sections"][0]["summary"]
            duration_s  = sec.get("duration", 0)
            typical_s   = sec.get("typicalDuration", duration_s)
            length_m    = sec.get("length", 0)
            delay_s     = max(0, duration_s - typical_s)
            traffic_ok  = delay_s < 120
            return {
                "duration_min": round(duration_s / 60),
                "typical_min":  round(typical_s  / 60),
                "delay_min":    round(delay_s    / 60),
                "distance_km":  round(length_m   / 1000, 1),
                "traffic_ok":   traffic_ok,
            }
        except Exception as e:
            return {"error": str(e)}

    def _get_train():
        if not from_crs or not to_crs:
            return {"error": "no_stations"}
        try:
            access = _get_rtt_token()
            r = requests.get(
                "https://data.rtt.io/rtt/location",
                headers={"Authorization": f"Bearer {access}"},
                params={"code": f"gb-nr:{from_crs}", "calling_at": to_crs},
                timeout=12,
            )
            data = r.json()
            services = data.get("services") or []
            departures = []
            for s in services[:6]:
                loc = s.get("locationDetail", {})
                dep_b = loc.get("gbttBookedDeparture", "")
                dep_r = loc.get("realtimeDeparture", dep_b)
                plat  = loc.get("platform", "")
                cancelled = loc.get("cancelledDeparture", False) or loc.get("cancelledCall", False)
                def _fmt(t):
                    t = str(t).strip()
                    if len(t) == 4 and t.isdigit(): return t[:2] + ":" + t[2:]
                    return t[:5] if len(t) >= 5 else t
                dep_b = _fmt(dep_b); dep_r = _fmt(dep_r)
                late = 0
                try:
                    bh, bm = int(dep_b[:2]), int(dep_b[3:])
                    rh, rm = int(dep_r[:2]), int(dep_r[3:])
                    late = (rh*60+rm) - (bh*60+bm)
                except Exception: pass
                departures.append({
                    "dep": dep_b, "dep_rt": dep_r,
                    "late_min": late, "platform": plat,
                    "cancelled": bool(cancelled),
                    "operator": s.get("atocName", ""),
                })
            return {"departures": departures[:4], "from_name": data.get("location", {}).get("name", from_crs), "to_name": to_crs}
        except Exception as e:
            return {"error": str(e)}

    with _cf_cm.ThreadPoolExecutor(max_workers=2) as ex:
        fd = ex.submit(_get_drive)
        ft = ex.submit(_get_train)
        drive = fd.result()
        train = ft.result()

    return jsonify({"drive": drive, "train": train, "from_pc": from_pc, "to_pc": to_pc})


@app.route("/api/commute/save", methods=["POST"])
def api_commute_save():
    body      = request.get_json(force=True, silent=True) or {}
    device_id = (body.get("device_id") or "").strip()
    phone     = (body.get("phone") or "").strip()
    label     = (body.get("label") or "").strip()
    dest      = (body.get("dest") or "").strip()
    days      = (body.get("days") or "weekday").strip()  # weekday/weekend/all
    show_home = body.get("show_home", True)  # boolean
    time_start = (body.get("time_start") or "07:00").strip()  # HH:MM
    time_end = (body.get("time_end") or "08:30").strip()  # HH:MM
    if not device_id and not phone:
        return jsonify({"error": "device_id or phone required"}), 400
    if not dest:
        return jsonify({"error": "dest required"}), 400
    if not label:
        label = dest
    try:
        row = lib._sb().table("user_commutes").insert({
            "device_id": device_id or phone,
            "phone":     phone or None,
            "label":     label,
            "dest":      dest,
            "days":      days,
            "show_home": show_home,
            "time_start": time_start,
            "time_end": time_end,
        }).execute().data[0]
        # If phone now known, also claim any earlier device_id-only records
        if phone and device_id:
            lib._sb().table("user_commutes").update({"phone": phone}) \
              .eq("device_id", device_id).is_("phone", "null").execute()
        return jsonify({"ok": True, "id": row["id"]})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/commute/list")
def api_commute_list():
    device_id = request.args.get("device_id", "").strip()
    phone     = request.args.get("phone", "").strip()
    if not device_id and not phone:
        return jsonify({"error": "device_id or phone required"}), 400
    try:
        sb = lib._sb()
        if phone:
            # Claim any device_id-only records saved on this same device before phone was linked
            if device_id:
                sb.table("user_commutes").update({"phone": phone}) \
                  .eq("device_id", device_id).is_("phone", "null").execute()
            rows = sb.table("user_commutes").select("id,label,dest,created_at,show_on_homepage,time_start,time_end,days_of_week") \
                     .eq("phone", phone).order("created_at").execute().data
        else:
            rows = sb.table("user_commutes").select("id,label,dest,created_at,show_on_homepage,time_start,time_end,days_of_week") \
                     .eq("device_id", device_id).order("created_at").execute().data
        return jsonify({"commutes": rows})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/commute/update", methods=["POST"])
def api_commute_update():
    body = request.get_json(force=True, silent=True) or {}
    commute_id = body.get("id")
    if not commute_id:
        return jsonify({"error": "id required"}), 400
    try:
        update_data = {}
        # Update label if provided
        if body.get("label"):
            update_data["label"] = body.get("label").strip()
        # Update visibility and timing preferences
        if "show_on_homepage" in body:
            update_data["show_on_homepage"] = bool(body.get("show_on_homepage"))
        if "time_start" in body:
            update_data["time_start"] = body.get("time_start")  # HH:MM format
        if "time_end" in body:
            update_data["time_end"] = body.get("time_end")  # HH:MM format
        if "days_of_week" in body:
            # JSON array: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
            update_data["days_of_week"] = body.get("days_of_week")

        if not update_data:
            return jsonify({"error": "no fields to update"}), 400

        lib._sb().table("user_commutes").update(update_data).eq("id", commute_id).execute()
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/commute/active")
def api_commute_active():
    """Get commutes that should display now (show_on_homepage + matching time/day)."""
    device_id = request.args.get("device_id", "").strip()
    phone     = request.args.get("phone", "").strip()
    if not device_id and not phone:
        return jsonify({"error": "device_id or phone required"}), 400
    try:
        from datetime import datetime
        sb = lib._sb()
        if phone:
            rows = sb.table("user_commutes").select("id,label,dest,show_on_homepage,time_start,time_end,days_of_week") \
                     .eq("phone", phone).eq("show_on_homepage", True).execute().data or []
        else:
            rows = sb.table("user_commutes").select("id,label,dest,show_on_homepage,time_start,time_end,days_of_week") \
                     .eq("device_id", device_id).eq("show_on_homepage", True).execute().data or []

        # Filter by current day and time
        now = datetime.now()
        current_dow = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"][now.weekday()]
        current_time = now.strftime("%H:%M")

        active = []
        for row in rows:
            days = row.get("days_of_week") or ["Mon", "Tue", "Wed", "Thu", "Fri"]
            if current_dow not in days:
                continue
            time_start = row.get("time_start", "00:00")
            time_end = row.get("time_end", "23:59")
            if not (time_start <= current_time <= time_end):
                continue
            active.append(row)

        return jsonify({"commutes": active})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


