@app.route("/api/brands/list", methods=["GET"])
def api_brands_list():
    """Get all available brands by market"""
    try:
        sb = lib._sb()
        result = sb.table("brand_phase1_intelligence").select("brand_name, market_country").execute()

        brands_by_market = {}
        for row in result.data:
            market = row.get("market_country")
            brand = row.get("brand_name")
            if market not in brands_by_market:
                brands_by_market[market] = []
            if brand not in brands_by_market[market]:
                brands_by_market[market].append(brand)

        # Sort each market's brands
        for market in brands_by_market:
            brands_by_market[market] = sorted(brands_by_market[market])

        return jsonify({
            "markets": sorted(brands_by_market.keys()),
            "brands_by_market": brands_by_market,
            "total_brands": sum(len(b) for b in brands_by_market.values())
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/brand/insights", methods=["GET"])
def api_brand_insights():
    """Phase 2: Generate AI insights for a brand in a market using Groq"""
    brand_name = request.args.get("brand", "").strip()
    market = request.args.get("market", "UK").strip()

    if not brand_name:
        return jsonify({"error": "Brand name required"}), 400

    try:
        sb = lib._sb()
        scorer = MarketEntryScorer()
        optimizer = IntelGroqOptimizer()

        # Fetch brand data from brand_phase1_intelligence table
        brand_result = sb.table("brand_phase1_intelligence").select("*").eq(
            "brand_name", brand_name
        ).eq("market_country", market).execute()

        if not brand_result.data or len(brand_result.data) == 0:
            # Try to find similar brands for suggestions
            try:
                similar = sb.table("brand_phase1_intelligence").select("brand_name").eq(
                    "market_country", market
                ).ilike("brand_name", f"%{brand_name}%").limit(3).execute()

                suggestions = ""
                if similar.data:
                    brands = [b.get("brand_name") for b in similar.data]
                    suggestions = f" Similar: {', '.join(brands)}"

                return jsonify({"error": f"Brand '{brand_name}' not found in {market}.{suggestions}"}), 404
            except:
                return jsonify({"error": f"Brand '{brand_name}' not found in {market}"}), 404

        brand_row = brand_result.data[0]

        # Extract data for scoring
        brand_data = {
            "name": brand_row.get("brand_name"),
            "category": brand_row.get("category", "consumer_goods"),
            "positioning_tier": brand_row.get("positioning_tier", "mass_market"),
            "distribution_strategy": brand_row.get("distribution_strategy", "mass_market")
        }

        market_data = {
            "category_status": brand_row.get("market_status", "stable"),
            "category_cagr_3yr": float(brand_row.get("market_cagr_3yr", 3.0)),
            "category_market_size_usd_millions": float(brand_row.get("market_size_millions", 100)),
            "key_growth_drivers": brand_row.get("growth_drivers", "N/A"),
            "ppp_index": float(brand_row.get("ppp_index", 1.0)),
            "competitive_intensity": brand_row.get("competitive_intensity", "medium")
        }

        # Build competitive data from direct competitors
        competitor_names = [
            brand_row.get("direct_competitor_1"),
            brand_row.get("direct_competitor_2"),
            brand_row.get("direct_competitor_3")
        ]
        competitors = [c for c in competitor_names if c]

        competitive_data = {
            "direct_competitors": competitors,
            "competitive_intensity": market_data.get("competitive_intensity", "medium")
        }

        # Calculate scores
        category = brand_data.get("category", "consumer_goods")
        scores = scorer.score_market(
            brand_name,
            market,
            category,
            brand_data,
            market_data,
            competitive_data
        )

        # Generate insights using Groq (quick verdict only to respect 30 RPM free tier limit)
        insights_result = optimizer.get_quick_verdict_only(
            brand_name,
            market,
            {
                "brand_strength_score": scores.get("brand_strength_score", 5.0),
                "growth_opportunity_score": scores.get("growth_opportunity_score", 5.0)
            },
            {
                "category_status": market_data.get("category_status", "stable"),
                "category_cagr_3yr": market_data.get("category_cagr_3yr", 3.0),
                "category_market_size_usd_millions": market_data.get("category_market_size_usd_millions", 100),
                "key_growth_drivers": market_data.get("key_growth_drivers", "N/A")
            }
        )

        return jsonify({
            "brand": brand_name,
            "market": market,
            "scores": {
                "brand_strength": scores.get("brand_strength_score", 5.0),
                "growth_opportunity": scores.get("growth_opportunity_score", 5.0)
            },
            "insights": insights_result.get("insights", {}),
            "efficiency": insights_result.get("efficiency", "0% cached")
        })

    except Exception as e:
        app.logger.error(f"Insights error: {str(e)}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/brand/social")
def api_brand_social():
    name = request.args.get("name", "").strip()
    if not name or len(name) < 2:
        return jsonify({"error": "Brand name required"}), 400
    cache_key = f"brand_social:{name.lower()}|v3"
    try:
        cached = lib._sb().table("ai_cache").select("data").eq("key", cache_key).execute().data
        if cached and cached[0].get("data"):
            return jsonify(cached[0]["data"])
    except Exception:
        pass
    data = fetch_brand_social(name)
    if data.get("confidence") in ("high", "medium"):
        try:
            lib._sb().table("ai_cache").upsert({"key": cache_key, "data": data}).execute()
        except Exception:
            pass
    return jsonify(data)


@app.route("/api/brand/save-to-library", methods=["POST"])
def api_brand_save_to_library():
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        return jsonify({"error": "name required"}), 400
    sb_key = f"brand:{name.lower()}|brandv29"
    d = {}
    try:
        rows = lib._sb().table("ai_cache").select("data").eq("key", sb_key).execute().data
        if rows:
            d = rows[0]["data"] or {}
    except Exception:
        pass
    display_name = d.get("name") or name
    lines = [f"# 🏷️ {display_name} — Brand Profile"]
    if d.get("description") or d.get("extract"):
        lines.append(f"\n{(d.get('description') or d.get('extract',''))[:500]}")
    for label, key in [("Founded", "founded"), ("HQ", "hq"), ("Industry", "industry"), ("Revenue", "revenue")]:
        if d.get(key): lines.append(f"**{label}:** {d[key]}")
    tl = d.get("timeline") or []
    if tl:
        lines.append("\n## Timeline")
        for e in tl[:10]:
            lines.append(f"- **{e.get('year','')}** — {e.get('title','')}: {e.get('description','')}")
    camps = d.get("campaigns") or []
    if camps:
        lines.append("\n## Famous Campaigns")
        for c in camps[:8]:
            lines.append(f"- **{c.get('name','')}** ({c.get('year','')}): {c.get('description','')}")
    rivals = d.get("competitors") or []
    if rivals:
        lines.append("\n## Main Rivals")
        for r in rivals[:6]:
            lines.append(f"- **{r.get('name','')}**: {r.get('description','')}")
    news = d.get("news") or []
    if news:
        lines.append("\n## Recent News")
        for n in news[:5]:
            lines.append(f"- {n.get('title','')} ({n.get('date','')})")
    lines.append(f"\n---\n_Source: intel.humanagency.co · {display_name}_")
    try:
        doc = lib.upload_document(f"🏷️ {display_name}", "\n".join(lines), doc_type="note")
        return jsonify({"ok": True, "share_id": doc["share_id"]})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


