@app.route("/api/brand/standing")
def api_brand_standing():
    name = request.args.get("name", "").strip()
    if not name:
        return jsonify({"error": "name required"}), 400

    key = name.lower().strip()
    dcg = _DCG_2026.get(key)

    # Build context for AI verdict
    ranking_context = ""
    if dcg:
        move_label = f", {dcg['badge']} vs last year" if dcg["badge"] not in ("HELD", "NEW") else (", position held" if dcg["badge"] == "HELD" else ", new entry this year")
        ranking_context = f"Ranked #{dcg['rank']} in DCG Most Admired Brands in Digital Commerce 2026{move_label}. "

    groq_key = os.environ.get("GROQ_API_KEY", "")
    verdict = ""
    if groq_key:
        try:
            prompt = (
                f"{ranking_context}Brand: {name}. "
                f"Write one punchy sentence (max 15 words) on this brand's market standing. "
                f"Be specific and direct. No fluff. Examples: "
                f"'Global #1 in beauty with dominant digital shelf presence.' "
                f"'Rising challenger brand with strong Gen Z loyalty.' "
                f"'Household staple under pressure from private label competition.'"
            )
            r = requests.post(
                "https://api.groq.com/openai/v1/chat/completions",
                headers={"Authorization": f"Bearer {groq_key}", "Content-Type": "application/json"},
                json={
                    "model": "llama-3.1-8b-instant",
                    "messages": [{"role": "user", "content": prompt}],
                    "max_tokens": 60,
                    "temperature": 0.4,
                },
                timeout=8,
            )
            verdict = r.json()["choices"][0]["message"]["content"].strip().strip('"')
        except Exception:
            pass

    return jsonify({"name": name, "dcg": dcg, "verdict": verdict})


@app.route("/api/brand/ask", methods=["POST"])
def api_brand_ask():
    data = request.get_json(silent=True) or {}
    name     = (data.get("name")     or "").strip()
    question = (data.get("question") or "").strip()
    ctx      = data.get("context")   or {}
    if not name or not question:
        return jsonify({"error": "name and question required"}), 400

    desc      = (ctx.get("description") or ctx.get("extract") or "")[:300]
    timeline  = ctx.get("timeline")   or []
    campaigns = ctx.get("campaigns")  or []
    rivals    = ctx.get("competitors") or []
    tp        = ctx.get("trustpilot") or {}

    ctx_lines = [f"Brand: {name}"]
    if desc:      ctx_lines.append(f"About: {desc}")
    if timeline:  ctx_lines.append("History: " + " | ".join(f"{e.get('year','')} {e.get('title','')}" for e in timeline[:5]))
    if campaigns: ctx_lines.append("Famous campaigns: " + ", ".join(c.get("name","") for c in campaigns[:4]))
    if rivals:    ctx_lines.append("Main rivals: " + ", ".join(c.get("name","") for c in rivals[:5]))
    if tp.get("rating"): ctx_lines.append(f"Trustpilot: {tp['rating']}/5 ({tp.get('count',0):,} reviews)")

    try:
        answer = _groq_chat(
            f"You are a brand intelligence assistant. Answer questions about {name} in 2-3 sentences max. "
            f"Be specific and factual. Context:\n" + "\n".join(ctx_lines),
            [{"role": "user", "content": question}],
            max_tokens=220,
        )
        return jsonify({"answer": answer.strip()})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


