def _lookup_utility(pc_area: str, mapping: list, default: tuple) -> dict:
    for prefixes, name, phone, web in mapping:
        if pc_area in prefixes:
            return {"name": name, "emergency": phone, "website": web}
    n, p, w = default
    return {"name": n, "emergency": p, "website": w}

def _postcode_area(postcode: str) -> str:
    """Extract letter-only prefix e.g. 'SE' from 'SE135FH'."""
    import re as _re
    m = _re.match(r'^([A-Z]{1,2})', postcode.upper().replace(" ", ""))
    return m.group(1) if m else ""

def _fetch_gps_overpass(lat, lon, radius_m=3000):
    query = f"""[out:json][timeout:15];
(node["amenity"="doctors"](around:{radius_m},{lat},{lon});
 way["amenity"="doctors"](around:{radius_m},{lat},{lon});
 node["amenity"="clinic"](around:{radius_m},{lat},{lon});
 way["amenity"="clinic"](around:{radius_m},{lat},{lon}););
out center tags;"""
    try:
        els = _overpass_mirrors(query)
        items = []
        for e in els:
            tags = e.get("tags", {}); name = tags.get("name", "")
            if not name: continue
            elat, elon = _el_coords(e)
            if not elat: continue
            dist = round(haversine_km(lat, lon, elat, elon), 2)
            items.append({"name": name, "address": _el_address(tags),
                          "phone": _el_phone(tags), "distance_km": dist})
        items.sort(key=lambda x: x["distance_km"])
        return items[:5]
    except Exception: return []

def _fetch_amenity_overpass(lat, lon, amenity, radius_m=2000, limit=3):
    query = f"""[out:json][timeout:12];
(node["amenity"="{amenity}"](around:{radius_m},{lat},{lon});
 way["amenity"="{amenity}"](around:{radius_m},{lat},{lon}););
out center tags;"""
    try:
        els = _overpass_mirrors(query)
        items = []
        for e in els:
            tags = e.get("tags", {}); name = tags.get("name", amenity.replace("_", " ").title())
            elat, elon = _el_coords(e)
            if not elat: continue
            dist = round(haversine_km(lat, lon, elat, elon), 2)
            items.append({"name": name, "address": _el_address(tags),
                          "phone": _el_phone(tags), "distance_km": dist})
        items.sort(key=lambda x: x["distance_km"])
        return items[:limit]
    except Exception: return []

_your_area_cache: dict = {}
_YOUR_AREA_TTL = 86400  # 24 hours

@app.route("/api/your-area")
def api_your_area():
    postcode = request.args.get("postcode", "").strip().replace(" ", "").upper()
    if not postcode:
        return jsonify({"error": "Postcode required"}), 400
    cache_key = f"your-area:{postcode}"
    hit = _your_area_cache.get(cache_key)
    if hit and time.time() - hit["ts"] < _YOUR_AREA_TTL:
        return jsonify(hit["data"])
    try:
        lat, lon = _latlon_for_postcode(postcode)
        if lat is None:
            return jsonify({"error": "Postcode not found"}), 404

        # Postcode metadata from postcodes.io
        pc_info = {}
        try:
            r = requests.get(f"https://api.postcodes.io/postcodes/{postcode}", timeout=5)
            if r.status_code == 200:
                pc_info = r.json().get("result", {})
        except Exception: pass

        council_name    = pc_info.get("admin_district", "")
        council_website = ""
        if council_name:
            slug = council_name.lower().replace(" ", "").replace("london borough of", "").replace("city of", "").strip()
            council_website = f"https://www.{slug}.gov.uk"

        pc_area = _postcode_area(postcode)
        water = _lookup_utility(pc_area, _WATER_MAP, ("Thames Water", "0800 316 9800", "thameswater.co.uk"))
        gas   = _lookup_utility(pc_area, _GAS_MAP, _CADENT_DEFAULT)

        with ThreadPoolExecutor(max_workers=3) as ex:
            gps_f      = ex.submit(_fetch_gps_overpass, lat, lon)
            pharmacy_f = ex.submit(_fetch_amenity_overpass, lat, lon, "pharmacy", 1500, 3)
            postoff_f  = ex.submit(_fetch_amenity_overpass, lat, lon, "post_office", 2000, 2)
            gps        = gps_f.result(timeout=18)
            pharmacies = pharmacy_f.result(timeout=18)
            post_offices = postoff_f.result(timeout=18)

        result = {
            "council":      {"name": council_name, "website": council_website},
            "water":        water,
            "gas":          gas,
            "gps":          gps,
            "pharmacies":   pharmacies,
            "post_offices": post_offices,
        }
        if council_name and any([gps, pharmacies, post_offices]):
            _your_area_cache[cache_key] = {"data": result, "ts": time.time()}
        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


_env_cache: dict = {}
_ENV_TTL = 24 * 3600

import math as _math

def _env_dist_m(lat, lon, clat, clon):
    dlat = _math.radians(clat - lat)
    dlon = _math.radians(clon - lon)
    a = _math.sin(dlat/2)**2 + _math.cos(_math.radians(lat))*_math.cos(_math.radians(clat))*_math.sin(dlon/2)**2
    return int(6371000 * 2 * _math.asin(_math.sqrt(a)))

@app.route("/api/environment")
def api_environment():
    postcode = request.args.get("postcode", "").strip().replace(" ", "").upper()
    if not postcode:
        return jsonify({"error": "Postcode required"}), 400

    # Cache key versioned so query expansions invalidate stale entries
    _cache_key = postcode + "_v6"

    # Check Supabase cache first (shared across all users)
    try:
        row = lib._sb().table("env_cache").select("data").eq("postcode", _cache_key).maybe_single().execute()
        if row and row.data:
            return jsonify(row.data["data"])
    except Exception:
        pass

    hit = _env_cache.get(_cache_key)
    if hit and time.time() - hit["ts"] < _ENV_TTL:
        return jsonify(hit["data"])

    try:
        lat, lon = _latlon_for_postcode(postcode)
        if lat is None:
            return jsonify({"error": "Postcode not found"}), 404

        def _flood_risk():
            try:
                # 0.5km radius — only flag if the postcode itself is genuinely in or adjacent to a flood zone.
                # Wider radii pick up river floodplains that don't affect the street at all.
                r = requests.get(
                    "https://environment.data.gov.uk/flood-monitoring/id/floodAreas",
                    params={"lat": lat, "long": lon, "dist": 0.5},
                    timeout=8, headers={"User-Agent": "MiruApp/1.0"}
                )
                items = r.json().get("items", [])
                if not items:
                    return {"level": "low", "label": "Low flood risk", "areas": []}
                labels = [a.get("description") or a.get("label") or "" for a in items[:3]]
                severity = max((a.get("currentWarning", {}).get("severityLevel", 4) for a in items), default=4)
                level = "high" if severity <= 2 else "medium"
                return {"level": level, "label": f"Flood alert zone within 500m ({len(items)} zone{'s' if len(items)>1 else ''})", "areas": labels}
            except Exception:
                return {"level": "unknown", "label": "Flood data unavailable", "areas": []}

        def _osm_combined():
            # Single Overpass query for all three types — 3x faster than separate calls
            # Green space radius 1500m to catch large parks whose centre may be farther out
            q = (
                f'[out:json][timeout:25];('
                f'way["landuse"="industrial"](around:1000,{lat},{lon});'
                f'relation["landuse"="industrial"](around:1000,{lat},{lon});'
                f'way["natural"="water"](around:600,{lat},{lon});'
                f'relation["natural"="water"](around:600,{lat},{lon});'
                f'way["leisure"="park"](around:1500,{lat},{lon});'
                f'relation["leisure"="park"](around:1500,{lat},{lon});'
                f'way["landuse"="park"](around:1500,{lat},{lon});'
                f'relation["landuse"="park"](around:1500,{lat},{lon});'
                f'way["leisure"="garden"]["access"!="private"](around:1500,{lat},{lon});'
                f'relation["leisure"="garden"]["access"!="private"](around:1500,{lat},{lon});'
                f'way["leisure"="nature_reserve"](around:1500,{lat},{lon});'
                f'relation["leisure"="nature_reserve"](around:1500,{lat},{lon});'
                f'way["leisure"="recreation_ground"](around:1500,{lat},{lon});'
                f'relation["leisure"="recreation_ground"](around:1500,{lat},{lon});'
                f'way["leisure"="common"](around:1500,{lat},{lon});'
                f'relation["leisure"="common"](around:1500,{lat},{lon});'
                f'way["landuse"="forest"](around:1500,{lat},{lon});'
                f'relation["landuse"="forest"](around:1500,{lat},{lon});'
                f'way["natural"="wood"](around:1500,{lat},{lon});'
                f'relation["natural"="wood"](around:1500,{lat},{lon});'
                f');out center tags 60;'
            )
            els = _overpass_query(q, timeout=25)
            industrial, water, green = [], [], []
            _green_seen = set()
            _GREEN_TAGS = {"park", "nature_reserve", "recreation_ground", "common", "garden"}
            _GREEN_FALLBACK = {
                "park": "Park", "nature_reserve": "Nature Reserve",
                "recreation_ground": "Recreation Ground", "common": "Common",
                "forest": "Forest", "wood": "Woodland", "garden": "Public Garden",
            }
            for e in els:
                tags = e.get("tags", {})
                name = tags.get("name") or tags.get("operator") or ""
                c = e.get("center") or {}
                dist_m = _env_dist_m(lat, lon, c["lat"], c["lon"]) if c.get("lat") else None
                item = {"name": name, "dist_m": dist_m}
                if tags.get("landuse") == "industrial" and name:
                    industrial.append(item)
                elif tags.get("natural") == "water":
                    # Use OSM water type as descriptive fallback (canal, river, lake, pond, reservoir, drain)
                    _WATER_TYPES = {
                        "canal": "Canal", "river": "River", "lake": "Lake",
                        "pond": "Pond", "reservoir": "Reservoir", "drain": "Drain",
                        "ditch": "Ditch", "stream": "Stream", "lagoon": "Lagoon",
                        "moat": "Moat", "oxbow": "Oxbow Lake",
                    }
                    water_type = tags.get("water", "")
                    display_name = name or _WATER_TYPES.get(water_type, "")
                    if display_name:
                        water.append({"name": display_name, "dist_m": dist_m})
                else:
                    leisure = tags.get("leisure", "")
                    landuse = tags.get("landuse", "")
                    natural = tags.get("natural", "")
                    is_green = (
                        leisure in _GREEN_TAGS or
                        landuse in {"forest", "park"} or
                        natural == "wood"
                    )
                    if is_green:
                        kind = leisure or landuse or natural
                        display = name or _GREEN_FALLBACK.get(kind, "Green Space")
                        key = display.lower()
                        if key not in _green_seen:
                            _green_seen.add(key)
                            green.append({"name": display, "dist_m": dist_m})
            def _sort_dedup(lst):
                seen = set()
                out = []
                for item in sorted(lst, key=lambda x: x.get("dist_m") or 9999):
                    key = item["name"].lower()
                    if key not in seen:
                        seen.add(key)
                        out.append(item)
                    if len(out) >= 5:
                        break
                return out
            return _sort_dedup(industrial), _sort_dedup(water), _sort_dedup(green)

        with ThreadPoolExecutor(max_workers=2) as ex:
            flood_f = ex.submit(_flood_risk)
            osm_f   = ex.submit(_osm_combined)

        industrial, water, green = osm_f.result(timeout=40)
        result = {
            "flood":      flood_f.result(timeout=12),
            "industrial": industrial,
            "water":      water,
            "green":      green,
            "lat":        lat,
            "lon":        lon,
        }
        _env_cache[_cache_key] = {"data": result, "ts": time.time()}
        # Persist to Supabase so next user gets it instantly
        try:
            lib._sb().table("env_cache").upsert({"postcode": _cache_key, "data": result}).execute()
        except Exception:
            pass
        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/area/watch", methods=["POST"])
def api_area_watch():
    data = request.get_json() or {}
    postcode = data.get("postcode", "").strip().replace(" ", "").upper()
    if not postcode:
        return jsonify({"error": "Postcode required"}), 400
    phone = (data.get("phone") or "").strip() or None
    device_id = (data.get("device_id") or "").strip() or None
    try:
        lib._sb().table("watched_postcodes").insert(
            {"postcode": postcode, "phone": phone, "device_id": device_id}
        ).execute()
        return jsonify({"ok": True})
    except Exception as e:
        # Duplicate is fine — already watching
        if "duplicate" in str(e).lower() or "unique" in str(e).lower():
            return jsonify({"ok": True})
        return jsonify({"error": str(e)}), 500


_summary_cache: dict = {}
_SUMMARY_TTL = 24 * 3600

_FAMOUS_CACHE: dict = {}
_FAMOUS_TTL = 3600  # 1 hour — stable facts, no need to refresh often

@app.route("/api/area/famous")
def api_area_famous():
    area = request.args.get("area", "").strip()
    if not area or len(area) < 2:
        return jsonify({"famous": ""})
    key = area.lower()
    cached = _FAMOUS_CACHE.get(key)
    if cached and time.time() - cached[1] < _FAMOUS_TTL:
        return jsonify({"famous": cached[0]})
    try:
        r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {os.environ.get('GROQ_API_KEY', '')}",
                     "Content-Type": "application/json"},
            json={"model": "llama-3.1-8b-instant", "max_tokens": 60, "temperature": 0.2,
                  "messages": [{"role": "user", "content":
                    f"What is {area}, UK known for? Give 2-3 items separated by · (middle dot). "
                    f"Each item max 8 words. No intro, no quotes, no full sentences. "
                    f"Example for Windsor: Royal castle · Home of Eton College · Great Park"}]},
            timeout=6,
        )
        text = r.json()["choices"][0]["message"]["content"].strip()
        # Strip any preamble the model added
        if "·" in text:
            text = " · ".join(p.strip().strip(".,") for p in text.split("·") if p.strip())
        _FAMOUS_CACHE[key] = (text, time.time())
        return jsonify({"famous": text})
    except Exception:
        return jsonify({"famous": ""})


@app.route("/api/area-summary")
def api_area_summary():
    postcode = request.args.get("postcode", "").strip().replace(" ", "").upper()
    if not postcode:
        return jsonify({"error": "Postcode required"}), 400

    hit = _summary_cache.get(postcode + "_v5")
    if hit and time.time() - hit["ts"] < _SUMMARY_TTL:
        return jsonify(hit["data"])
    try:
        row = lib._sb().table("area_summary_cache").select("summary").eq("postcode", postcode + "_v5").maybe_single().execute()
        if row and row.data:
            return jsonify({"summary": row.data["summary"]})
    except Exception:
        pass

    try:
        lat, lon = _latlon_for_postcode(postcode)
        if lat is None:
            return jsonify({"error": "Postcode not found"}), 404

        # Collect data in parallel
        from search import fetch_crime_data, fetch_house_prices
        with ThreadPoolExecutor(max_workers=3) as ex:
            crime_f  = ex.submit(fetch_crime_data, lat, lon)
            house_f  = ex.submit(fetch_house_prices, postcode)
            env_f    = ex.submit(lambda: _summary_cache.get(f"_env_{postcode}"))

        crime = crime_f.result(timeout=15) or {}
        house = house_f.result(timeout=15) or {}
        env_row = None
        try:
            er = lib._sb().table("env_cache").select("data").eq("postcode", postcode + "_v5").maybe_single().execute()
            env_row = er.data["data"] if er and er.data else None
        except Exception:
            pass

        # Build facts string
        total_crime = crime.get("per_month") or crime.get("total_crimes") or crime.get("total") or 0
        crime_level = crime.get("level") or ("low" if total_crime < 50 else "moderate" if total_crime < 150 else "high")
        top_crime = (crime.get("breakdown") or crime.get("categories") or [{}])[0].get("category", "") if (crime.get("breakdown") or crime.get("categories")) else ""

        hp = house.get("house_prices") or house
        avg_price = None
        for pt in ["detached", "semi_detached", "terraced", "flat"]:
            v = (hp.get(pt) or {}).get("avg")
            if v:
                avg_price = v
                break

        flood = (env_row or {}).get("flood", {})
        flood_level = flood.get("level", "unknown")
        green_count = len((env_row or {}).get("green", []))
        industrial_count = len((env_row or {}).get("industrial", []))

        flood_label = flood.get("label", "")
        flood_sentence = (
            f"Flood risk: {flood_level} ({flood_label}). "
            if flood_level not in ("low", "unknown")
            else "Flood risk: low — no flood alert zones within 500m. "
        )

        facts = (
            f"Postcode: {postcode}. "
            f"Crime level: {crime_level} ({total_crime} incidents/month{', top type: ' + top_crime if top_crime else ''}). "
            f"{flood_sentence}"
            f"{'Average property price: £' + f'{avg_price:,.0f}' + '. ' if avg_price else ''}"
            f"{'Green spaces nearby: ' + str(green_count) + '. ' if green_count else 'No named parks nearby. '}"
            f"{'Industrial sites nearby: ' + str(industrial_count) + '. ' if industrial_count else 'No industrial land nearby. '}"
        )

        groq_key = os.environ.get("GROQ_API_KEY", "")
        if not groq_key:
            return jsonify({"error": "AI not configured"}), 503

        r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {groq_key}", "Content-Type": "application/json"},
            json={
                "model": "llama-3.1-8b-instant",
                "messages": [
                    {"role": "system", "content": (
                        "You are a UK property analyst. Write a 2-3 sentence plain English verdict based SOLELY on the facts provided. "
                        "CRITICAL: Do NOT use your own knowledge about the location, geography, or flood plains. "
                        "If the facts say flood risk is low, it is low — do not contradict this. "
                        "Only mention flood risk if the facts explicitly say medium or high. "
                        "Be proportionate: if crime is low and flood risk is low, lead with that positively. "
                        "IMPORTANT: If average property price is above £500,000, the market is clearly signalling strong demand — "
                        "this area is sought-after and desirable. In that case, even if crime is moderate or high, "
                        "lead with the desirability and price signal, then note crime as context, not as a red flag. "
                        "High prices and high crime often coexist in prime urban areas — do not frame this as a contradiction. "
                        "No bullet points, no headers. Plain flowing sentences only."
                    )},
                    {"role": "user", "content": f"Give a verdict on {postcode} based only on these facts (ignore any geographic knowledge you have): {facts}"}
                ],
                "max_tokens": 150,
                "temperature": 0.3,
            },
            timeout=10,
        )
        summary = r.json()["choices"][0]["message"]["content"].strip()
        result = {"summary": summary, "facts": facts}
        _summary_cache[postcode + "_v5"] = {"data": result, "ts": time.time()}
        try:
            lib._sb().table("area_summary_cache").upsert({"postcode": postcode + "_v5", "summary": summary}).execute()
        except Exception:
            pass
        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/services")
def api_services():
    postcode = request.args.get("postcode", "").strip().replace(" ", "").upper()
    debug    = request.args.get("debug") == "1"
    if not postcode:
        return jsonify({"error": "Postcode required"}), 400
    try:
        cache_key = f"services:{postcode}"
        hit = _services_cache.get(cache_key)
        if hit and time.time() - hit["ts"] < _SERVICES_TTL and not debug:
            return jsonify(hit["data"])
        lat, lon = _latlon_for_postcode(postcode)
        if lat is None:
            return jsonify({"error": "Postcode not found"}), 404
        if debug:
            # Raw Overpass test — bypass everything
            q = (f"[out:json][timeout:18];"
                 f"(node[amenity=hospital](around:15000,{lat},{lon});"
                 f"way[amenity=hospital](around:15000,{lat},{lon}););"
                 f"out tags center 30;")
            debug_results = {}
            for url in _OVERPASS_URLS:
                try:
                    r = requests.post(url, data={"data": q}, timeout=18)
                    debug_results[url] = {"status": r.status_code, "elements": len(r.json().get("elements", [])) if r.status_code == 200 else 0}
                except Exception as e:
                    debug_results[url] = {"error": str(e)}
            return jsonify({"lat": lat, "lon": lon, "overpass": debug_results})
        with ThreadPoolExecutor(max_workers=2) as ex:
            f_h = ex.submit(_fetch_hospitals, lat, lon)
            f_p = ex.submit(_fetch_police_contact, lat, lon)
            hospitals = f_h.result()
            police    = f_p.result()
        result = {"hospitals": hospitals, "police": police}
        if hospitals:  # only cache if we got results
            _services_cache[cache_key] = {"data": result, "ts": time.time()}
        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/shops")
def api_shops():
    postcode = request.args.get("postcode", "").strip().replace(" ", "").upper()
    debug    = request.args.get("debug") == "1"
    if not postcode:
        return jsonify({"error": "Postcode required"}), 400
    try:
        cache_key = f"shops:{postcode}"
        hit = _services_cache.get(cache_key)
        if hit and time.time() - hit["ts"] < _SERVICES_TTL and not debug:
            return jsonify(hit["data"])
        lat, lon = _latlon_for_postcode(postcode)
        if lat is None:
            return jsonify({"error": "Postcode not found"}), 404
        if debug:
            # Full query including relations — same as production
            q = f"""[out:json][timeout:25];
(node["shop"="supermarket"](around:5000,{lat},{lon});
way["shop"="supermarket"](around:5000,{lat},{lon});
relation["shop"="supermarket"](around:5000,{lat},{lon});
);out center tags;"""
            dbg = {"lat": lat, "lon": lon, "overpass_urls": {}}
            for url in _OVERPASS_URLS:
                try:
                    r = requests.post(url, data={"data": q}, timeout=20)
                    els = r.json().get("elements", []) if r.status_code == 200 else []
                    # sort by distance so sample shows nearest first
                    def _d(e):
                        c = e.get("center") or {}
                        lt = e.get("lat") or c.get("lat") or 0
                        ln = e.get("lon") or c.get("lon") or 0
                        return haversine_km(lat, lon, lt, ln) if lt else 999
                    els_sorted = sorted(els, key=_d)
                    names = [(e.get("tags", {}).get("name", "?"), e.get("type"), round(_d(e)*1000)) for e in els_sorted[:15]]
                    dbg["overpass_urls"][url] = {"status": r.status_code, "count": len(els), "nearest_15": names}
                except Exception as e:
                    dbg["overpass_urls"][url] = {"error": str(e)}
            # Also show what Google Places returns
            gp = _places_nearby(lat, lon, "supermarket", 10000, 15)
            dbg["google_places"] = [{"name": p["name"], "dist_m": int(p["distance_km"]*1000)} for p in gp]
            dbg["merged_final"] = [{"name": s["name"], "dist_m": int(s.get("distance_km",0)*1000)} for s in _fetch_supermarkets(lat, lon)]
            return jsonify(dbg)
        with ThreadPoolExecutor(max_workers=3) as ex:
            sm_f   = ex.submit(_fetch_supermarkets, lat, lon)
            offl_f = ex.submit(_places_nearby, lat, lon, "liquor_store", 5000, 5)
            conv_f = ex.submit(_places_nearby, lat, lon, "convenience_store", 3000, 5)
            supermarkets = sm_f.result(timeout=12)
            off_licences_raw = offl_f.result(timeout=12)
            convenience_raw  = conv_f.result(timeout=12)
        off_licences = [{"name": p["name"], "address": p.get("address",""), "distance_km": p.get("distance_km",0), "phone": "", "opening_hours": ""} for p in off_licences_raw]
        convenience  = [{"name": p["name"], "address": p.get("address",""), "distance_km": p.get("distance_km",0), "phone": "", "opening_hours": ""} for p in convenience_raw]
        result = {"supermarkets": supermarkets, "off_licences": off_licences,
                  "convenience": convenience}
        if supermarkets or off_licences or convenience:
            _services_cache[cache_key] = {"data": result, "ts": time.time()}
        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/myarea/places", methods=["GET"])
def api_myarea_places_get():
    from_number = request.args.get("from_number", "").strip()
    device_id   = request.args.get("device_id", "").strip()
    if not from_number and not device_id:
        return jsonify([])
    try:
        q = lib._sb().table("my_area_places") \
            .select("id,name,address,phone,emoji,category,postcode,opening_hours") \
            .neq("category", "_home") \
            .order("created_at", desc=False)
        q = q.eq("from_number", from_number) if from_number else q.eq("device_id", device_id)
        return jsonify(q.execute().data or [])
    except Exception:
        return jsonify([])  # graceful — localStorage is primary store


@app.route("/api/myarea/places", methods=["POST"])
def api_myarea_places_post():
    from_number = request.args.get("from_number", "").strip()
    device_id   = request.args.get("device_id", "").strip()
    if not from_number and not device_id:
        return jsonify({"error": "from_number or device_id required"}), 400
    body = request.get_json(force=True, silent=True) or {}
    name = (body.get("name") or "").strip()
    if not name:
        return jsonify({"error": "name required"}), 400
    record = {
        "device_id":     from_number or device_id,
        "name":          name,
        "address":       (body.get("address") or "").strip(),
        "phone":         (body.get("phone") or "").strip(),
        "emoji":         (body.get("emoji") or "📍").strip(),
        "category":      (body.get("category") or "place").strip(),
        "postcode":      (body.get("postcode") or "").strip(),
        "opening_hours": (body.get("opening_hours") or "").strip()[:200],
    }
    if from_number:
        record["from_number"] = from_number
    try:
        row = lib._sb().table("my_area_places").insert(record).execute().data[0]
        return jsonify(row)
    except Exception:
        record.pop("from_number", None)
        try:
            row = lib._sb().table("my_area_places").insert(record).execute().data[0]
            return jsonify(row)
        except Exception as e:
            return jsonify({"error": str(e)}), 500


@app.route("/api/myarea/places/<place_id>", methods=["DELETE"])
def api_myarea_places_delete(place_id):
    from_number = request.args.get("from_number", "").strip()
    device_id   = request.args.get("device_id", "").strip()
    if not from_number and not device_id:
        return jsonify({"error": "from_number or device_id required"}), 400
    try:
        sb = lib._sb()
        if from_number:
            try:
                sb.table("my_area_places").delete().eq("id", place_id).eq("from_number", from_number).execute()
            except Exception:
                sb.table("my_area_places").delete().eq("id", place_id).execute()
        else:
            sb.table("my_area_places").delete().eq("id", place_id).eq("device_id", device_id).execute()
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/myarea/places/<place_id>", methods=["PATCH"])
def api_myarea_places_patch(place_id):
    from_number = request.args.get("from_number", "").strip()
    device_id   = request.args.get("device_id", "").strip()
    if not from_number and not device_id:
        return jsonify({"error": "from_number or device_id required"}), 400
    body = request.get_json(force=True, silent=True) or {}
    allowed = ("address", "phone", "opening_hours", "name")
    updates = {k: v for k, v in body.items() if k in allowed}
    if not updates:
        return jsonify({"error": "nothing to update"}), 400
    try:
        sb = lib._sb()
        q = sb.table("my_area_places").update(updates).eq("id", place_id)
        if from_number:
            q = q.eq("from_number", from_number)
        else:
            q = q.eq("device_id", device_id)
        result = q.execute()
        return jsonify({"ok": True, "updated": result.data})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/myarea/place-search", methods=["GET"])
def api_myarea_place_search():
    """Search for places and return address + phone for autocomplete."""
    query = request.args.get("q", "").strip()
    if not query or len(query) < 2:
        return jsonify([])

    results = []

    # Try Google Places if key is set
    if _GOOGLE_PLACES_KEY:
        try:
            ts = requests.get(
                "https://maps.googleapis.com/maps/api/place/textsearch/json",
                params={"query": query + " UK", "key": _GOOGLE_PLACES_KEY, "region": "uk"},
                timeout=8,
            )
            for p in ts.json().get("results", [])[:5]:
                place_id = p.get("place_id")
                if not place_id:
                    continue
                det = requests.get(
                    "https://maps.googleapis.com/maps/api/place/details/json",
                    params={
                        "place_id": place_id,
                        "fields": "name,formatted_address,international_phone_number",
                        "key": _GOOGLE_PLACES_KEY,
                    },
                    timeout=8,
                )
                detail = det.json().get("result", {})
                results.append({
                    "name": detail.get("name", ""),
                    "address": detail.get("formatted_address", ""),
                    "phone": detail.get("international_phone_number", ""),
                })
            if results:
                return jsonify(results)
        except Exception:
            pass

    # Fallback to Nominatim (free, no API key needed)
    try:
        nom = requests.get(
            "https://nominatim.openstreetmap.org/search",
            params={"q": query + " UK", "format": "json", "limit": 5, "countrycodes": "gb"},
            headers={"User-Agent": "Miru/1.0 (miru.humanagency.co)"},
            timeout=8,
        )
        for p in nom.json():
            results.append({
                "name": p.get("name", "") or ", ".join(p.get("display_name", "").split(",")[:2]),
                "address": p.get("display_name", ""),
                "phone": "",
            })
    except Exception:
        pass

    return jsonify(results)


