@app.route("/api/intel/compare")
def api_intel_compare():
    """Side-by-side brand/company comparison powered by Groq."""
    import concurrent.futures as _cf, json as _json, re as _re
    a = request.args.get("a", "").strip()
    b = request.args.get("b", "").strip()
    mode = request.args.get("mode", "brand")  # brand | company
    if not a or not b:
        return jsonify({"error": "a and b required"}), 400

    # Fetch both in parallel using existing data functions
    with _cf.ThreadPoolExecutor(max_workers=2) as ex:
        if mode == "company":
            fa = ex.submit(fetch_company_info, a)
            fb = ex.submit(fetch_company_info, b)
        else:
            fa = ex.submit(fetch_brand_data, a)
            fb = ex.submit(fetch_brand_data, b)
        da = fa.result()
        db = fb.result()

    def _summary(d, name):
        if mode == "company":
            w = d.get("wiki") or {}
            return (f"Name: {d.get('name') or name}\n"
                    f"Industry: {w.get('industry','')}\n"
                    f"Founded: {w.get('founded','')}\n"
                    f"HQ: {w.get('hq','')}\n"
                    f"Revenue: {w.get('revenue','')}\n"
                    f"Employees: {w.get('employees','')}\n"
                    f"Overview: {(w.get('extract') or '')[:400]}")
        else:
            return (f"Name: {d.get('name') or name}\n"
                    f"Founded: {d.get('founded','')}\n"
                    f"HQ: {d.get('hq','')}\n"
                    f"Revenue: {d.get('revenue','')}\n"
                    f"Slogan: {d.get('slogan','')}\n"
                    f"Description: {(d.get('description') or '')[:300]}\n"
                    f"Competitors: {', '.join(c.get('name', str(c)) if isinstance(c, dict) else str(c) for c in (d.get('competitors') or [])[:5])}")

    a_label = da.get("name") or a
    b_label = db.get("name") or b
    prompt = (
        f"Compare {a_label} vs {b_label} for a sharp business intelligence card.\n\n"
        f"--- {a_label} ---\n{_summary(da, a)}\n\n"
        f"--- {b_label} ---\n{_summary(db, b)}\n\n"
        "Instructions:\n"
        "1. Pick 5 dimensions that reveal the most MEANINGFUL strategic differences between these specific companies. "
        "Avoid generic labels like 'Founded' or 'Parent Company'. "
        "Good dimensions: Market Leadership, Customer Loyalty, Profit Margin, Innovation Pace, Brand Recognition, "
        "Pricing Power, Digital Presence, Operational Scale, Geographic Reach, Category Ownership.\n"
        "2. If they operate in different sectors, call it out — the comparison is then about business strength, not direct competition.\n"
        "3. Verdict must be opinionated: state who is strategically stronger IN THEIR OWN CONTEXT, not just who has higher revenue.\n"
        f"4. In every 'a' field put data about {a_label}. In every 'b' field put data about {b_label}.\n"
        "Return JSON only — exactly 5 dimensions:\n"
        '{"verdict":"one punchy sentence — clear winner in context, note if different sectors",'
        '"dimensions":['
        '{"label":"<dimension 1>","a":"<concise value>","b":"<concise value>"},'
        '{"label":"<dimension 2>","a":"<concise value>","b":"<concise value>"},'
        '{"label":"<dimension 3>","a":"<concise value>","b":"<concise value>"},'
        '{"label":"<dimension 4>","a":"<concise value>","b":"<concise value>"},'
        '{"label":"<dimension 5>","a":"<concise value>","b":"<concise value>"}'
        '],'
        f'"a_edge":"one sentence: where {a_label} wins",'
        f'"b_edge":"one sentence: where {b_label} wins"'
        '}'
    )
    try:
        raw = _groq_chat("You are a brand strategy analyst. Reply with JSON only.", [{"role":"user","content":prompt}], max_tokens=600, json_mode=True)
        raw = _re.sub(r"^```[a-z]*\n?","",raw).rstrip("`").strip()
        result = _json.loads(raw)
        result["a_name"] = da.get("name") or a
        result["b_name"] = db.get("name") or b
        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/intel/compare-batch")
def api_intel_compare_batch():
    """Fetch 2-3 companies and return structured grid data for side-by-side comparison."""
    import concurrent.futures as _cf
    companies = request.args.get("companies", "").strip().split(",")
    companies = [c.strip() for c in companies if c.strip()]

    if not companies or len(companies) < 2 or len(companies) > 3:
        return jsonify({"error": "Provide 2-3 company names (comma-separated)"}), 400

    # Check for duplicates
    if len(set(c.lower() for c in companies)) != len(companies):
        return jsonify({"error": "Cannot compare company with itself"}), 400

    # Fetch all companies in parallel
    def fetch_and_extract(name):
        d = fetch_company_info(name)
        w = d.get("wiki") or {}
        share = d.get("share") or {}
        jobs = d.get("job_signals") or {}
        ai = d.get("ai_signals") or {}

        # Build result with fallbacks for missing fields
        result = {
            "name": d.get("name") or name,
            "founded": str(w.get("founded") or w.get("start_date") or "—"),
            "hq": str(w.get("hq") or w.get("headquarters") or w.get("location") or "—"),
            "industry": str(w.get("industry") or w.get("categories") or "—"),
            "revenue": str(w.get("revenue") or w.get("annual_revenue") or "—"),
            "employees": str(w.get("employees") or w.get("staffing_size") or "—"),
            "market_cap": str(share.get("market_cap") or share.get("marketcap") or "—"),
            "hiring": f"{jobs.get('total', 0)} open roles" if jobs.get('total') else "—",
            "ai_pct": f"{round(ai.get('ai_pct', 0) or 0)}% AI roles" if ai.get('ai_pct') else "—",
            "overview": w.get("extract") or w.get("summary") or "—",
        }
        if result["overview"] and len(result["overview"]) > 150:
            result["overview"] = result["overview"][:150]
        return result

    try:
        with _cf.ThreadPoolExecutor(max_workers=3) as ex:
            results = list(ex.map(fetch_and_extract, companies))
        return jsonify({"companies": results, "count": len(results)})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/intel/competitors")
def api_intel_competitors():
    """Get competitor list for a given company."""
    name = request.args.get("name", "").strip()
    if not name:
        return jsonify({"error": "Company name required"}), 400

    try:
        d = fetch_company_info(name)
        competitors = d.get("competitors", [])
        # Extract names if they're dict objects
        comp_names = [
            c.get("name") if isinstance(c, dict) else str(c)
            for c in competitors
        ]
        return jsonify({"company": d.get("name") or name, "competitors": comp_names[:5]})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/home/last-receipt")
def api_home_last_receipt():
    """Get user's last receipt for brief card."""
    # Identify user via token or cookie (same as /api/home/brief)
    token = request.args.get("token", "").strip()
    if not token:
        token = (request.cookies.get("miru_saves_token") or
                 request.cookies.get("miru_saves_phone") or "").strip()
    from_number = _v2_resolve(token)

    if not from_number:
        return jsonify({"merchant": None, "total": None, "shop_date": None})

    phone = from_number.replace("whatsapp:", "").strip()

    try:
        # Get most recent REAL receipt by UPLOAD timestamp (created_at)
        # Skip "Online:" merchants (broken data) — find first real receipt
        rows = lib._sb().table("receipts").select("merchant,total,shop_date,created_at,items").eq("phone", phone) \
            .order("created_at", desc=True).limit(20).execute().data or []  # Get 20 to filter through

        if not rows:
            return jsonify({"merchant": None, "total": None, "shop_date": None})

        # Find first real receipt (not "Online:")
        r = None
        for row in rows:
            merchant = row.get("merchant", "")
            if merchant and not merchant.startswith("Online:"):
                r = row
                break

        if not r:
            return jsonify({"merchant": None, "total": None, "shop_date": None})
        app.logger.info(f"[last-receipt] RETURNING: {r.get('merchant')} on {r.get('shop_date')}")

        merchant = r.get("merchant", "Unknown")
        total = r.get("total", 0)
        shop_date = r.get("shop_date")

        # FORCE FIX: Ensure date is correct
        # Database might have wrong format or swapped month/day
        if shop_date:
            try:
                if "/" in shop_date:
                    # MM/DD/YY format → ISO YYYY-MM-DD
                    parts = shop_date.split("/")
                    if len(parts) == 3:
                        month_str, day_str, year_str = parts[0], parts[1], parts[2]
                        year = int(year_str) if len(year_str) == 4 else 2000 + int(year_str)
                        shop_date = f"{year:04d}-{month_str.zfill(2)}-{day_str.zfill(2)}"
                        app.logger.info(f"[last-receipt] Slash format normalized: {r.get('shop_date')} → {shop_date}")
                elif "-" in shop_date:
                    # ISO format: check if month/day are swapped
                    parts = shop_date.split("-")
                    if len(parts) == 3:
                        year_str, m_str, d_str = parts[0], parts[1], parts[2]
                        month_num = int(m_str)
                        day_num = int(d_str)

                        # Case 1: month > 12 (impossible month)
                        if month_num > 12 and day_num <= 12:
                            shop_date = f"{year_str}-{d_str}-{m_str}"
                            app.logger.info(f"[last-receipt] ISO swapped (month>12): {r.get('shop_date')} → {shop_date}")

                        # Case 2: month > day + statistical heuristic
                        # Most shopping happens early/mid month (day < 15), rarely late (day > 20)
                        # If month > day AND month is mid-late AND day is early, they're swapped
                        elif month_num > day_num and month_num >= 7 and day_num <= 12:
                            shop_date = f"{year_str}-{d_str}-{m_str}"
                            app.logger.info(f"[last-receipt] ISO swapped (heuristic): {r.get('shop_date')} → {shop_date}")
            except Exception as e:
                app.logger.debug(f"[last-receipt] Date fix failed: {e}, keeping raw")

        # Parse items if available
        items_str = r.get("items", "[]") or "[]"
        items = []
        try:
            import json as _json_items
            items_list = _json_items.loads(items_str)
            items = [item.get("name", "") for item in (items_list or []) if item.get("name", "")][:3]  # Top 3 items
        except:
            pass

        return jsonify({"merchant": merchant, "total": total, "shop_date": shop_date, "items": items})
    except Exception as e:
        app.logger.warning(f"[last-receipt] {e}")
        return jsonify({"error": str(e), "merchant": None}), 500


