@app.route("/api/brands/search")
def api_brands_search():
    """Autocomplete search for brands"""
    q = request.args.get("q", "").strip()
    if not q or len(q) < 1:
        return jsonify([])

    try:
        sb = lib._sb()
        result = sb.table("brand_phase1_intelligence").select(
            "brand_name, category"
        ).ilike("brand_name", f"%{q}%").limit(10).execute()

        brands = []
        seen = set()
        for row in result.data:
            name = row.get("brand_name", "")
            if name and name not in seen:
                brands.append({
                    "name": name,
                    "category": row.get("category", "")
                })
                seen.add(name)

        return jsonify(brands)
    except Exception as e:
        app.logger.error(f"Brand search error: {e}")
        return jsonify([])


@app.route("/api/intel/companies")
def api_intel_companies():
    """Get all parent companies with brand counts"""
    try:
        sb = lib._sb()

        # Try to fetch with parent_company
        print(f"🔍 [COMPANIES] Attempting to fetch parent companies...")
        result = sb.table("brand_phase1_intelligence").select("parent_company, brand_name").execute()

        # Safely handle result
        data = result.data if result and hasattr(result, 'data') else None
        print(f"🔍 [COMPANIES] Query returned: {type(data)}, length: {len(data) if data else 0}")

        if not data:
            print(f"⚠️  [COMPANIES] No data from query, returning empty list")
            return jsonify({"success": True, "companies": [], "total_companies": 0})

        # Count brands per company
        companies = {}
        sample_rows = []
        for i, row in enumerate(data):
            if i < 5:  # Show first 5 for debugging
                sample_rows.append(row)
            if not row or not isinstance(row, dict):
                continue
            # Handle NULL parent_company values
            company = (row.get("parent_company") or "").strip()
            print(f"  Row {i}: company='{company}'")
            if company and company.lower() not in ("unknown", "", "null"):
                companies[company] = companies.get(company, 0) + 1

        print(f"🔍 [COMPANIES] Sample rows: {sample_rows}")
        print(f"🔍 [COMPANIES] Unique companies found: {len(companies)}")
        print(f"🔍 [COMPANIES] Company list: {list(companies.keys())[:10]}")

        # Sort by brand count descending
        sorted_companies = sorted(
            [{"name": c, "brand_count": count} for c, count in companies.items()],
            key=lambda x: x["brand_count"],
            reverse=True
        )

        print(f"✅ [COMPANIES] Returning {len(sorted_companies)} companies")
        return jsonify({
            "success": True,
            "companies": sorted_companies,
            "total_companies": len(sorted_companies)
        })

    except Exception as e:
        error_msg = f"{type(e).__name__}: {str(e)}"
        print(f"❌ [COMPANIES] ERROR: {error_msg}")
        app.logger.error(f"❌ Companies API error: {error_msg}")

        # Return empty success instead of error - frontend already handles empty
        return jsonify({
            "success": True,
            "companies": [],
            "total_companies": 0,
            "debug_error": str(e)
        })


@app.route("/api/intel/category/<category_name>")
def api_intel_category_brands(category_name):
    """Get all brands for a specific category"""
    try:
        sb = lib._sb()
        result = sb.table("brand_phase1_intelligence").select(
            "brand_name, category, positioning_tier, market_country, parent_company"
        ).eq("category", category_name).execute()

        # Safely handle result
        data = result.data if result and hasattr(result, 'data') else []
        if not data:
            return jsonify({
                "success": True,
                "category": category_name,
                "brands": [],
                "brand_count": 0
            })

        # Group by brand
        brands_dict = {}
        for row in data:
            if not row or not isinstance(row, dict):
                continue
            brand = row.get("brand_name", "").strip()
            if brand:
                if brand not in brands_dict:
                    brands_dict[brand] = {
                        "name": brand,
                        "category": row.get("category", ""),
                        "positioning_tier": row.get("positioning_tier", ""),
                        "parent_company": row.get("parent_company", ""),
                        "markets": []
                    }
                market = row.get("market_country", "").strip()
                if market and market not in brands_dict[brand]["markets"]:
                    brands_dict[brand]["markets"].append(market)

        # Sort by brand name
        brands = sorted(brands_dict.values(), key=lambda x: x["name"])

        return jsonify({
            "success": True,
            "category": category_name,
            "brands": brands,
            "brand_count": len(brands)
        })
    except Exception as e:
        app.logger.error(f"❌ Category brands error: {type(e).__name__}: {e}")
        return jsonify({"success": False, "error": str(e)})


