@app.route("/api/intel/request-brand", methods=["POST"])
def api_intel_request_brand():
    """Submit brand data request - triggers background agent to collect data"""
    data = request.get_json() or {}
    brand_name = data.get("brand_name", "").strip()
    category = data.get("category", "").strip() or "unknown"  # Optional, AI can guess
    email = data.get("email", "").strip()

    if not brand_name:
        return jsonify({"success": False, "error": "Brand name is required"}), 400

    try:
        sb = lib._sb()

        # Store request in database
        # Background worker (brand_worker.py) will pick it up and process
        request_data = {
            "brand_name": brand_name,
            "category": category,
            "email": email,
            "status": "pending",
            "created_at": datetime.now().isoformat()
        }

        sb.table("brand_data_requests").insert(request_data).execute()

        return jsonify({
            "success": True,
            "message": "Brand request submitted",
            "note": "Request queued for processing. Check status in 1-2 minutes."
        })
    except Exception as e:
        app.logger.error(f"Request brand error: {e}")
        return jsonify({"success": False, "error": str(e)}), 500

