@app.route("/api/v2/receipts-timeline", methods=["GET"])
def api_v2_receipts_timeline():
    """Get all receipts with items for timeline view (last N days)."""
    token = request.args.get("token", "").strip()
    from_number = _v2_resolve(token)
    if not from_number:
        return jsonify({"receipts": [], "total": 0})

    try:
        days = request.args.get("days", 90, type=int)
        import json
        from datetime import datetime, timedelta

        # Get receipts from last N days (stored in wa_saves as 🧾 clippings)
        cutoff = (datetime.utcnow() - timedelta(days=days)).isoformat()

        print(f"[receipts-timeline] Querying wa_saves for user={from_number}, cutoff={cutoff}", flush=True)
        rows = lib._sb().table("wa_saves").select("id,from_number,title,summary,amount,category,created_at") \
            .eq("from_number", from_number) \
            .gte("created_at", cutoff) \
            .ilike("title", "🧾%") \
            .order("created_at", desc=True) \
            .execute().data or []

        print(f"[receipts-timeline] Found {len(rows)} receipts", flush=True)

        receipts = []
        total = 0

        import re as _re_parse

        # DEBUG: Log first receipt to see actual data structure
        if rows:
            print(f"[receipts-debug] FIRST RECEIPT STRUCTURE:", flush=True)
            first = rows[0]
            print(f"  title: {first.get('title')}", flush=True)
            print(f"  summary (first 200 chars): {str(first.get('summary'))[:200]}", flush=True)
            print(f"  category: {first.get('category')}", flush=True)
            print(f"  All fields: {list(first.keys())}", flush=True)

        for row in rows:
            # wa_saves stores receipts with 🧾 prefix in title
            title = row.get("title", "").replace("🧾 ", "").strip()
            summary = row.get("summary", "")
            category = row.get("category", "Unknown")

            # USE THE PRE-EXTRACTED AMOUNT FIELD!
            amount = 0
            amount_field = row.get("amount")
            if amount_field:
                try:
                    amount = float(str(amount_field).replace("£", "").replace(",", ""))
                except:
                    pass

            merchant = title or "Unknown"
            items = []

            # Extract item lines from summary (bullet points or dashes)
            if summary:
                lines = summary.split("\n")
                for line in lines:
                    line = line.strip()
                    # Skip META lines, totals, and empty lines
                    if line and not line.startswith("META:") and "total" not in line.lower() \
                            and "saved" not in line.lower() and "amount" not in line.lower():
                        # Clean up bullet points
                        line = _re_parse.sub(r'^[•\-\*]\s*', '', line)
                        if line and len(line) > 3:
                            items.append(line)

            total += amount

            receipts.append({
                "id": row.get("id"),
                "merchant": merchant,
                "total": amount,
                "shop_date": row.get("created_at"),
                "created_at": row.get("created_at"),
                "items": items[:10],  # Cap at 10 items
                "category": category
            })

        # DEBUG: Check extraction quality
        with_amount = sum(1 for r in receipts if r['total'] > 0)
        print(f"[receipts-timeline] {with_amount}/{len(receipts)} receipts have amounts (total £{total:.2f})", flush=True)
        zero_amount = [r['merchant'] for r in receipts if r['total'] == 0][:5]
        if zero_amount:
            print(f"[receipts-timeline] Still £0.00: {zero_amount}", flush=True)

        return jsonify({"receipts": receipts, "total": total})
    except Exception as e:
        print(f"[receipts-timeline] Error: {e}")
        return jsonify({"receipts": [], "total": 0, "error": str(e)})


@app.route("/api/v2/item-price-history", methods=["GET"])
def api_v2_item_price_history():
    """Get price history for a specific item across all receipts."""
    token = request.args.get("token", "").strip()
    item_name = request.args.get("item", "").strip()
    from_number = _v2_resolve(token)

    if not from_number or not item_name:
        return jsonify({"history": [], "average": 0, "min": 0, "max": 0})

    try:
        import json

        # Query wa_saves for receipts (🧾 clippings)
        rows = lib._sb().table("wa_saves").select("*") \
            .eq("from_number", from_number) \
            .ilike("title", "🧾%") \
            .order("created_at", desc=True) \
            .execute().data or []

        history = []
        for row in rows:
            items = row.get("items", [])
            if isinstance(items, str):
                try:
                    items = json.loads(items)
                except:
                    items = []

            # Search for item in this receipt
            for item in items:
                item_text = item if isinstance(item, str) else (item.get("name", "") or "")
                if item_name.lower() in item_text.lower():
                    price = None
                    if not isinstance(item, str) and isinstance(item, dict):
                        price = item.get("price")

                    if price is None:
                        # Fall back to total divided by item count
                        price = float(row.get("total", 0)) / max(1, len(items))

                    history.append({
                        "date": row.get("shop_date") or row.get("created_at"),
                        "price": float(price),
                        "merchant": row.get("merchant")
                    })
                    break

        if not history:
            return jsonify({"history": [], "average": 0, "min": 0, "max": 0})

        prices = [h["price"] for h in history]
        average = sum(prices) / len(prices)

        return jsonify({
            "history": history,
            "average": average,
            "min": min(prices),
            "max": max(prices)
        })
    except Exception as e:
        print(f"[item-price-history] Error: {e}")
        return jsonify({"history": [], "average": 0, "min": 0, "max": 0, "error": str(e)})


@app.route("/api/v2/spend/upload-pdf", methods=["POST"])
def api_v2_spend_upload_pdf():
    """Upload and extract transactions from a PDF (bank statement, receipt, or invoice).

    SECURITY:
    - Data is extracted using vision AI (Claude), not stored on servers
    - Only transaction count is logged, never amounts or merchant names
    - Each user's data is isolated by phone number
    - PDF file is deleted immediately after processing
    """
    try:
        token = request.form.get("token", "").strip()
        from_number = _v2_resolve(token)
        if not from_number:
            return jsonify({"error": "Unauthorized"}), 401

        if "pdf" not in request.files:
            return jsonify({"error": "pdf file required"}), 400

        pdf_file = request.files["pdf"]
        if not pdf_file.filename.lower().endswith(".pdf"):
            return jsonify({"error": "Only PDF files allowed"}), 400

        # Read PDF bytes
        pdf_bytes = pdf_file.read()
        if not pdf_bytes:
            return jsonify({"error": "Empty file"}), 400

        # Extract transactions using AI vision
        from spend_pdf_extractor import extract_transactions_from_pdf
        result = extract_transactions_from_pdf(pdf_bytes)

        if not result["success"]:
            return jsonify(result), 400

        # Store extracted transactions in receipts table
        if result["transactions"]:
            try:
                sb = lib._sb()
                phone_clean = from_number.replace("whatsapp:", "").strip()

                # Add each transaction as a receipt
                for txn in result["transactions"]:
                    sb.table("receipts").insert({
                        "phone": phone_clean,
                        "merchant": txn.get("merchant", "Unknown"),
                        "total": txn.get("amount", 0),
                        "shop_date": txn.get("date"),
                        "items": __import__("json").dumps([{"name": txn.get("category", "Other"), "qty": 1, "price": txn.get("amount", 0)}]),
                        "raw_summary": f"PDF extracted: {txn.get('category', 'Other')}",
                        "restaurant_type": classify_restaurant(txn.get("merchant", "")),
                    }).execute()

                app.logger.info(f"[spend] Stored {result['count']} transactions from PDF to receipts table")
            except Exception as e:
                app.logger.warning(f"[spend] Failed to store transactions: {e}")

        return jsonify({
            "success": True,
            "count": result["count"],
            "transactions": result["transactions"],
            "message": f"Extracted {result['count']} transactions from PDF",
        })

    except Exception as e:
        app.logger.error(f"[spend] PDF upload error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


# ────────────────────────────────────────────────────────────────────────
# FIELD WORKER EXPENSE INTELLIGENCE (work_expenses)
# ────────────────────────────────────────────────────────────────────────

EXPENSE_GROQ_PROMPT = """You are a receipt OCR extraction assistant specialized for field workers' business expenses.

Extract structured data from this receipt photo or invoice text.

CRITICAL: Extract ONLY if this is a business receipt (not personal bills, insurance, utilities, etc.)

RECEIPT DATA:
{receipt_text}

Extract these fields:
1. amount: Total amount (number only, e.g., 45.00)
2. currency: GBP, USD, EUR, etc.
3. merchant: Business name (e.g., "Screwfix", "Shell", "Costa")
4. date: Transaction date (YYYY-MM-DD format). If not visible, use "unknown"
5. category: ONE of: Supplies, Fuel, Meals, Equipment, Transport, Accommodation, Communications, Subscriptions, Training, Other
6. description: What was purchased?
7. vat_amount: VAT charged (number only)
8. business_use: true/false (is this business only or personal?)

RETURN: Valid JSON only (no markdown)

{
  "amount": 45.00,
  "currency": "GBP",
  "merchant": "Screwfix",
  "date": "2026-06-28",
  "category": "Supplies",
  "description": "Plasterboard + screws",
  "vat_amount": 7.50,
  "business_use": true,
  "extraction_confidence": 0.95
}

IF EXTRACTION FAILS:
{
  "error": "reason",
  "extraction_confidence": 0.0
}"""

def _extract_expense_with_groq(receipt_text: str) -> dict:
    """Extract expense data from receipt text using Groq."""
    try:
        from groq import Groq
        client = Groq(api_key=os.environ.get("GROQ_API_KEY"))

        prompt = EXPENSE_GROQ_PROMPT.format(receipt_text=receipt_text)
        response = client.chat.completions.create(
            model="mixtral-8x7b-32768",
            messages=[{"role": "user", "content": prompt}],
            temperature=0.2,
            max_tokens=300
        )

        import json
        response_text = response.choices[0].message.content.strip()
        if response_text.startswith("```"):
            response_text = response_text.split("```")[1]
            if response_text.startswith("json"):
                response_text = response_text[4:]
            response_text = response_text.rstrip("```").strip()

        return json.loads(response_text)
    except Exception as e:
        print(f"[expense] Groq extraction error: {e}")
        return {"error": str(e), "extraction_confidence": 0.0}

@app.route("/api/v2/expenses/extract", methods=["POST"])
def api_v2_expenses_extract():
    """Extract receipt data using Groq OCR."""
    try:
        token = request.form.get("token", "") or request.json.get("token", "")
        from_number = _v2_resolve(token)
        if not from_number:
            return jsonify({"error": "Unauthorized"}), 401

        receipt_text = request.form.get("receipt_text", "") or request.json.get("receipt_text", "")
        if not receipt_text:
            return jsonify({"error": "receipt_text required"}), 400

        # Extract with Groq
        extracted = _extract_expense_with_groq(receipt_text)

        if extracted.get("error"):
            return jsonify(extracted), 400

        # Store in Supabase
        try:
            lib._sb().table("work_expenses").insert({
                "from_number": from_number,
                "amount": extracted.get("amount", 0),
                "currency": extracted.get("currency", "GBP"),
                "merchant": extracted.get("merchant", "Unknown"),
                "receipt_date": extracted.get("date", datetime.now().date().isoformat()),
                "category": extracted.get("category", "Other"),
                "description": extracted.get("description", ""),
                "vat_amount": extracted.get("vat_amount", 0),
                "business_use": extracted.get("business_use", True),
                "extraction_confidence": extracted.get("extraction_confidence", 0),
                "expense_status": "pending"
            }).execute()
            print(f"[expense] Stored: {from_number} - £{extracted.get('amount', 0):.2f} from {extracted.get('merchant')}")
        except Exception as db_err:
            print(f"[expense] DB error (not critical): {db_err}")

        return jsonify({
            "success": True,
            "extracted": extracted,
            "message": f"✅ Expense saved: £{extracted.get('amount', 0):.2f} from {extracted.get('merchant')} ({extracted.get('category')})"
        })

    except Exception as e:
        print(f"[expense] Extract error: {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/v2/expenses/summary", methods=["GET"])
def api_v2_expenses_summary():
    """Get monthly expense breakdown by category."""
    try:
        token = request.args.get("token", "").strip()
        from_number = _v2_resolve(token)
        if not from_number:
            return jsonify({"error": "Unauthorized"}), 401

        # Get month from params
        month = request.args.get("month", datetime.now().month, type=int)
        year = request.args.get("year", datetime.now().year, type=int)

        start_date = f"{year:04d}-{month:02d}-01"
        if month == 12:
            end_date = f"{year+1:04d}-01-01"
        else:
            end_date = f"{year:04d}-{month+1:02d}-01"

        # Query expenses
        rows = lib._sb().table("work_expenses").select(
            "amount,merchant,category,vat_amount,receipt_date,expense_status"
        ).eq("from_number", from_number) \
         .gte("receipt_date", start_date) \
         .lt("receipt_date", end_date) \
         .execute().data or []

        # Aggregate by category
        breakdown = {}
        total_amount = 0
        total_vat = 0
        merchants = {}

        for row in rows:
            cat = row.get("category", "Other")
            amt = float(row.get("amount", 0))
            vat = float(row.get("vat_amount", 0))
            merch = row.get("merchant", "Unknown")

            if cat not in breakdown:
                breakdown[cat] = {"total": 0, "count": 0, "merchants": {}}

            breakdown[cat]["total"] += amt
            breakdown[cat]["count"] += 1

            if merch not in breakdown[cat]["merchants"]:
                breakdown[cat]["merchants"][merch] = 0
            breakdown[cat]["merchants"][merch] += amt

            total_amount += amt
            total_vat += vat

        # Sort categories by total (highest first)
        sorted_breakdown = dict(sorted(breakdown.items(), key=lambda x: x[1]["total"], reverse=True))

        return jsonify({
            "period": f"{month_name(month)} {year}",
            "total_amount": round(total_amount, 2),
            "total_vat": round(total_vat, 2),
            "receipt_count": len(rows),
            "breakdown": sorted_breakdown
        })

    except Exception as e:
        print(f"[expense] Summary error: {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/v2/expenses/list", methods=["GET"])
def api_v2_expenses_list():
    """List all expenses for a user (paginated)."""
    try:
        token = request.args.get("token", "").strip()
        from_number = _v2_resolve(token)
        if not from_number:
            return jsonify({"error": "Unauthorized"}), 401

        limit = request.args.get("limit", 20, type=int)
        offset = request.args.get("offset", 0, type=int)

        rows = lib._sb().table("work_expenses").select(
            "id,amount,merchant,category,receipt_date,vat_amount,expense_status"
        ).eq("from_number", from_number) \
         .order("receipt_date", desc=True) \
         .range(offset, offset + limit - 1) \
         .execute().data or []

        return jsonify({
            "expenses": rows,
            "count": len(rows),
            "offset": offset,
            "limit": limit
        })

    except Exception as e:
        print(f"[expense] List error: {e}")
        return jsonify({"error": str(e)}), 500

def month_name(month: int) -> str:
    """Convert month number to name."""
    names = ["", "January", "February", "March", "April", "May", "June",
             "July", "August", "September", "October", "November", "December"]
    return names[month] if 1 <= month <= 12 else "Unknown"

@app.route("/api/v2/prefs", methods=["POST"])
def api_v2_prefs_post():
    """Save V2 preferences. Merges with existing — send only changed keys."""
    body = request.get_json(force=True, silent=True) or {}
    token = body.get("token", "") or request.args.get("token", "")
    token = (token or "").strip()
    from_number = _v2_resolve(token)
    if not from_number:
        return jsonify({"error": "token required"}), 401
    # Accept prefs as nested {"prefs":{...}} or top-level keys in the same body
    PREF_KEYS = {"train_from", "train_to", "fuel_postcode", "commute_mode",
                 "bin_collection_day", "bin_types", "bin_types_a", "bin_types_b", "bin_rotation", "bin_rotation_week",
                 "interests"}
    new_prefs = body.get("prefs") or {k: v for k, v in body.items() if k in PREF_KEYS}
    if not isinstance(new_prefs, dict):
        return jsonify({"error": "prefs must be object"}), 400

    # ── Validate train stations ──────────────────────────────────────────────
    def _find_station(name):
        """Find exact or close match for station name. Strict validation. Return (crs, display_name) or None."""
        if not name: return None
        name_lower = name.lower().replace("station","").strip()
        # NO digits allowed (rejects "longcross 1", "london 2", etc)
        if any(c.isdigit() for c in name_lower):
            return None
        # Exact match
        for cache_name, cache_stn in _STATION_CACHE.items():
            if cache_name == name_lower:
                return cache_stn["crs"], cache_stn["name"]
        # Prefix match (must be at least 4 chars and high quality)
        for cache_name, cache_stn in _STATION_CACHE.items():
            if len(name_lower) >= 4 and cache_name.startswith(name_lower):
                return cache_stn["crs"], cache_stn["name"]
        # Fuzzy match (high cutoff - 0.8 = must be very similar)
        import difflib
        close = difflib.get_close_matches(name_lower, list(_STATION_CACHE.keys()), n=1, cutoff=0.8)
        if close:
            stn = _STATION_CACHE[close[0]]
            return stn["crs"], stn["name"]
        return None

    # Validate train_from and train_to
    errors = []
    if "train_from" in new_prefs and new_prefs["train_from"]:
        result = _find_station(new_prefs["train_from"])
        if not result:
            errors.append(f"Home station '{new_prefs['train_from']}' not found. Check spelling.")
        else:
            new_prefs["train_from"] = result[1]  # Use canonical name
    if "train_to" in new_prefs and new_prefs["train_to"]:
        result = _find_station(new_prefs["train_to"])
        if not result:
            errors.append(f"Work station '{new_prefs['train_to']}' not found. Check spelling.")
        else:
            new_prefs["train_to"] = result[1]  # Use canonical name

    if errors:
        return jsonify({"error": " | ".join(errors)}), 400

    # Auto-derive train_from from location profile home anchor, then fall back to home postcode
    if "train_to" in new_prefs and "train_from" not in new_prefs:
        _hlat = _hlng = None
        # Prefer stored home location anchor (more precise than postcode centroid)
        try:
            _lp = lib._sb().table("ma_details").select("data") \
                .eq("device_id", from_number).eq("type", "location_profile").limit(1).execute().data or []
            _home_anchor = (_lp[0].get("data") or {}).get("home", {}) if _lp else {}
            _hlat = _home_anchor.get("lat")
            _hlng = _home_anchor.get("lng")
        except Exception:
            pass
        # Fall back to postcode
        if not _hlat:
            _home_pc = (body.get("home_postcode") or "").strip().upper().replace(" ", "")
            if _home_pc:
                try:
                    _ll = postcode_to_latlon(_home_pc)
                    if _ll:
                        _hlat, _hlng = _ll
                except Exception:
                    pass
        if _hlat and _hlng:
            try:
                _scored = sorted(
                    [(haversine_km(_hlat, _hlng, s["lat"], s["lon"]), s)
                     for s in _STATION_CACHE.values()
                     if s.get("lat") and s.get("lon") and s.get("crs") not in _LOW_SERVICE_CRS],
                    key=lambda x: x[0]
                )
                if _scored and _scored[0][0] < 5.0:
                    new_prefs["train_from"] = _scored[0][1]["name"]
            except Exception:
                pass

    try:
        sb = lib._sb()
        _fn_plain = from_number.replace("whatsapp:", "").strip()
        _fn_wa    = f"whatsapp:{_fn_plain}"
        rows = sb.table("ma_details").select("id,data") \
            .in_("device_id", [_fn_plain, _fn_wa]).eq("type", "v2_prefs").limit(1).execute().data or []
        _prev_prefs = (rows[0].get("data") or {}) if rows else {}
        if rows:
            merged = {**_prev_prefs, **new_prefs}
            sb.table("ma_details").update({"data": merged}).eq("id", rows[0]["id"]).execute()
        else:
            sb.table("ma_details").insert({
                "device_id": from_number, "type": "v2_prefs",
                "label": "home_brief", "data": new_prefs,
            }).execute()
        if new_prefs.get("morning_push") is True and not _prev_prefs.get("morning_push"):
            try:
                _to = from_number if from_number.startswith("whatsapp:") else f"whatsapp:{from_number}"
                _wa_send_proactive(_to,
                    "📬 Morning briefs are on. I'll message you at 7:30am daily.\n\n"
                    "Reply *STOP BRIEF* anytime to turn off.")
            except Exception:
                pass
        return jsonify({"ok": True, "prefs": new_prefs})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


