@app.route("/api/v2/location-profile", methods=["POST"])
def api_v2_location_profile_post():
    """Save or update a named location anchor. Send {"token":"...", "key":"home", "anchor":{...}}"""
    body = request.get_json(force=True, silent=True) or {}
    token = (body.get("token") or request.args.get("token", "")).strip()
    from_number = _v2_resolve(token)
    if not from_number:
        return jsonify({"error": "token required"}), 401
    key    = body.get("key", "").strip()
    anchor = body.get("anchor")
    if not key or key not in ("home", "work", "school_run"):
        return jsonify({"error": "key must be home, work, or school_run"}), 400
    if anchor is not None and not isinstance(anchor, dict):
        return jsonify({"error": "anchor must be object or null"}), 400
    try:
        sb = lib._sb()
        rows = sb.table("ma_details").select("id,data") \
            .eq("device_id", from_number).eq("type", "location_profile").limit(1).execute().data or []
        if rows:
            profile = rows[0].get("data") or {}
            if anchor is None:
                profile.pop(key, None)
            else:
                profile[key] = anchor
            sb.table("ma_details").update({"data": profile}).eq("id", rows[0]["id"]).execute()
        else:
            profile = {key: anchor} if anchor else {}
            sb.table("ma_details").insert({
                "device_id": from_number,
                "type": "location_profile",
                "label": "location_profile",
                "data": profile,
            }).execute()
        return jsonify({"ok": True, "profile": profile})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/v2/classify-location", methods=["GET"])
def api_v2_classify_location():
    """Lightweight endpoint — classify a GPS ping against stored profile. No brief generated."""
    token = request.args.get("token", "").strip()
    from_number = _v2_resolve(token)
    if not from_number:
        return jsonify({"context": "unknown"})
    try:
        lat = float(request.args.get("lat", ""))
        lng = float(request.args.get("lng", ""))
    except (TypeError, ValueError):
        return jsonify({"context": "unknown"})
    try:
        rows = lib._sb().table("ma_details").select("data") \
            .eq("device_id", from_number).eq("type", "location_profile").limit(1).execute().data or []
        profile = rows[0]["data"] if rows else {}
        result = _classify_location(lat, lng, profile)
        return jsonify(result)
    except Exception as e:
        return jsonify({"context": "out", "error": str(e)})


def _classify_location(lat, lng, profile: dict, saves: list = None) -> dict:
    """Classify a GPS position against a stored location profile.

    Returns:
      {
        "context":  "home" | "work" | "school_run" | "nearby_save" | "out",
        "label":    human-readable string e.g. "Home" or "Near Wagamama",
        "anchor":   which profile key matched (or None),
        "save":     nearest save name if context == "nearby_save" (or None),
        "dist_km":  distance to matched anchor (or None),
      }
    """
    if lat is None or lng is None:
        return {"context": "unknown", "label": None, "anchor": None, "save": None, "dist_km": None}

    # Check named anchors in order of priority
    _ANCHOR_ORDER = ["home", "work", "school_run"]
    for key in _ANCHOR_ORDER:
        anchor = profile.get(key)
        if not anchor or not anchor.get("lat") or not anchor.get("lng"):
            continue
        dist = haversine_km(lat, lng, anchor["lat"], anchor["lng"])
        radius = anchor.get("radius_km", 0.5)
        if dist <= radius:
            label_map = {"home": "Home", "work": "Work", "school_run": anchor.get("label", "School run")}
            return {
                "context":  key,
                "label":    label_map.get(key, key.title()),
                "anchor":   key,
                "save":     None,
                "dist_km":  round(dist, 2),
            }

    # Check nearby saves (restaurants, places saved by user) within 400m
    if saves:
        for s in saves:
            slat = s.get("lat") or s.get("_lat")
            slng = s.get("lng") or s.get("_lng")
            if not slat or not slng:
                continue
            dist = haversine_km(lat, lng, slat, slng)
            if dist <= 0.4:
                name = (s.get("title") or "").strip()
                # Strip leading emoji
                parts = name.split()
                if parts and len(parts[0]) <= 2:
                    name = " ".join(parts[1:])
                return {
                    "context":  "nearby_save",
                    "label":    f"Near {name}" if name else "Near a saved place",
                    "anchor":   None,
                    "save":     name,
                    "dist_km":  round(dist, 2),
                }

    return {"context": "out", "label": None, "anchor": None, "save": None, "dist_km": None}


def _v2_log_location_signal(from_number: str, lat: float, lng: float):
    """Append a GPS ping to location_signals for auto-learn. Keeps last 10 only."""
    import datetime as _dt
    try:
        sb = lib._sb()
        rows = sb.table("ma_details").select("id,data") \
            .eq("device_id", from_number).eq("type", "location_signals").limit(1).execute().data or []
        now_ts = _dt.datetime.utcnow().isoformat()
        new_ping = {"lat": round(lat, 5), "lng": round(lng, 5), "ts": now_ts}
        if rows:
            signals = rows[0].get("data") or {}
            pings = signals.get("pings", [])
            pings.append(new_ping)
            pings = pings[-30:]  # keep last 30 for pattern learning
            sb.table("ma_details").update({"data": {"pings": pings}}).eq("id", rows[0]["id"]).execute()
        else:
            sb.table("ma_details").insert({
                "device_id": from_number,
                "type": "location_signals",
                "label": "location_signals",
                "data": {"pings": [new_ping]},
            }).execute()
    except Exception as _e:
        pass  # non-critical


def _v2_check_auto_learn(from_number: str) -> dict | None:
    """Return a candidate home location if 3+ evening pings cluster within 200m. Else None."""
    try:
        sb = lib._sb()
        rows = sb.table("ma_details").select("data") \
            .eq("device_id", from_number).eq("type", "location_signals").limit(1).execute().data or []
        if not rows:
            return None
        pings = (rows[0].get("data") or {}).get("pings", [])
        # Filter to evening pings (19:00–23:59 UTC, approximate)
        evening = [p for p in pings if "T1" in p.get("ts", "") or "T2" in p.get("ts", "")]
        if len(evening) < 3:
            return None
        # Check if all cluster within 200m of the most recent
        ref = evening[-1]
        cluster = [p for p in evening if haversine_km(ref["lat"], ref["lng"], p["lat"], p["lng"]) <= 0.2]
        if len(cluster) >= 3:
            return {"lat": ref["lat"], "lng": ref["lng"]}
    except Exception:
        pass
    return None


# Surrey CC term holiday periods — (start_iso, end_iso, label, back_iso)
# Covers community/voluntary-controlled schools; academies may vary by ~1 day
_SURREY_HOLIDAYS = [
    ("2025-10-27", "2025-10-31", "autumn half term",  "2025-11-03"),
    ("2025-12-20", "2026-01-04", "Christmas holidays", "2026-01-05"),
    ("2026-02-16", "2026-02-20", "spring half term",  "2026-02-23"),
    ("2026-03-28", "2026-04-13", "Easter holidays",   "2026-04-14"),
    ("2026-05-25", "2026-05-29", "summer half term",  "2026-06-01"),
    ("2026-07-23", "2026-09-02", "summer holidays",   "2026-09-03"),
    ("2026-10-19", "2026-10-30", "autumn half term",  "2026-11-02"),
    ("2026-12-19", "2027-01-04", "Christmas holidays", "2027-01-05"),
    ("2027-02-15", "2027-02-19", "spring half term",  "2027-02-22"),
    ("2027-03-26", "2027-04-09", "Easter holidays",   "2027-04-12"),
    ("2027-05-31", "2027-06-04", "summer half term",  "2027-06-07"),
    ("2027-07-29", "2027-09-01", "summer holidays",   "2027-09-02"),
]


def _surrey_holiday_status(today_date):
    """Return current/imminent holiday info for today's date.

    Returns dict with keys:
      on_holiday   bool
      label        str   e.g. "summer half term"
      back_date    str   ISO  e.g. "2026-06-01"
      back_label   str   e.g. "Mon 1 Jun"
      ends_today   bool  — today is the last day of this holiday
      starts_tom   bool  — holiday starts tomorrow (last school day is today)
      back_tom     bool  — back at school tomorrow
    """
    import datetime as _dt
    _DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    _MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
               "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

    def _fmt(iso):
        d = _dt.date.fromisoformat(iso)
        return f"{_DAYS[d.weekday()]} {d.day} {_MONTHS[d.month - 1]}"

    today_s   = today_date.isoformat()
    tomorrow  = (today_date + _dt.timedelta(days=1)).isoformat()

    for start, end, label, back in _SURREY_HOLIDAYS:
        if start <= today_s <= end:
            return {
                "on_holiday": True,
                "label":      label,
                "back_date":  back,
                "back_label": _fmt(back),
                "ends_today": today_s == end,
                "starts_tom": False,
                "back_tom":   tomorrow == back,
            }
        if tomorrow == start:
            return {
                "on_holiday": False,
                "label":      label,
                "back_date":  back,
                "back_label": _fmt(back),
                "ends_today": False,
                "starts_tom": True,
                "back_tom":   False,
            }

    return {"on_holiday": False, "label": "", "back_date": "", "back_label": "",
            "ends_today": False, "starts_tom": False, "back_tom": False}


def _school_dedup_events(events: list) -> list:
    """Deduplicate a list of school events in memory — exact title, fuzzy same-date, and reschedule suppression."""
    import re as _sre
    _stops = {"a","an","the","and","or","for","to","of","in","on","at","is","with","about","from","your","session","drop","first","parent","support"}
    def _words(t):
        return [w for w in _sre.sub(r"[^a-z0-9]"," ",(t or "").lower()).split() if len(w)>2 and w not in _stops]
    def _overlap(a, b):
        wa, wb = set(_words(a)), _words(b)
        if not wa and not wb: return 0
        common = sum(1 for w in wb if w in wa)
        return common / max(len(wa), len(wb), 1)
    def _richness(e):
        return (200 if e.get("action_needed") else 0) + len(e.get("description") or "") + len(e.get("action_needed") or "")

    # Pass 1: exact title dedup (case-insensitive, strip punctuation)
    seen_titles, uniq = {}, []
    for e in events:
        k = _sre.sub(r"[^a-z0-9]","", (e.get("event_title") or "").lower())
        if k and k in seen_titles:
            # Keep the richer one
            idx = seen_titles[k]
            if _richness(e) > _richness(uniq[idx]):
                uniq[idx] = e
        else:
            seen_titles[k] = len(uniq)
            uniq.append(e)

    # Pass 2: fuzzy same-date dedup across all profiles
    deduped, used = [], set()
    for i, ei in enumerate(uniq):
        if i in used: continue
        cluster = [ei]
        for j, ej in enumerate(uniq):
            if j <= i or j in used: continue
            same_date = (ei.get("event_date") or "") == (ej.get("event_date") or "")
            if same_date and _overlap(ei.get("event_title",""), ej.get("event_title","")) >= 0.35:
                cluster.append(ej)
                used.add(j)
        cluster.sort(key=_richness, reverse=True)
        deduped.append(cluster[0])
        used.add(i)

    # Pass 3: reschedule/postpone/cancel suppression
    _resc = _sre.compile(r'\b(reschedul|postpone|cancel)\w*', _sre.I)
    suppressed = set()
    for rev in deduped:
        if not _resc.search(rev.get("event_title","")): continue
        rev_words = set(_words(rev["event_title"]))
        if not rev_words: continue
        for ev in deduped:
            if ev is rev or id(ev) in suppressed: continue
            if _resc.search(ev.get("event_title","")): continue
            ev_words = _words(ev.get("event_title",""))
            if ev_words and sum(1 for w in ev_words if w in rev_words) >= min(2, len(rev_words)):
                suppressed.add(id(ev))
    return [e for e in deduped if id(e) not in suppressed]


def _v2_fetch_school(from_number: str) -> dict:
    """School profiles (daily run) + upcoming events (42 days) + recent comms (14 days)."""
    from datetime import date, timedelta
    try:
        today    = date.today()
        horizon  = (today + timedelta(days=42)).isoformat()  # 6 weeks — covers half term gaps
        recent   = (today - timedelta(days=14)).isoformat()
        today_s  = today.isoformat()
        tomorrow_s = (today + timedelta(days=1)).isoformat()
        # Compute holiday status early — needed even if no school profiles registered
        holiday_status = _surrey_holiday_status(today)
        holiday_status["inset_days"] = []
        # Try both formats — profiles may be stored with or without "whatsapp:" prefix
        _fn_plain = from_number.replace("whatsapp:", "").strip()
        _fn_wa    = f"whatsapp:{_fn_plain}"
        profiles = lib._sb().table("school_profiles") \
                       .select("id,child_name,school_name,address") \
                       .in_("from_number", [_fn_plain, _fn_wa]).eq("active", True).execute().data or []
        if not profiles:
            return {"schools": [], "upcoming": [], "recent": [], "events": [], "holiday_status": holiday_status}
        pids = [p["id"] for p in profiles]
        # Build profile_id → child_name/school_name lookup
        _pid_map = {p["id"]: p for p in profiles}
        def _enrich(ev):
            pr = _pid_map.get(ev.get("profile_id"), {})
            ev["child_name"]  = pr.get("child_name", "")
            ev["school_name"] = pr.get("school_name", "")
            ev["address"]     = pr.get("address", "")  # For transit lookup + smart context
            return ev
        # Upcoming events — next 42 days (include time so frontend can display it)
        upcoming = [_enrich(e) for e in (lib._sb().table("school_events").select(
            "id,profile_id,event_title,event_date,event_time,event_type,action_needed,location"
        ).in_("profile_id", pids).gte("event_date", today_s).lte("event_date", horizon) \
         .order("event_date").execute().data or [])]
        # Recent comms — emails received in last 14 days
        recent_rows = [_enrich(e) for e in (lib._sb().table("school_events").select(
            "id,profile_id,event_title,event_date,event_type,created_at"
        ).in_("profile_id", pids).gte("created_at", recent + "T00:00:00") \
         .order("created_at", desc=True).limit(5).execute().data or [])]
        # Inset days — school-specific days off from Gmail scan (today or tomorrow)
        inset_rows = []
        try:
            inset_rows = [_enrich(e) for e in (lib._sb().table("school_events").select(
                "profile_id,event_title,event_date"
            ).in_("profile_id", pids).in_("event_date", [today_s, tomorrow_s]) \
             .ilike("event_title", "%inset%").execute().data or [])]
        except Exception:
            pass
        schools = [
            {"child_name": p.get("child_name",""), "school_name": p.get("school_name",""), "address": p.get("address","")}
            for p in profiles
        ]
        holiday_status["inset_days"] = inset_rows

        # Dedup upcoming events before returning — fixes home brief + school card
        upcoming = _school_dedup_events(upcoming)

        # Extract action items due this week
        action_items = [
            {
                "child_name": e.get("child_name", ""),
                "title": e.get("event_title", ""),
                "due_date": e.get("event_date", ""),
                "action": e.get("action_needed", ""),
            }
            for e in upcoming
            if e.get("action_needed") and e.get("event_date") <= (today + timedelta(days=7)).isoformat()
        ]

        return {"schools": schools, "upcoming": upcoming, "recent": recent_rows,
                "events": upcoming, "actions": action_items, "holiday_status": holiday_status}
    except Exception:
        return {"schools": [], "upcoming": [], "recent": [], "events": [], "holiday_status": None}


def _receipt_category(merchant: str) -> str:
    """Map a merchant name to a spend category based on UK merchant patterns."""
    m = (merchant or "").lower().strip()
    if not m:
        return "Other"

    # Parking — check first (e.g. "NCP Parking", "Q-Park", "RingGo")
    if any(k in m for k in ["parking", "ncp", "q-park", "qpark", "apcoa", "saba park",
                              "justpark", "ringgo", "ringo", "paybyphone", "mipermit",
                              "car park", "parkingeye", "ukpc"]):
        return "Parking"

    # Fuel / Petrol — check BEFORE Groceries (so "Asda Fuel" → Fuel, not Groceries)
    if any(k in m for k in ["fuel", "petrol", "shell", "bp", "esso", "texaco", "total",
                              "applegreen", "murco", "service station", "fuel station"]):
        return "Fuel"

    # Groceries — supermarkets only (as specified)
    if any(k in m for k in ["tesco", "sainsbury", "asda", "morrisons", "waitrose",
                              "aldi", "lidl", "marks & spencer", "m&s food", "co-op", "coop",
                              "co op", "booths", "iceland food", "budgens", "costco",
                              "whole foods", "ocado", "spar"]):
        return "Groceries"

    # Coffee & Lunch (cafes, quick-service, bakeries)
    if any(k in m for k in ["pret", "starbucks", "costa", "caffe nero", "nero",
                              "greggs", "leon", "itsu", "wasabi", "coffee",
                              "paul bakery", "boston tea", "eat."]):
        return "Coffee & Lunch"

    # Lunch & Dining (sit-down restaurants, pubs)
    if any(k in m for k in ["kokorro", "nando", "wagamama", "pizza express", "pizzaexpress",
                              "zizzi", "ask italian", "bella italia", "prezzo", "frankie",
                              "harvester", "tgi", "gourmet burger", "byron", "five guys",
                              "shake shack", "honest burger", "turtle bay", "bills", "bill's",
                              "restaurant", "brasserie", "bistro", "tavern", "kitchen",
                              "grill", "smokehouse", "pub ", " inn ", "the crown", "the swan",
                              "the bull", "the fox", "the anchor", "the white"]):
        return "Dining"

    # Takeaway (Indian, Chinese, Thai, Vietnamese, etc.)
    if any(k in m for k in ["takeaway", "tandoori", "biryani", "curry", "indian",
                              "chinese", "thai", "vietnamese", "pho", "pad thai",
                              "dim sum", "jaipur", "maharaja", "taj", "spice",
                              "naan", "tikka", "samosa", "dosa", "basmati",
                              "wok", "dragon", "orient", "asia", "bangkok"]):
        return "Takeaway"

    # Fast Food
    if any(k in m for k in ["mcdonald", "kfc", "burger king", "subway", "papa john",
                              "domino", "pizza hut", "kebab", "chippy", "fish & chip",
                              "fish and chip", "fried chicken", "burger", "hot dog"]):
        return "Fast Food"

    # Transport
    if any(k in m for k in ["trainline", "national rail", "gwr", "swr", "southern rail",
                              "southeastern", "thameslink", "chiltern", "crosscountry",
                              "tfl", "transport for london", "oyster", "uber", "lyft",
                              "bolt ride", "national express", "megabus", "easyjet",
                              "british airways", "ryanair", "ba.com", "heathrow express"]):
        return "Transport"

    # Clothes (fashion retail)
    if any(k in m for k in ["zara", "h&m", "uniqlo", "topshop", "gap", "next ",
                              "asos", "selfridges", "john lewis", "debenhams",
                              "river island", "urban outfitters", "new look",
                              "fashion", "clothing", "apparel", "wardrobe"]):
        return "Clothes"

    # Accessories (shoes, bags, jewelry, beauty)
    if any(k in m for k in ["office", "clarks", "schuh", "boots beauty", "superdrug",
                              "dune", "ted baker", "reiss", "carvela", "aldo",
                              "timberland", "nike", "adidas", "sports direct",
                              "jewelry", "jewellery", "watch", "bag", "handbag",
                              "sunglasses", "boots pharmacy", "boots", "space nk",
                              "sephora", "beauty", "accessory", "footwear", "shoes"]):
        return "Accessories"

    # Shopping (general retail — books, home, etc.)
    if any(k in m for k in ["amazon", "waterstones", "argos", "currys",
                              "jd sport", "john lewis home", "dunelm",
                              "homebase", "b&q", "ikea", "wilko"]):
        return "Shopping"

    # Subscriptions / Digital
    if any(k in m for k in ["netflix", "spotify", "apple.com", "amazon prime", "disney",
                              "youtube premium", "sky ", "now tv", "bt sport", "google one"]):
        return "Subscriptions"

    return "Other"


def _v2_fetch_spend(from_number: str, month: int = None, quarter: int = None, year: int = None) -> dict:
    """Sum receipt clippings for a period, broken down by category. Excludes online orders."""
    import re as _re
    from datetime import date, datetime, timedelta
    try:
        today = date.today()
        # Determine date range
        if year and not month and not quarter:
            # Yearly: whole year
            period_start = date(year, 1, 1).isoformat()
            period_end = date(year + 1, 1, 1).isoformat()
            period_label = str(year)
        elif year and quarter:
            # Quarterly
            start_month = (quarter - 1) * 3 + 1
            period_start = date(year, start_month, 1).isoformat()
            if quarter == 4:
                period_end = date(year + 1, 1, 1).isoformat()
            else:
                period_end = date(year, start_month + 3, 1).isoformat()
            period_label = f"Q{quarter} {year}"
        elif year and month:
            # Monthly (default)
            period_start = date(year, month, 1).isoformat()
            if month == 12:
                period_end = date(year + 1, 1, 1).isoformat()
            else:
                period_end = date(year, month + 1, 1).isoformat()
            period_label = date(year, month, 1).strftime("%B %Y")
        else:
            # Default: this month
            period_start = today.replace(day=1).isoformat()
            if today.month == 12:
                period_end = date(today.year + 1, 1, 1).isoformat()
            else:
                period_end = date(today.year, today.month + 1, 1).isoformat()
            period_label = today.strftime("%B %Y")

        rows = lib._sb().table("wa_saves").select("summary,title,category,id") \
            .eq("from_number", from_number) \
            .gte("created_at", period_start) \
            .lt("created_at", period_end) \
            .ilike("title", "🧾%") \
            .execute().data or []

        # Deduplicate: same amount + same day = duplicate (keep first occurrence)
        # If amount is repeated on same day, it's the same transaction uploaded twice
        seen_by_key = {}  # (date_key, amount) → first receipt record
        deduplicated_rows = []
        for r in rows:
            created = r.get("created_at", "")
            date_key = created[:10]  # YYYY-MM-DD

            # Extract amount from summary
            m = _re.search(r'£([\d,]+\.?\d*)', r.get("summary", "") + r.get("title", ""))
            if not m:
                # No amount found, still add it (can't deduplicate without amount)
                deduplicated_rows.append(r)
                continue

            try:
                amount = float(m.group(1).replace(",", ""))
            except ValueError:
                deduplicated_rows.append(r)
                continue

            # Key: just date + amount
            key = (date_key, round(amount, 2))
            if key not in seen_by_key:
                seen_by_key[key] = True
                deduplicated_rows.append(r)

        # Log deduplication
        if len(deduplicated_rows) < len(rows):
            app.logger.info(f"[spend] Deduplicated {len(rows)} receipts → {len(deduplicated_rows)} (removed {len(rows)-len(deduplicated_rows)} duplicates by same amount on same day)")

        rows = deduplicated_rows
        total = 0.0; count = 0
        breakdown: dict = {}
        merchants_by_cat: dict = {}  # Track merchants per category for detailed breakdown
        for r in rows:
            merchant = (r.get("title") or "").replace("🧾", "").strip()
            # Skip online orders
            if merchant.startswith("Online:"):
                continue
            m = _re.search(r'£([\d,]+\.?\d*)', r.get("summary", "") + r.get("title", ""))
            if not m:
                continue
            try:
                amt = float(m.group(1).replace(",", ""))
            except ValueError:
                continue
            total += amt; count += 1
            # Determine category — always recategorize with latest logic
            cat = _receipt_category(merchant)
            # Also check items for better categorization (clothes/accessories)
            summary = (r.get("summary") or "").lower()
            if "clothes" not in cat.lower() and "accessories" not in cat.lower():
                clothes_kw = ["shirt", "jeans", "dress", "blouse", "pants", "trouser",
                              "jacket", "coat", "jumper", "sweater", "top", "skirt",
                              "shorts", "socks", "tights", "leggings", "trousers"]
                accessories_kw = ["shoes", "shoe", "boots", "trainers", "sneaker", "heels",
                                 "bag", "handbag", "backpack", "purse", "wallet",
                                 "belt", "scarf", "hat", "cap", "gloves", "sunglasses",
                                 "jewelry", "jewellery", "watch", "bracelet", "necklace"]
                if any(kw in summary for kw in clothes_kw):
                    cat = "Clothes"
                elif any(kw in summary for kw in accessories_kw):
                    cat = "Accessories"
            if cat not in breakdown:
                breakdown[cat] = {"total": 0.0, "count": 0, "merchants": {}}
                merchants_by_cat[cat] = {}
            breakdown[cat]["total"] = round(breakdown[cat]["total"] + amt, 2)
            breakdown[cat]["count"] += 1
            # Track merchant spending in this category
            if merchant not in merchants_by_cat[cat]:
                merchants_by_cat[cat][merchant] = 0.0
            merchants_by_cat[cat][merchant] += amt

        # Add top merchants to each category (sorted by amount)
        for cat in breakdown:
            merchants_list = [(m, merchants_by_cat[cat][m]) for m in merchants_by_cat[cat]]
            merchants_list.sort(key=lambda x: x[1], reverse=True)
            breakdown[cat]["merchants"] = [{"name": m[0], "total": round(m[1], 2)} for m in merchants_list[:5]]  # Top 5
        return {
            "total":     round(total, 2),
            "count":     count,
            "period":    period_label,
            "breakdown": breakdown,
        }
    except Exception:
        return {}


def _v2_fetch_today_activity(from_number: str) -> list:
    """Receipts from the last 8 hours — tells us what the user did today."""
    import datetime as _tadt
    try:
        _since = (_tadt.datetime.now() - _tadt.timedelta(hours=8)).strftime("%Y-%m-%dT%H:%M:%S")
        rows = lib._sb().table("receipts").select("merchant,category,total,shop_date") \
            .eq("phone", from_number) \
            .gte("shop_date", _since) \
            .order("shop_date", desc=False).limit(6).execute().data or []
        return [{"merchant": r.get("merchant",""), "category": r.get("category",""),
                 "total": r.get("total"), "time": (r.get("shop_date") or "")[:16]} for r in rows]
    except Exception:
        return []


def _v2_fetch_weekend_patterns(from_number: str) -> dict:
    """What the user tends to save/do on weekend evenings (5–11pm Sat/Sun) — inferred from history."""
    import datetime as _wpdt, collections as _wpc
    try:
        since = (_wpdt.date.today() - _wpdt.timedelta(days=60)).isoformat()
        rows = lib._sb().table("wa_saves").select("category,title,created_at") \
            .eq("from_number", from_number) \
            .gte("created_at", since + "T00:00:00") \
            .not_.in_("category", ["nearby", "place"]) \
            .order("created_at", desc=True).limit(100).execute().data or []
        cat_counts: dict = _wpc.Counter()
        for r in rows:
            ts = r.get("created_at", "")
            try:
                dt = _wpdt.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(
                    _wpdt.timezone(offset=_wpdt.timedelta(hours=1)))  # BST approx
                if dt.weekday() in (5, 6) and 17 <= dt.hour < 23:
                    cat = (r.get("category") or "").strip()
                    if cat and cat not in ("nearby", "place", ""):
                        cat_counts[cat] += 1
            except Exception:
                continue
        top = [c for c, _ in cat_counts.most_common(3)]
        return {"top_categories": top, "sample_size": sum(cat_counts.values())}
    except Exception:
        return {}


def _v2_fetch_saves(from_number: str) -> list:
    """Recent non-receipt saves (places, articles, clips) for surfacing in the brief."""
    from datetime import date, timedelta
    try:
        since = (date.today() - timedelta(days=30)).isoformat()
        rows = lib._sb().table("wa_saves").select(
            "title,summary,url,category,created_at"
        ).eq("from_number", from_number) \
         .not_.ilike("title", "🧾%") \
         .not_.ilike("title", "Pending intent%") \
         .neq("status", "pending_intent") \
         .gte("created_at", since) \
         .order("created_at", desc=True) \
         .limit(8).execute().data or []
        import re as _sre
        import json as _j

        # Always drop — unclassifiable image scans with no named content
        _ALWAYS_DROP = {"📷 Photo", "📢 Billboard/Ad", "🪧 Sign", "📄 Document"}
        # Generic titles where we try to extract a real name from the summary
        _TRY_EXTRACT = {"🎫 Event/Ticket", "🍷 Wine", "🍽️ Menu", "🏪 Place", "🏷️ Brand"}
        _ALL_GENERIC  = _ALWAYS_DROP | _TRY_EXTRACT | {"📦 Product"}
        _SKIP_PREFIXES = ("AIRESULT:", "META:", "PRODUCTS:", "SHOP:")
        # AI image-description phrases that add no value to the user
        _AI_DESC = ("the image", "this image", "the photo", "the picture",
                    "the poster", "the sign", "the advertisement", "the ticket",
                    "the screenshot", "it appears", "it shows")

        def _is_ai_noise(s: str) -> bool:
            return s.lower().startswith(_AI_DESC)

        def _clean_summary(raw: str) -> str:
            lines = (raw or "").splitlines()
            for ln in lines:
                ln = ln.strip()
                if not ln or any(ln.startswith(p) for p in _SKIP_PREFIXES):
                    continue
                ln = _sre.sub(r'^[•\-]\s*', '', ln).strip()
                # Strip common AI boilerplate prefixes that aren't caught by _is_ai_noise
                ln = _sre.sub(r'^(?:the event listing includes?|this listing (?:is for|includes?)|listing includes?)\s*', '', ln, flags=_sre.I).strip()
                if len(ln) > 8 and not _is_ai_noise(ln):
                    return ln[:100]
            return ""

        def _extract_title(raw_title: str, raw_summary: str) -> str:
            """For generic-titled saves, pull a real name from the summary."""
            t = raw_title.strip()
            if t not in _TRY_EXTRACT:
                return t
            emoji = t.split(" ")[0]  # e.g. "🎫"
            for ln in raw_summary.splitlines():
                ln = ln.strip()
                if ln.startswith("SHOP:"):
                    name = ln[5:].strip()
                    if name: return f"{emoji} {name}"
                if ln.startswith("AIRESULT:"):
                    try:
                        obj = _j.loads(ln[9:])
                        name = (obj.get("event_name") or obj.get("company") or
                                obj.get("brand") or obj.get("venue") or "")
                        if name and len(name) > 2:
                            return f"{emoji} {name}"
                    except Exception:
                        pass
                # Event: "includes X on Day DD Mon" → extract X
                m = _sre.search(r'includes (.+?) on (?:Mon|Tue|Wed|Thu|Fri|Sat|Sun|\d)', ln, _sre.I)
                if m:
                    return f"{emoji} {m.group(1).strip()}"
                # Plain short title line (not AI boilerplate)
                if not _is_ai_noise(ln) and len(ln.split()) <= 7 and not any(ln.startswith(p) for p in _SKIP_PREFIXES):
                    return f"{emoji} {ln}"
            return t  # keep generic — will be dropped if summary also empty

        result = []
        for r in rows:
            raw_title   = (r.get("title") or "").strip()
            raw_summary = r.get("summary") or ""
            # Hard-drop always-useless image scans
            if raw_title in _ALWAYS_DROP:
                continue
            # Drop anything whose best summary line is pure AI image description
            first_line = next(
                (ln.strip() for ln in raw_summary.splitlines()
                 if ln.strip() and not any(ln.strip().startswith(p) for p in _SKIP_PREFIXES)),
                ""
            )
            if _is_ai_noise(first_line):
                continue
            title   = _extract_title(raw_title, raw_summary)
            summary = _clean_summary(raw_summary)
            # Drop if still generic and no real content surfaced
            if title in _ALL_GENERIC and not summary:
                continue
            result.append({
                "title":      title,
                "summary":    summary,
                "url":        r.get("url", ""),
                "category":   r.get("category", ""),
                "source":     "clip",
                "created_at": r.get("created_at", ""),
            })

        # Also include recent receipt saves as "visited" places (last 30 days, newest first)
        receipt_rows = lib._sb().table("wa_saves").select(
            "title,category,created_at"
        ).eq("from_number", from_number) \
         .ilike("title", "🧾%") \
         .gte("created_at", since) \
         .order("created_at", desc=True) \
         .limit(6).execute().data or []

        seen_merchants = set()
        for r in receipt_rows:
            merchant = (r.get("title") or "").replace("🧾", "").strip()
            if not merchant or merchant in seen_merchants:
                continue
            seen_merchants.add(merchant)
            result.append({
                "title":      merchant,
                "summary":    "",
                "url":        "",
                "category":   r.get("category", ""),
                "source":     "receipt",
                "created_at": r.get("created_at", ""),
            })

        # Sort all by created_at desc (receipts and clips interleaved)
        result.sort(key=lambda x: x.get("created_at", ""), reverse=True)
        # Strip internal created_at before returning
        for item in result:
            item.pop("created_at", None)

        return result[:10]
    except Exception:
        return []


def _v2_fetch_calendar(from_number: str) -> list:
    """Fetch today's + tomorrow's Google Calendar events for the user."""
    try:
        _fn_plain = from_number.replace("whatsapp:", "").strip()
        _fn_wa    = f"whatsapp:{_fn_plain}"
        rows = lib._sb().table("ma_details").select("data") \
            .in_("device_id", [_fn_plain, _fn_wa]) \
            .eq("type", "calendar_token").execute().data
        if not rows:
            return []
        refresh_token = (rows[0].get("data") or {}).get("refresh_token", "")
        if not refresh_token:
            return []
        tr = requests.post("https://oauth2.googleapis.com/token", data={
            "refresh_token": refresh_token,
            "client_id":     _web_client_id(),
            "client_secret": _web_client_secret(),
            "grant_type":    "refresh_token",
        }, timeout=8)
        access_token = tr.json().get("access_token", "")
        if not access_token:
            return []
        from datetime import datetime as _cdt, timezone as _ctz, timedelta as _ctd
        now_utc      = _cdt.now(_ctz.utc)
        today_min    = now_utc.replace(hour=0, minute=0, second=0, microsecond=0)
        tomorrow_max = today_min + _ctd(days=2)
        er = requests.get(
            "https://www.googleapis.com/calendar/v3/calendars/primary/events",
            headers={"Authorization": f"Bearer {access_token}"},
            params={
                "timeMin":      today_min.isoformat(),
                "timeMax":      tomorrow_max.isoformat(),
                "singleEvents": "true",
                "orderBy":      "startTime",
                "maxResults":   "15",
            },
            timeout=8,
        )
        events = []
        for ev in er.json().get("items", []):
            title = (ev.get("summary") or "").strip()
            if not title or title.lower() == "busy":
                continue
            start   = ev.get("start", {})
            all_day = "date" in start and "dateTime" not in start
            raw     = start.get("dateTime") or start.get("date", "")
            start_label = ""
            date_label  = raw[:10] if raw else ""
            if raw and "T" in raw:
                try:
                    _s = _cdt.fromisoformat(raw.replace("Z", "+00:00"))
                    # Google Calendar events in dateTime format are already in the user's local timezone
                    # Don't add extra offset — just format the time as-is
                    start_label = _s.strftime("%-I:%M%p").lower().replace(":00am", "am").replace(":00pm", "pm")
                    date_label = _s.date().isoformat()
                except Exception:
                    pass
            location = (ev.get("location") or "").strip()
            events.append({"title": title, "start": start_label, "date": date_label, "all_day": all_day, "location": location})
        return events
    except Exception as e:
        app.logger.warning(f"[calendar] fetch: {e}")
        return []


def _v2_extract_birthdays_and_upcoming(calendar_events: list, now) -> tuple:
    """Extract birthdays from calendar and upcoming special dates.
    Returns (birthdays, upcoming_special) where:
    - birthdays: [{"name": "Jane", "date": "2026-06-23", "days_away": 8}, ...]
    - upcoming_special: list of dict with cultural/special observances
    """
    from datetime import datetime as _bdt, timedelta as _btd, date as _bdate
    birthdays = []
    upcoming = []
    today = now.date()

    for ev in calendar_events:
        title = (ev.get("title") or "").strip()
        if not title:
            continue
        ev_date = ev.get("date", "")
        if not ev_date or "T" in ev_date:  # skip times, we need just dates
            continue

        # Look for birthday events (case-insensitive)
        if "birthday" in title.lower() or "bday" in title.lower():
            # Extract name if format is "Jane's Birthday" or "Birthday - Jane"
            name = title.replace("'s Birthday", "").replace("Birthday", "").replace("—", "").replace("-", "").strip()
            if not name or name.lower() == "birthday":
                name = "Someone"
            try:
                ev_dt = _bdate.fromisoformat(ev_date)
                days_away = (ev_dt - today).days
                if 0 <= days_away <= 30:  # Only upcoming in next 30 days
                    birthdays.append({
                        "name": name,
                        "date": ev_date,
                        "days_away": days_away
                    })
            except (ValueError, TypeError):
                pass

    # Sort by days_away so closest birthdays come first
    birthdays.sort(key=lambda x: x["days_away"])
    return birthdays, upcoming


def _v2_fetch_rated_places(postcode: str, min_rating: float = 4.6) -> list:
    """Fetch highly-rated restaurants, cafes, bars, pubs around postcode (4.6+ rating).
    Returns list of {"name", "type", "rating", "distance_mi"} sorted by rating desc."""
    if not postcode:
        return []
    try:
        ll = postcode_to_latlon(postcode)
        if not ll:
            return []
        lat, lon = ll

        gm_key = (os.environ.get("GOOGLE_DIRECTIONS_KEY")
                  or os.environ.get("GOOGLE_PLACES_KEY")
                  or os.environ.get("GOOGLE_MAPS_KEY")
                  or os.environ.get("GOOGLE_API_KEY", ""))

        if not gm_key:
            return []

        rated_places = []
        place_types = ["restaurant", "cafe", "bar"]

        for place_type in place_types:
            try:
                r = requests.get(
                    "https://maps.googleapis.com/maps/api/place/nearbysearch/json",
                    params={
                        "location": f"{lat},{lon}",
                        "radius": 2000,  # 2km radius
                        "type": place_type,
                        "key": gm_key,
                    },
                    timeout=5,
                )
                if r.status_code == 200:
                    for result in r.json().get("results", []):
                        rating = result.get("rating", 0)
                        if rating < min_rating:
                            continue

                        name = result.get("name", "")
                        plat, plon = result.get("geometry", {}).get("location", {}).get("lat"), \
                                     result.get("geometry", {}).get("location", {}).get("lng")
                        if not name or not plat or not plon:
                            continue

                        dist_km = haversine_km(lat, lon, plat, plon)
                        dist_mi = dist_km / 1.60934

                        rated_places.append({
                            "name": name,
                            "type": place_type,
                            "rating": round(rating, 1),
                            "distance_mi": round(dist_mi, 1),
                        })
            except Exception:
                continue

        # Deduplicate by name, keep highest rated
        seen = {}
        for p in sorted(rated_places, key=lambda x: -x["rating"]):
            key = p["name"].lower()
            if key not in seen:
                seen[key] = p

        # Return top 5 by rating
        return sorted(seen.values(), key=lambda x: -x["rating"])[:5]
    except Exception as e:
        app.logger.debug(f"[rated-places] {postcode}: {e}")
        return []


def _v2_fetch_recent_capture(from_number: str) -> dict:
    """Return the most recent photo save from the last 20 minutes, if any.
    Used to surface 'you just snapped this' context in the V2 brief."""
    try:
        from datetime import datetime, timedelta
        cutoff = (datetime.utcnow() - timedelta(minutes=20)).isoformat()
        rows = lib._sb().table("wa_saves").select(
            "id,title,summary,category,image_url,created_at,source"
        ).eq("from_number", from_number) \
         .not_.is_("image_url", "null") \
         .gte("created_at", cutoff) \
         .order("created_at", desc=True) \
         .limit(1).execute().data or []
        return rows[0] if rows else {}
    except Exception:
        return {}


