def _find_food_nearby(lat: float, lon: float, place_type: str,
                      radius: int = 1500, cheap: bool = False,
                      keyword: str = "", required_types: list = None,
                      min_ratings: int = 100) -> list:
    key = os.environ.get("GOOGLE_PLACES_KEY", "")
    if not key:
        return []

    def _search(kw, rad):
        params = {"location": f"{lat},{lon}", "radius": rad,
                  "type": place_type, "key": key}
        if kw:
            params["keyword"] = kw
        r = requests.get(
            "https://maps.googleapis.com/maps/api/place/nearbysearch/json",
            params=params, timeout=10,
        )
        return r.json().get("results", [])

    try:
        results = _search(keyword, radius)
        # If fewer than 3 qualify after filtering, widen radius
        def _qualify(p):
            n = p.get("user_ratings_total", 0)
            if n < min_ratings:
                return False
            if required_types:
                p_types = p.get("types", [])
                if not any(t in p_types for t in required_types):
                    return False
            return True

        qualified = [p for p in results if _qualify(p)]
        if len(qualified) < 2:
            # Widen radius and relax min_ratings to 50
            results2 = _search(keyword, radius * 2)
            for p in results2:
                if p not in results:
                    results.append(p)
            qualified = [p for p in results if
                         p.get("user_ratings_total", 0) >= 50 and
                         (not required_types or any(t in p.get("types", []) for t in required_types))]

        items = []
        for p in qualified:
            loc = p.get("geometry", {}).get("location", {})
            plat, plon = loc.get("lat"), loc.get("lng")
            dist_km = haversine_km(lat, lon, plat, plon) if plat and plon else 999
            name = p.get("name", "")
            items.append({
                "name":        name,
                "place_id":    p.get("place_id", ""),
                "dist_km":     dist_km,
                "dist_mi":     round(dist_km * 0.621371, 1),
                "rating":      p.get("rating", 0),
                "n_ratings":   p.get("user_ratings_total", 0),
                "open_now":    p.get("opening_hours", {}).get("open_now"),
                "price_level": p.get("price_level"),
                "is_chain":    name.lower().strip() in _FOOD_CHAINS,
                "snippet":     "",
            })

        def _type_relevance(name, ptype, kw=""):
            """Score 0.1–1.0 for how well the place name matches the actual query."""
            n = name.lower()
            if ptype == "cafe":
                if kw == "tea":
                    # Tea search: tea rooms first, coffee shops pushed to the bottom
                    if any(w in n for w in ("tea", "tearoom", "tea room", "chai")):
                        return 1.0
                    if any(w in n for w in ("bakery", "patisserie", "deli", "garden", "house")):
                        return 0.75
                    if any(w in n for w in ("coffee", "cafe", "café", "espresso", "barista",
                                             "roast", "brew", "latte")):
                        return 0.25  # coffee shops are largely irrelevant for tea
                    if any(w in n for w in ("bistro", "bar", "pub", "grill", "brasserie",
                                             "restaurant", "hotel", "inn", "arms", "tavern")):
                        return 0.1
                    return 0.6
                else:
                    # Coffee/default search
                    if any(w in n for w in ("coffee", "cafe", "café", "espresso", "barista", "roast", "brew", "latte")):
                        return 1.0
                    if any(w in n for w in ("bakery", "patisserie", "tearoom", "tea room", "deli")):
                        return 0.85
                    if any(w in n for w in ("bistro", "bar", "pub", "grill", "brasserie",
                                             "restaurant", "hotel", "inn", "arms", "tavern", "kitchen")):
                        return 0.35
            if ptype == "restaurant":
                _ethnic = ("indian", "curry", "spice", "balti", "tandoor", "masala", "biryani",
                           "thai", "chinese", "sushi", "japanese", "dim sum", "noodle",
                           "pizza", "pizzeria", "pasta", "italian", "turkish", "lebanese",
                           "persian", "arabic", "bangladeshi", "pakistani", "sri lanka",
                           "vietnamese", "korean", "mexican", "tapas", "spanish")
                if kw == "steak":
                    if any(w in n for w in ("steak", "steakhouse", "chophouse", "chop house", "ribeye", "sirloin", "wagyu")):
                        return 1.0
                    if any(w in n for w in ("brasserie", "butcher", "prime", "miller", "carter")):
                        return 0.9
                    if "grill" in n and not any(w in n for w in ("smash", "burger", "chicken", "halal", "kebab", "fried")):
                        return 0.75  # generic grill — might have steak
                    if any(w in n for w in ("smash", "burger", "fried chicken", "halal")):
                        return 0.05  # burger/fast food joints, not steakhouses
                    if any(w in n for w in _ethnic):
                        return 0.05
                    return 0.65
                if kw == "burger":
                    if any(w in n for w in ("burger", "smash", "shack", "joint", "patty", "grill")):
                        return 1.0
                    if any(w in n for w in _ethnic):
                        return 0.15
                    return 0.7
                if kw == "kebab":
                    if any(w in n for w in ("kebab", "shawarma", "doner", "turkish", "lebanese", "arabic", "persian", "grill")):
                        return 1.0
                    if any(w in n for w in ("indian", "curry", "balti", "tandoor")):
                        return 0.5  # some crossover
                    return 0.6
                if kw == "indian restaurant":
                    if any(w in n for w in ("indian", "india", "curry", "balti", "tandoor", "masala", "tikka",
                                            "biryani", "korma", "spice", "saffron", "mughul", "mogul", "bengali",
                                            "bangladeshi", "pakistani", "punjabi", "delhi", "bombay", "mumbai")):
                        return 1.0
                    if any(w in n for w in ("restaurant", "kitchen", "house", "palace", "raj", "maharaja")):
                        return 0.7
                    if any(w in n for w in ("pizza", "burger", "kebab", "chinese", "thai", "italian", "pub")):
                        return 0.05
                    return 0.5
                if kw == "italian restaurant":
                    if any(w in n for w in ("italian", "italy", "pizza", "pasta", "trattoria", "osteria",
                                            "ristorante", "pizzeria", "napoli", "naples", "rome", "sicily",
                                            "venice", "florence", "romano", "bella", "la dolce", "al dente")):
                        return 1.0
                    if any(w in n for w in ("cafe", "bistro", "kitchen")):
                        return 0.6
                    if any(w in n for w in ("indian", "burger", "kebab", "chinese", "thai", "pub")):
                        return 0.05
                    return 0.5
                if kw == "mexican restaurant":
                    if any(w in n for w in ("mexican", "mexico", "taco", "burrito", "quesadilla", "tex mex",
                                            "cantina", "hacienda", "taqueria", "jalisco", "oaxaca", "tijuana")):
                        return 1.0
                    if any(w in n for w in ("kitchen", "grill", "bar")):
                        return 0.6
                    if any(w in n for w in ("indian", "burger", "kebab", "chinese", "italian", "pub")):
                        return 0.05
                    return 0.5
                if kw == "fish and chips":
                    if any(w in n for w in ("fish", "chip", "chippy", "cod", "haddock", "fryer", "frier",
                                            "fishmonger", "seafood", "fry", "plaice", "fisherman")):
                        return 1.0
                    if any(w in n for w in ("burger", "kebab", "pizza", "chinese", "indian", "italian")):
                        return 0.05
                    return 0.4
                if kw == "chinese restaurant":
                    if any(w in n for w in ("chinese", "china", "dim sum", "peking", "canton", "hong kong",
                                            "szechuan", "sichuan", "mandarin", "beijing", "shanghai", "wonton")):
                        return 1.0
                    if any(w in n for w in ("noodle", "oriental", "asian", "dragon", "golden", "jade",
                                            "palace", "dynasty", "emperor", "bamboo", "lotus", "panda")):
                        return 0.85  # probably Chinese
                    if any(w in n for w in ("thai", "japanese", "korean", "vietnamese", "malaysian", "singaporean")):
                        return 0.3  # Asian but not Chinese
                    if any(w in n for w in ("indian", "curry", "pizza", "burger", "kebab", "pub", "italian")):
                        return 0.05
                    return 0.6
            if ptype == "bar":
                if kw == "wine bar":
                    if any(w in n for w in ("wine", "vino", "cellar", "cave", "vineyard", "winery", "sommelier")):
                        return 1.0
                    if any(w in n for w in ("bar", "bistro", "brasserie", "kitchen")):
                        return 0.75
                    if any(w in n for w in ("pub", "inn", "arms", "tavern", "sports")):
                        return 0.3
                if kw == "cocktail bar":
                    if any(w in n for w in ("cocktail", "mixology", "speakeasy", "negroni", "martini", "lounge")):
                        return 1.0
                    if any(w in n for w in ("bar", "club", "social", "house")):
                        return 0.8
                    if any(w in n for w in ("pub", "inn", "arms", "sports")):
                        return 0.2
                if kw in ("pub", "beer"):
                    if any(w in n for w in ("pub", "inn", "arms", "tavern", "brewery", "tap", "ale", "beer")):
                        return 1.0
                    if any(w in n for w in ("bar", "bistro", "kitchen")):
                        return 0.8
                    if any(w in n for w in ("wine", "cocktail", "champagne", "prosecco")):
                        return 0.4
            return 0.75  # neutral / unknown

        if cheap:
            items.sort(key=lambda x: (x["price_level"] or 9, -x["rating"], x["dist_km"]))
        else:
            items.sort(key=lambda x: (
                -x["rating"] * _type_relevance(x["name"], place_type, keyword) * (1.0 if x["open_now"] is not False else 0.9),
                x["dist_km"],
            ))
        return items
    except Exception as e:
        print(f"[food_nearby] {e}")
        return []


def _places_review_snippet(place_id: str, keywords: list) -> str:
    """Return a highly-positive sentence from Google Places reviews matching any keyword."""
    key = os.environ.get("GOOGLE_PLACES_KEY", "")
    if not key or not place_id:
        return ""
    try:
        r = requests.get(
            "https://maps.googleapis.com/maps/api/place/details/json",
            params={"place_id": place_id, "fields": "reviews", "key": key},
            timeout=4,
        )
        reviews = r.json().get("result", {}).get("reviews", [])
        # Only use 4- and 5-star reviews
        reviews = [rv for rv in reviews if rv.get("rating", 0) >= 4]
        reviews.sort(key=lambda rv: -rv.get("rating", 0))

        best_score = 0
        best_sentence = ""

        for review in reviews:
            text = review.get("text", "").replace("\n", " ")
            # Split into sentences
            sentences = re.split(r'(?<=[.!?])\s+', text)
            for sent in sentences:
                sent_l = sent.lower()
                kw_hit = any(kw in sent_l for kw in keywords)
                if not kw_hit:
                    continue
                pos_hits = sum(1 for w in _REVIEW_POSITIVES if w in sent_l)
                if pos_hits == 0:
                    continue
                score = pos_hits + review.get("rating", 4) - 4
                if score > best_score and len(sent) <= 100:
                    best_score = score
                    best_sentence = sent.strip()

        if best_sentence:
            return f'"{best_sentence}"'
    except Exception:
        pass
    return ""



def _fetch_place_hours(destination: str) -> dict:
    """Fetch opening hours for a named place via Google Places. Returns {} on failure."""
    key = os.environ.get("GOOGLE_PLACES_KEY") or os.environ.get("GOOGLE_API_KEY", "")
    if not key:
        return {}
    try:
        # Text search to get place_id
        ts = requests.get(
            "https://maps.googleapis.com/maps/api/place/textsearch/json",
            params={"query": destination + " UK", "key": key, "region": "uk"},
            timeout=6,
        )
        results = ts.json().get("results", [])
        if not results:
            return {}
        place_id = results[0].get("place_id", "")
        if not place_id:
            return {}
        # Place Details for opening hours
        pd = requests.get(
            "https://maps.googleapis.com/maps/api/place/details/json",
            params={"place_id": place_id, "fields": "name,opening_hours", "key": key},
            timeout=6,
        )
        oh = pd.json().get("result", {}).get("opening_hours", {})
        if not oh:
            return {}
        # weekday_text is ["Monday: 9:00 AM – 8:00 PM", ...] starting from Monday
        weekday_text = oh.get("weekday_text", [])
        today_idx    = __import__("datetime").datetime.now().weekday()  # 0=Mon
        today_hours  = weekday_text[today_idx] if weekday_text else ""
        # Strip day prefix ("Monday: ")
        if today_hours and ": " in today_hours:
            today_hours = today_hours.split(": ", 1)[1]
        return {
            "open_now":    oh.get("open_now"),
            "today_hours": today_hours,
            "weekday_text": weekday_text,  # full week for next-open lookup
        }
    except Exception:
        return {}


def _next_opening_str(weekday_text: list) -> str:
    """Given weekday_text (Mon-indexed), return e.g. 'Opens tomorrow at 10:00 AM' or 'Opens Monday at 10:00 AM'."""
    if not weekday_text:
        return ""
    day_names = ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"]
    today_idx = __import__("datetime").datetime.now().weekday()  # 0=Mon
    for offset in range(1, 8):
        idx = (today_idx + offset) % 7
        entry = weekday_text[idx] if idx < len(weekday_text) else ""
        if not entry:
            continue
        hours_part = entry.split(": ", 1)[1] if ": " in entry else entry
        if hours_part.lower() in ("closed", ""):
            continue
        # Extract just the opening time (first time mentioned)
        import re as _re
        t = _re.search(r'\d{1,2}:\d{2}\s*[AP]M', hours_part)
        open_time = t.group(0) if t else hours_part
        label = "tomorrow" if offset == 1 else day_names[idx]
        return f"Opens {label} at {open_time}"
    return ""


_SCHOOL_LOCATION_WORDS = {
    "school","academy","college","primary","junior","secondary","senior",
    "infant","nursery","prep","grammar","comprehensive","sixth","form","class",
}

def _compute_activity_drive_context(ra: dict, origin_postcode: str, now, weather: dict) -> str:
    """
    For a recurring activity happening today, return a pre-computed fact string
    combining: who, what, time, drive time (if external venue), leave-by, weather tip.

    Returns empty string if the activity has already passed or is at school.
    """
    try:
        activity = ra.get("activity", "")
        child    = ra.get("child", "")
        location = (ra.get("location") or "").strip()
        time_str = (ra.get("time") or "").strip()   # "HH:MM" 24h

        if not activity:
            return ""

        # Parse activity time
        act_hh, act_mm = 0, 0
        if time_str and ":" in time_str:
            try:
                act_hh, act_mm = int(time_str.split(":")[0]), int(time_str.split(":")[1])
            except Exception:
                pass
        act_minutes = act_hh * 60 + act_mm
        now_minutes = now.hour * 60 + now.minute

        # Skip if already started or more than 5 hours away (not immediately actionable)
        if act_minutes <= now_minutes:
            return ""
        if act_minutes - now_minutes > 300:
            return ""

        # Format display time as 12h
        _period = "am" if act_hh < 12 else "pm"
        _disp_h = act_hh if act_hh <= 12 else act_hh - 12
        _disp_h = 12 if _disp_h == 0 else _disp_h
        time_display = f"{_disp_h}:{act_mm:02d}{_period}"

        who_prefix = f"{child} — " if child else ""
        base = f"{who_prefix}{activity}"

        # Detect school/on-site activity — no drive needed
        loc_words = set(location.lower().split())
        is_at_school = not location or bool(loc_words & _SCHOOL_LOCATION_WORDS)

        if is_at_school:
            loc_note = " (at school — no travel)" if location else " (at school)"
            return f"📅 {base} at {time_display}{loc_note}"

        # External venue — compute drive time
        key = os.environ.get("GOOGLE_DIRECTIONS_KEY") or os.environ.get("GOOGLE_API_KEY", "")
        if not key or not origin_postcode:
            return f"📅 {base} at {time_display} @ {location}"

        from_geo = _geocode_place(origin_postcode + " UK")
        # Use pre-resolved coordinates if saved, else geocode now
        if ra.get("lat") and ra.get("lng"):
            to_geo = (ra["lat"], ra["lng"])
        else:
            to_geo = _geocode_place((ra.get("location_resolved") or location) + " UK")
        if not from_geo or not to_geo:
            return f"📅 {base} at {time_display} @ {location}"

        r = requests.get(
            "https://maps.googleapis.com/maps/api/directions/json",
            params={
                "origin":         f"{from_geo[0]},{from_geo[1]}",
                "destination":    f"{to_geo[0]},{to_geo[1]}",
                "mode":           "driving",
                "departure_time": "now",
                "traffic_model":  "best_guess",
                "key":            key,
            },
            timeout=6,
        )
        d = r.json()
        if d.get("status") != "OK":
            return f"📅 {base} at {time_display} @ {location}"

        leg   = d["routes"][0]["legs"][0]
        dur_s = leg.get("duration_in_traffic", leg["duration"])["value"]
        dur_m = (dur_s + 59) // 60  # round up minutes

        # Leave-by = activity time - drive - 5 min buffer
        leave_total = act_minutes - dur_m - 5
        leave_h, leave_m = leave_total // 60, leave_total % 60
        leave_period = "am" if leave_h < 12 else "pm"
        leave_dh = leave_h if leave_h <= 12 else leave_h - 12
        leave_dh = 12 if leave_dh == 0 else leave_dh
        leave_str = f"{leave_dh}:{leave_m:02d}{leave_period}"

        delay   = max(0, dur_s - leg["duration"]["value"])
        traffic = "heavy traffic" if delay > 600 else "some traffic" if delay > 180 else ""
        traffic_note = f" ({traffic})" if traffic else ""

        fact = (f"📅 {base} at {time_display} @ {location} — "
                f"{dur_m} min drive{traffic_note}, leave by {leave_str}")

        # Append weather tip if extreme and not already in a previous activity fact
        temp = (weather or {}).get("temp", 15)
        if temp >= 28:
            fact += f". {temp}°C — take water & sunscreen"
        elif temp <= 1:
            fact += f". {temp}°C — roads may be icy"

        return fact
    except Exception:
        return ""


def _inline_fuel_snippet(postcode: str) -> str:
    """Return 2-line cheapest petrol snippet for embedding in drive-time cards."""
    try:
        latlon = postcode_to_latlon(postcode)
        if not latlon:
            return ""
        lat, lon = latlon
        nearby = _nearby_stations(lat, lon, "petrol", 8.0)
        if not nearby:
            return ""
        nearby.sort(key=lambda x: (x["price"], x["dist_mi"]))
        lines = [f"\n⛽ Cheapest petrol near {postcode.upper()}:"]
        for s in nearby[:2]:
            lines.append(f"• {s['brand']} — {s['price']:.1f}p ({s['dist_mi']:.1f} mi)")
        return "\n".join(lines)
    except Exception:
        return ""


def _drive_weather_tip(postcode: str, from_number: str = "") -> str:
    """Return a one-line weather tip — but only once per user per day."""
    try:
        today = datetime.now().strftime("%Y-%m-%d")
        warn_key = f"{from_number}:{today}"
        if from_number and _WA_WEATHER_WARNED.get(warn_key):
            return ""  # already warned today
        w = _v2_fetch_weather(postcode)
        if not w:
            return ""
        temp = w.get("temp", 15)
        if temp >= 28:
            tip = f"☀️ {temp}°C today — take water, it'll be busy. Park in the shade if you can."
        elif temp <= 1:
            tip = f"🧊 {temp}°C — roads may be icy, allow extra time."
        elif "rain" in (w.get("desc") or "").lower():
            tip = f"🌧️ Rain on the way — allow a bit of extra time."
        else:
            return ""
        if from_number:
            _WA_WEATHER_WARNED[warn_key] = True
        return "\n" + tip
    except Exception:
        return ""


def _heading_to_drive_reply(destination: str, origin_postcode: str, specific_dest: str = None, dest_geo: tuple = None, from_number: str = "") -> str:
    """Build the drive time + hours reply for a confirmed destination."""
    key = os.environ.get("GOOGLE_DIRECTIONS_KEY") or os.environ.get("GOOGLE_API_KEY", "")
    query = specific_dest or (destination + " UK")
    from concurrent.futures import ThreadPoolExecutor
    if dest_geo:
        with ThreadPoolExecutor(max_workers=3) as pool:
            f_from    = pool.submit(_geocode_place, origin_postcode + " UK")
            f_hours   = pool.submit(_fetch_place_hours, specific_dest or destination)
            f_weather = pool.submit(_drive_weather_tip, origin_postcode, from_number)
            from_geo     = f_from.result()
            to_geo       = dest_geo
            hours        = f_hours.result()
            weather_tip  = f_weather.result()
    else:
        with ThreadPoolExecutor(max_workers=4) as pool:
            f_from    = pool.submit(_geocode_place, origin_postcode + " UK")
            f_to      = pool.submit(_geocode_place, query)
            f_hours   = pool.submit(_fetch_place_hours, specific_dest or destination)
            f_weather = pool.submit(_drive_weather_tip, origin_postcode, from_number)
            from_geo     = f_from.result()
            to_geo       = f_to.result()
            hours        = f_hours.result()
            weather_tip  = f_weather.result()
    if not from_geo or not to_geo or not key:
        return f"Have a good trip to {destination}!"
    try:
        r = requests.get(
            "https://maps.googleapis.com/maps/api/directions/json",
            params={
                "origin":         f"{from_geo[0]},{from_geo[1]}",
                "destination":    f"{to_geo[0]},{to_geo[1]}",
                "mode":           "driving",
                "departure_time": "now",
                "traffic_model":  "best_guess",
                "key":            key,
            },
            timeout=8,
        )
        d = r.json()
        if d.get("status") != "OK":
            return f"Have a good trip to {destination}!"
        leg      = d["routes"][0]["legs"][0]
        dur_s    = leg.get("duration_in_traffic", leg["duration"])["value"]
        delay    = max(0, dur_s - leg["duration"]["value"])
        traffic  = "heavy" if delay > 600 else "moderate" if delay > 180 else "clear"
        emoji    = "🔴" if traffic == "heavy" else "🟡" if traffic == "moderate" else "🟢"
        dur_min  = dur_s // 60
        dist     = leg["distance"]["text"]
        via      = d["routes"][0].get("summary", "")
        _is_closed = hours.get("open_now") is False
        _is_open   = hours.get("open_now") is True
        lines = [f"🚗 {destination.title()}"]

        # Closed warning leads — don't bury it after the drive time
        if _is_closed:
            _next = _next_opening_str(hours.get("weekday_text", []))
            _closed_line = f"⚠️ Closed right now"
            if _next:
                _closed_line += f" — {_next}"
            elif hours.get("today_hours"):
                _closed_line += f" (today: {hours['today_hours']})"
            _closed_line += ". Still want to head there?"
            lines.append(_closed_line)

        lines.append(f"{emoji} About {dur_min} min · {dist}" + (f" via {via}" if via else ""))
        if traffic == "heavy":      lines.append("Traffic is heavy right now.")
        elif traffic == "moderate": lines.append("Some traffic on the way.")

        # Hours line — only show when open (closed already shown above)
        if _is_open and hours.get("today_hours"):
            lines.append(f"\U0001f550 Today: {hours['today_hours']} ✅ Open now")

        if weather_tip:
            lines.append(weather_tip)
        _lat2, _lng2 = to_geo
        lines.append(
            f"\n🗺️ https://maps.google.com/maps?q={_lat2},{_lng2}"
            f"\n🚦 https://waze.com/ul?ll={_lat2},{_lng2}&navigate=yes"
        )
        reply = "\n".join(lines)
        if from_number:
            _log_place_visit(from_number, destination, destination.lower(), lat=_lat2, lng=_lng2)
            _set_wa_pending_intent(from_number, {"type": "regular_place", "name": destination})
            reply += "\n\n_Reply *regular* to save as a frequent place._"
            # Store trip card so home brief can surface it while user is still preparing
            import datetime as _tdt
            _trip = {
                "destination": destination.title(),
                "lat": _lat2, "lng": _lng2,
                "dur_min": dur_min,
                "dist": dist,
                "via": via,
                "traffic": traffic,
                "expires_at": (_tdt.datetime.utcnow() + _tdt.timedelta(hours=2)).isoformat(),
            }
            try:
                _tp = from_number.replace("whatsapp:", "").strip()
                lib._sb().table("ma_details").delete().eq("device_id", _tp).eq("type", "active_trip").execute()
                lib._sb().table("ma_details").insert({"device_id": _tp, "type": "active_trip", "data": _trip, "label": "active_trip"}).execute()
            except Exception as _te:
                app.logger.warning(f"[active_trip] store error: {_te}")
        return reply
    except Exception:
        return f"Have a good trip to {destination}!"


# Known chain brands — single word or short name without a location qualifier
_CHAIN_BRANDS = {
    "costco","tesco","sainsburys","sainsbury","asda","waitrose","aldi","lidl",
    "morrisons","marks","ikea","b&q","screwfix","homebase","wickes","dunelm",
    "next","primark","argos","halfords","currys","boots","superdrug","john lewis",
}


def _wa_heading_to(body: str, from_number: str) -> str | None:
    """Detect travel intent and reply with nearest branches or drive time."""
    b = body.strip()

    # Pattern 1: "I’m heading/going/on my way/driving to X"
    _HEADING_RE = re.compile(
        r"^(?:i[‘’]?m\s+(?:heading|going|on\s+my\s+way|driving|heading\s+out|popping|nipping)\s+to\s+|"
        r"off\s+to\s+|heading\s+to\s+|going\s+to\s+|on\s+my\s+way\s+to\s+|"
        r"i[‘’]?m\s+(?:heading|going|driving|popping|nipping)\s+)"  # "i’m heading ikea" without "to"
        r"(.{3,60})$", re.I
    )
    m = _HEADING_RE.match(b)

    # Pattern 1b: typo-tolerant — one garbled word then "to [chain]" e.g. "ging to ikea"
    if not m and len(b.split()) <= 6:
        _typo_m = re.match(r'^\S{1,8}\s+to\s+(.{3,50})$', b, re.I)
        if _typo_m:
            candidate = _typo_m.group(1).strip().lower()
            if any(brand in candidate for brand in _CHAIN_BRANDS):
                m = _typo_m

    # Pattern 2: "[chain] near me" — treat as travel intent
    _NEAR_ME_RE = re.compile(r"^(.{3,40}?)\s+near\s+me\s*$", re.I)
    if not m:
        nm = _NEAR_ME_RE.match(b)
        if nm:
            candidate = nm.group(1).strip().lower()
            if any(brand in candidate for brand in _CHAIN_BRANDS):
                m = nm  # reuse match, group(1) is destination

    if not m:
        return None
    destination = m.group(1).strip().rstrip(".")

    # Get user’s home postcode
    origin = None
    try:
        rows = lib._sb().table("ma_details").select("data") \
            .eq("device_id", from_number).eq("type", "v2_prefs").limit(1).execute().data or []
        prefs = rows[0]["data"] if rows else {}
        origin = prefs.get("fuel_postcode") or prefs.get("home_postcode")
    except Exception:
        pass
    if not origin:
        return f"Enjoy your trip to {destination}! Send me your postcode and I’ll check drive time."

    # Is this a chain name with no location qualifier?
    dest_words = destination.lower().split()
    dest_clean = destination.lower().strip()
    is_chain = dest_clean in _CHAIN_BRANDS or (len(dest_words) == 1 and dest_clean in _CHAIN_BRANDS)
    # Also treat as chain if destination matches a known brand exactly (no extra town/area words)
    if not is_chain:
        for brand in _CHAIN_BRANDS:
            if dest_clean == brand or dest_clean == brand + "s":
                is_chain = True
                break

    if is_chain:
        # Find nearest branches via nearbySearch ranked by distance (not prominence)
        gkey = os.environ.get("GOOGLE_PLACES_KEY") or os.environ.get("GOOGLE_API_KEY", "")
        home_geo = _geocode_place(origin + " UK")
        branches = []
        if home_geo and gkey:
            try:
                import math as _math
                r = requests.get(
                    "https://maps.googleapis.com/maps/api/place/nearbysearch/json",
                    params={
                        "location": f"{home_geo[0]},{home_geo[1]}",
                        "keyword":  destination,
                        "rankby":   "distance",   # nearest first, not most prominent
                        "key":      gkey,
                    },
                    timeout=8,
                )
                for p in r.json().get("results", [])[:8]:  # take 8, filter to 3 nearest
                    loc = p.get("geometry", {}).get("location", {})
                    if not loc:
                        continue
                    dlat = loc["lat"] - home_geo[0]
                    dlng = loc["lng"] - home_geo[1]
                    dist_km = _math.sqrt(dlat**2 + dlng**2) * 111
                    name = p.get("name", destination.title())
                    branches.append({"name": name, "dist_km": dist_km,
                                     "lat": loc["lat"], "lng": loc["lng"]})
                branches.sort(key=lambda x: x["dist_km"])
                branches = branches[:3]
            except Exception:
                pass

        if len(branches) >= 2:
            lines = [f"🛒 Which {destination.title()}?"]
            for i, b in enumerate(branches, 1):
                dist_mi = round(b["dist_km"] * 0.621, 1)
                lines.append(f"{i}. {b['name']} ({dist_mi} mi)")
            lines.append(f"\nReply *1*, *2* or *3*")
            # Store pending intent with branch options
            _set_wa_pending_intent(from_number, {
                "type": "heading_to_pick",
                "destination": destination,
                "origin": origin,
                "branches": branches,
            })
            return "\n".join(lines)

    # Specific location or chain lookup failed — go direct
    return _heading_to_drive_reply(destination, origin, from_number=from_number)


def _wa_food_find(body: str, from_number: str):
    """Return WhatsApp-formatted food/drink picks, or None if not a food query."""
    # Normalise typos: collapse 3+ repeated letters (coffeee→coffee, beeer→beer)
    body_lower = re.sub(r'(.)\1{2,}', r'\1\1', body.lower())

    # Recipe requests take priority — don't match "negroni recipe" as a nearby bar search
    if re.search(r'\brecipe\b|\bhow\s+to\s+make\b|\bhow\s+do\s+i\s+make\b|\bingredients\s+for\b', body_lower):
        return None

    intent = None
    for pattern, info in _FOOD_INTENTS:
        if pattern.search(body_lower):
            intent = info
            break
    if not intent:
        return None

    # Some categories (steak, burger) are always about quality — never sort by price
    wants_cheap = bool(re.search(r'\bcheap\b', body_lower)) and not intent.get("always_best")

    # Postcode from message — accept full (KT16 0DA) or outward-only (KT16)
    _full_pc  = re.search(r'[A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2}', body.upper())
    _out_pc   = re.search(r'\b([A-Z]{1,2}\d{1,2}[A-Z]?)\b', body.upper())
    lat = lon = None
    pc_fmt = ""

    if _full_pc:
        postcode = _full_pc.group(0).replace(" ", "")
        try:
            r2 = requests.get(f"https://api.postcodes.io/postcodes/{postcode}", timeout=5)
            if r2.status_code == 200:
                res = r2.json().get("result", {})
                lat, lon = res.get("latitude"), res.get("longitude")
                pc_fmt = postcode[:-3] + " " + postcode[-3:]
        except Exception:
            pass
    if lat is None and _out_pc:
        outcode = _out_pc.group(1)
        try:
            r2 = requests.get(f"https://api.postcodes.io/outcodes/{outcode}", timeout=5)
            if r2.status_code == 200:
                res = r2.json().get("result", {})
                lat, lon = res.get("latitude"), res.get("longitude")
                pc_fmt = outcode
        except Exception:
            pass
    _wants_live = bool(re.search(r'\b(here|near me|around here|where i am|current(ly)?)\b', body_lower))

    if lat is None:
        # Use recently shared live location if available (within 2 hours)
        _loc = _USER_LAST_LOCATION.get(from_number)
        if _loc and (time.time() - _loc.get("ts", 0)) < 7200:
            lat, lon = _loc["lat"], _loc["lon"]
            pc_fmt = "your location"

    if lat is None:
        # Fall back to stored home postcode (unless user explicitly wants live location)
        if not _wants_live:
            stored = _get_wa_home_postcode(from_number)
            if stored:
                try:
                    r2 = requests.get(f"https://api.postcodes.io/postcodes/{stored}", timeout=5)
                    if r2.status_code == 200:
                        res = r2.json().get("result", {})
                        lat, lon = res.get("latitude"), res.get("longitude")
                        pc_fmt = stored[:-3] + " " + stored[-3:]
                except Exception:
                    pass

    if lat is None:
        _set_wa_pending_intent(from_number, {
            "type": "food", "food_type": intent["label"], "cheap": wants_cheap
        })
        if _wants_live:
            return (f"{intent['emoji']} Drop your location pin and I'll find the best {intent['label']} right where you are.\n\n"
                    f"_(Tap the 📎 attachment icon → Location → Send current location)_")
        return (f"{intent['emoji']} Where are you?\n\n"
                f"Reply with your postcode or drop your location pin — I'll find the best {intent['label']} near you.\n"
                f"_(Or set your home postcode at miru.humanagency.co so you never need to send it)_")

    places = _find_food_nearby(lat, lon, intent["type"],
                               cheap=wants_cheap,
                               keyword=intent.get("keyword", ""),
                               required_types=intent.get("required_types", []),
                               radius=intent.get("radius", 1500))
    if not places:
        return f"No {intent['label']} spots found near {pc_fmt}. Sorry!"

    emoji, label = intent["emoji"], intent["label"]
    keywords = intent.get("review_terms", [])

    # Pick top and optional second before fetching reviews
    top = places[0]
    second = None
    if top["is_chain"]:
        indys = [p for p in places[1:] if not p["is_chain"] and p["rating"] >= 4.0]
        if indys:
            second = indys[0]
    elif len(places) > 1 and places[1]["rating"] >= 4.0 and places[1]["dist_km"] <= 1.0:
        second = places[1]

    # Fetch review snippets in parallel (max 4s total)
    # Only show snippet if the place name itself suggests it fits the category
    _cat_words = intent.get("keyword", "").lower().split()
    def _is_relevant(p):
        if not _cat_words:
            return True
        name_l = p["name"].lower()
        return any(w in name_l for w in _cat_words)

    picks = [p for p in [top, second] if p]
    if keywords and picks:
        with ThreadPoolExecutor(max_workers=2) as exe:
            futs = {exe.submit(_places_review_snippet, p["place_id"], keywords): i
                    for i, p in enumerate(picks)}
            for fut in futs:
                i = futs[fut]
                try:
                    snippet = fut.result(timeout=4)
                    # Suppress snippet if place seems off-category (e.g. restaurant in coffee results)
                    picks[i]["snippet"] = snippet if _is_relevant(picks[i]) else ""
                except Exception:
                    picks[i]["snippet"] = ""

    def _line(p):
        parts = []
        if p["rating"]:
            parts.append(f"{p['rating']}★")
        if p["price_level"]:
            parts.append(_PRICE_LEVEL.get(p["price_level"], ""))
        parts.append(f"{p['dist_mi']}mi")
        if p["open_now"] is True:
            parts.append("Open now")
        elif p["open_now"] is False:
            parts.append("May be closed")
        out = f"*{p['name']}* · " + " · ".join(filter(None, parts))
        if p.get("snippet"):
            out += f"\n_{p['snippet']}_"
        return out

    prefix = f"Cheap {label}" if wants_cheap else f"Best {label}"
    if second:
        return (f"{emoji} *{label.title()} near {pc_fmt}*\n\n"
                f"{_line(top)}\n\n{_line(second)}\n\nmiru.humanagency.co")
    return (f"{emoji} *{prefix} near {pc_fmt}*\n\n"
            f"{_line(top)}\n\nmiru.humanagency.co")


def _split_product_postcode(body: str):
    """Return (product_name, postcode_or_None) from a freeform message."""
    m = re.search(r'([A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2})', body.upper())
    if not m:
        return body.strip(), None
    postcode = m.group(1).replace(" ", "")
    remaining = (body[:m.start()] + " " + body[m.end():]).strip()
    return remaining, postcode


def _wa_train_format(from_name: str, to_name: str = "") -> str:
    """Return WhatsApp-formatted train departures. Returns None if station not found."""
    if not from_name:
        return None
    try:
        # Strip qualifier words users add (e.g. "Lewisham national rail" → "lewisham")
        from_lower = _STATION_QUALIFIER_RE.sub('', from_name.lower()).strip()
        to_lower   = _STATION_QUALIFIER_RE.sub('', to_name.lower()).strip() if to_name else ""

        # Find best match in station cache
        def _find_crs(name):
            if not name:
                return None, None
            exact = [(k, s) for k, s in _STATION_CACHE.items() if k == name]
            if exact:
                return exact[0][1]["crs"], exact[0][1]["name"]
            prefix = [(k, s) for k, s in _STATION_CACHE.items() if k.startswith(name)]
            if prefix:
                return prefix[0][1]["crs"], prefix[0][1]["name"]
            contains = [(k, s) for k, s in _STATION_CACHE.items() if name in k]
            if contains:
                return contains[0][1]["crs"], contains[0][1]["name"]
            # Fuzzy
            import difflib as _dl
            close = _dl.get_close_matches(name, list(_STATION_CACHE.keys()), n=1, cutoff=0.6)
            if close:
                s = _STATION_CACHE[close[0]]
                return s["crs"], s["name"]
            return None, None

        crs, stn_display = _find_crs(from_lower)
        # Z-prefix CRS = DLR/TfL station — route directly to TfL journey planner
        if crs and crs.upper().startswith('Z'):
            if to_lower:
                tube_reply = get_tube_journey(from_lower, to_lower)
                if tube_reply and "Couldn't find" not in tube_reply:
                    return tube_reply
            return None
        if not crs:
            # Station not in National Rail — try TfL journey planner directly
            if to_lower:
                tube_reply = get_tube_journey(from_name, to_name)
                if tube_reply and "Couldn't find" not in tube_reply:
                    return tube_reply
            # Try TfL arrivals at nearest matching tube station
            tube_reply = get_tube_journey(from_name, to_name) if to_lower else None
            if tube_reply and "Couldn't find" not in tube_reply:
                return tube_reply
            return None  # genuinely unknown — let it fall through

        to_crs, to_display = _find_crs(to_lower) if to_lower else (None, None)

        # Fetch departures — use calling_at so RTT filters by intermediate stop, not just final dest
        access = _get_rtt_token()
        rtt_params: dict = {"code": f"gb-nr:{crs}"}
        if to_crs:
            rtt_params["calling_at"] = to_crs  # RTT returns services that call AT this stop
        r = requests.get(
            "https://data.rtt.io/rtt/location",
            headers={"Authorization": f"Bearer {access}"},
            params=rtt_params,
            timeout=12,
        )
        if r.status_code != 200:
            return f"Couldn't load departures for {stn_display} right now. Try again shortly."
        data = r.json()
        services = data.get("services") or []

        def fmt_time(dt):
            if not dt: return ""
            s = str(dt).strip()
            if len(s) >= 16: return s[11:16]
            if len(s) == 5 and s[2] == ":": return s
            if len(s) == 4 and s.isdigit(): return s[:2] + ":" + s[2:]
            return s[:5] if len(s) >= 5 else s

        lines = []
        shown = 0
        for svc in services:
            if shown >= 6:
                break
            td  = svc.get("temporalData", {})
            dep = td.get("departure", {})
            dest_list = svc.get("destination") or [{}]
            dest = (dest_list[0].get("location") or {}).get("description", "") if dest_list else ""
            if not dest:
                continue
            # calling_at param already filtered by RTT — no Python-side destination filter needed
            sched = fmt_time(dep.get("scheduleAdvertised") or dep.get("scheduled") or "")
            real_raw = (dep.get("realtimeForecast") or dep.get("forecast") or
                        dep.get("realtimeActual") or dep.get("actual") or "")
            real  = fmt_time(real_raw)
            cancelled = dep.get("isCancelled", False) or dep.get("cancelled", False)
            platform_raw = (svc.get("locationMetadata") or {}).get("platform")
            if isinstance(platform_raw, dict):
                platform = str(platform_raw.get("display") or platform_raw.get("number") or "")
            else:
                platform = str(platform_raw) if platform_raw else ""
            if not sched:
                continue
            if cancelled:
                status = "❌ Cancelled"
            elif real and real != sched:
                status = f"🕐 Exp {real}"
            else:
                status = "✅ On time"
            line = f"*{sched}* → {dest}  {status}"
            if platform:
                line += f"  Plat {platform}"
            lines.append(line)
            shown += 1

        if not lines:
            dest_note = f" to {to_display or to_name.title()}" if to_name else ""
            # Try tube journey planner as fallback (catches Elizabeth line / TfL-only routes)
            if to_name:
                tube_reply = get_tube_journey(from_name, to_name)
                if tube_reply and "Couldn't find" not in tube_reply:
                    return tube_reply
            return f"No service found from {stn_display}{dest_note}.\n\nTry: *tube {from_name} to {to_name or '...'}*"
        dest_note = f" to {to_display or to_name.title()}" if to_name else ""
        header = f"🚂 *{stn_display}*{dest_note}"
        return header + "\n\n" + "\n".join(lines) + "\n\nmiru.humanagency.co"
    except RuntimeError as e:
        print(f"[wa train] {e}")
        return None  # RTT not configured — fall through
    except Exception as e:
        print(f"[wa train format] {e}")
        return None


def _wa_brand_card(brand_name: str) -> str:
    """Fetch brand intel (DB-first via fetch_brand_data cache) and format as WhatsApp card."""
    from urllib.parse import quote as _q
    try:
        d = fetch_brand_data(brand_name)
    except Exception:
        d = {}

    name = d.get("name") or brand_name
    if not name or (not d.get("description") and not d.get("founded") and not d.get("slogan")):
        return (f"🏷️ Couldn't find brand info for *{brand_name}*.\n\n"
                f"Try the full profile: intel.humanagency.co?q={_q(brand_name)}")

    lines = [f"🏷️ *{name}*"]

    meta = []
    if d.get("founded"):  meta.append(f"Est. {d['founded']}")
    if d.get("hq"):       meta.append(d["hq"])
    if d.get("industry"): meta.append(d["industry"])
    if meta: lines.append(" · ".join(meta))

    if d.get("slogan"):
        lines.append(f'_"{d["slogan"]}"_')

    if d.get("description"):
        desc = d["description"][:220].rsplit(" ", 1)[0]
        lines.append(f"\n{desc}…")

    if d.get("competitors"):
        lines.append(f"\n🆚 vs {' · '.join(d['competitors'][:3])}")

    tp = d.get("trustpilot") or {}
    if tp.get("rating"):
        stars = round(float(tp["rating"]))
        count_str = f" ({tp['count']:,} reviews)" if tp.get("count") else ""
        lines.append(f"{'⭐'*stars} Trustpilot: {tp['rating']}/5{count_str}")

    lines.append(f"\n🔍 Full profile: intel.humanagency.co?q={_q(name)}")
    return "\n".join(lines)


def whatsapp_product_format(product_name: str, postcode: str = None) -> str:
    """Look up a grocery product and return a WhatsApp-friendly price summary."""
    import requests as _req, json as _json
    from concurrent.futures import ThreadPoolExecutor, as_completed as _as_completed

    groq_key = os.environ.get("GROQ_API_KEY", "")

    def _obj(text):
        s, e = text.find("{"), text.rfind("}")
        return _json.loads(text[s:e+1]) if s != -1 and e != -1 else {}

    def _groq(prompt, max_tokens=500, model="llama-3.1-8b-instant"):
        r = _req.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {groq_key}", "Content-Type": "application/json"},
            json={"model": model,
                  "messages": [{"role": "user", "content": prompt}],
                  "max_tokens": max_tokens, "temperature": 0.2},
            timeout=15,
        )
        return r.json()["choices"][0]["message"]["content"].strip()

    def _tesco(q):
        """Try Tesco grocery API for a live price."""
        try:
            r = _req.get(
                "https://api.tesco.com/shoppingexperience/v1/api/products/search",
                params={"query": q, "count": "3", "offset": "0"},
                headers={"User-Agent": "Mozilla/5.0", "Accept": "application/json"},
                timeout=5,
            )
            if r.status_code == 200:
                items = r.json().get("uk", {}).get("ghs", {}).get("products", {}).get("results", [])
                if items:
                    p = items[0].get("price") or items[0].get("unitPrice")
                    if p:
                        return f"£{float(p):.2f}"
        except Exception:
            pass
        return None

    # Single Groq call: product info + all store prices + alternatives
    product = {"name": product_name, "brand": "", "category": ""}
    prices = {}
    alternatives = []

    if groq_key:
        try:
            prompt = (
                f'You are a UK grocery price expert. The user asked about: "{product_name}".\n'
                'Return ONLY valid JSON with these fields:\n'
                '{\n'
                '  "name": "exact product name and size e.g. Heinz Baked Beans 415g",\n'
                '  "brand": "brand name",\n'
                '  "category": "category",\n'
                '  "prices": {\n'
                '    "aldi": "£X.XX",\n'
                '    "lidl": "£X.XX",\n'
                '    "asda": "£X.XX",\n'
                '    "sainsburys": "£X.XX",\n'
                '    "tesco": "£X.XX",\n'
                '    "waitrose": "£X.XX"\n'
                '  },\n'
                '  "alternatives": [\n'
                '    {"name": "...", "price": "£X.XX", "store": "..."}\n'
                '  ]\n'
                '}\n'
                'Use typical current UK shelf prices. Only include stores where the product is commonly sold.'
            )
            raw = _groq(prompt, max_tokens=500)
            obj = _obj(raw)
            if obj.get("name"):
                product = {"name": obj["name"], "brand": obj.get("brand",""), "category": obj.get("category","")}
            prices = {k: v for k, v in obj.get("prices", {}).items() if v and "X" not in v}
            alternatives = obj.get("alternatives", [])[:2]
        except Exception:
            # Fallback: simpler prompt with smaller model
            try:
                raw = _groq(
                    f'UK grocery "{product_name}": give typical prices at Aldi, Asda, Tesco, Sainsburys. '
                    'Return ONLY JSON: {"name":"...","brand":"...","prices":{"aldi":"£X.XX","asda":"£X.XX","tesco":"£X.XX","sainsburys":"£X.XX"}}',
                    max_tokens=200, model="llama-3.1-8b-instant"
                )
                obj = _obj(raw)
                if obj.get("name"):
                    product["name"] = obj["name"]
                    product["brand"] = obj.get("brand", "")
                prices = {k: v for k, v in obj.get("prices", {}).items() if v and "X" not in v}
            except Exception:
                pass

    # Try to get a live Tesco price to verify/supplement AI prices
    live_tesco = _tesco(product["name"])
    if live_tesco:
        prices["tesco"] = live_tesco + " ✓"

    search_term = product["name"]
    brand = product["brand"]

    # Format reply
    lines = [f"🛒 {search_term}"]
    if brand:
        lines.append(f"Brand: {brand}" + (f" | {product['category']}" if product.get("category") else ""))
    lines.append("")

    if prices:
        store_order = ["aldi", "lidl", "asda", "sainsburys", "tesco", "waitrose", "amazon"]
        sorted_prices = sorted(prices.items(), key=lambda x: (store_order.index(x[0]) if x[0] in store_order else 99))
        lines.append("Prices:")
        for store, price in sorted_prices:
            lines.append(f"  {store.title()}: {price}")
        # Highlight cheapest (strip £, ✓, spaces for comparison)
        try:
            def _num(v): return float(re.sub(r'[^0-9.]', '', v))
            cheapest_store, cheapest_price = min(prices.items(), key=lambda x: _num(x[1]))
            lines.append(f"\n💰 Cheapest: {cheapest_store.title()} at {cheapest_price}")
        except Exception:
            pass
    else:
        lines.append("⚠️ Couldn't find live prices right now.")

    if alternatives:
        lines.append("\nAlternatives:")
        for a in alternatives[:2]:
            lines.append(f"  {a['name']} — {a.get('price','')}")

    # Nearby supermarkets if postcode given
    if postcode:
        latlon = postcode_to_latlon(postcode)
        if latlon:
            try:
                amenities = fetch_nearby_amenities(latlon[0], latlon[1], 8.0)
                supers = amenities.get("supermarkets", [])[:4]
                if supers:
                    lines.append(f"\nNearby supermarkets ({postcode}):")
                    for s in supers:
                        lines.append(f"  {s['name']} ({s['dist_mi']:.1f}mi)")
            except Exception:
                pass

    lines.append("\nReply with a product name to compare prices")
    lines.append("Or a postcode for fuel prices")
    lines.append("Not right? Reply *HELP*")
    return "\n".join(lines)


