_SEEN_NUMBERS: set = set()

def _is_new_user(from_number: str) -> bool:
    """True if this number has no prior history in Miru."""
    if from_number in _SEEN_NUMBERS:
        return False
    try:
        variants = _wa_number_variants(from_number)
        # Check all tables where a user might leave a footprint
        checks = [
            ("wa_saves",       "from_number"),
            ("school_profiles","wa_number"),
            ("my_area_places", "from_number"),
            ("ma_details",     "device_id"),   # v2_prefs / recurring activities
        ]
        for table, col in checks:
            try:
                rows = lib._sb().table(table).select("id").in_(col, variants).limit(1).execute().data
                if rows:
                    _SEEN_NUMBERS.add(from_number)
                    return False
            except Exception:
                pass  # one table failing shouldn't block the rest
        return True
    except Exception:
        return False  # if totally broken, treat as existing user → send help not welcome


def _wa_classify_intent(body: str) -> dict | None:
    """Use Groq to classify a free-text WhatsApp message into a known intent.
    Returns intent dict or None on failure / unknown.
    Called when no exact command matched — handles typos, word-order variations, and natural phrasing."""
    try:
        import json as _json
        result = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {os.environ.get('GROQ_API_KEY', '')}", "Content-Type": "application/json"},
            json={"model": "llama3-8b-8192", "temperature": 0, "max_tokens": 160,
            "messages": [{"role": "system", "content": (
                "Classify the user message into ONE intent. Respond with JSON only — no markdown, no explanation.\n\n"
                "Intents:\n"
                "  train        — train/rail departures or journey. Extract: from (station name, str), to (station name or null).\n"
                "  tube         — London tube/DLR/Overground/Elizabeth line status, journey, or line info.\n"
                "                 Extract: from (station or null), to (station or null),\n"
                "                 query (status | journey | line name — infer from message, default 'status').\n"
                "  food         — food or drink discovery nearby. Extract: food_type — normalise to one of (coffee|breakfast|sandwiches|lunch|pizza|dinner|beer|pub|tea|masala_chai|burger|kebab|steak|wine|cocktail|chaat|indian|italian|mexican|fish_chips|chinese).\n"
                "                 Map latte/cappuccino/capuccino/mocha/pistachio latte/espresso/flat white/americano/cortado/coffee/cofee/coffeeee → coffee.\n"
                "                 Map tea/english breakfast/chai/brew/cuppa → tea.\n"
                "                 Map beer/pint/ale/lager/craft beer/cheap beer/good beer → beer.\n"
                "                 Map burger/burgers/smash burger/best burger → burger. Map kebab/doner/shawarma → kebab. Map steak/steakhouse/ribeye/sirloin → steak.\n"
                "                 Map wine/red wine/white wine/rosé/house wine/glass of wine → wine.\n"
                "                 Map cocktail/cocktails/cocktail bar/negroni/martini/espresso martini/spritz/best cocktail → cocktail.\n"
                "                 Map chaat/pani puri/bhel puri/samosa chaat/indian street food → chaat.\n"
                "                 Map masala chai/chai latte/cutting chai/indian chai/best chai/ginger chai → masala_chai.\n"
                "                 Map indian/india/curry/curries/balti/tandoori/tikka/biryani/korma/masala/best indian/indian food/indian restaurant/indian place → indian.\n"
                "                 Map italian/italy/pasta/risotto/trattoria/best italian/italian food/italian restaurant → italian.\n"
                "                 Map mexican/mexico/taco/tacos/burrito/tex-mex/best mexican/mexican food/mexican restaurant → mexican.\n"
                "                 Map fish and chips/fish n chips/fish & chips/chippy/chip shop/best fish and chips → fish_chips.\n"
                "                 Map chinese/china/dim sum/chow mein/best chinese → chinese.\n"
                "                 postcode (UK outcode like KT16 or full postcode — extract exactly as written, or null if not present),\n"
                "                 cheap (bool, true only if user explicitly says cheap/budget/affordable).\n"
                "  book_lookup  — user wants to find/save/add a book. Extract: query (title/author/ISBN).\n"
                "  search_saves — user wants to browse/filter things they already saved.\n"
                "                 Extract: filter (books|wine|recipes|menus|restaurants|videos|products|all),\n"
                "                 author (if 'by X' mentioned, else null), timeframe (today|yesterday|last_week|last_month|all).\n"
                "  worth_it     — wants review/verdict on last saved book.\n"
                "  shopping_list— wants ingredients/shopping list from last saved recipe.\n"
                "  drink_info   — wants to know what's in a cocktail / how it looks or tastes. Extract: drink (name of the cocktail or drink, str).\n"
                "                 Map 'what's in a X' / 'what is a X' / 'what does a X look like' / 'tell me about X' / 'X cocktail info' → drink_info.\n"
                "                 Only use when asking ABOUT a drink, not ordering/finding one nearby.\n"
                "  recipe       — wants a recipe or cocktail recipe. Extract: dish (the name of the dish or drink, str).\n"
                "                 Map 'how do I make X' / 'recipe for X' / 'how to make X' / 'X recipe' / 'ingredients for X' → recipe.\n"
                "  my_saves     — wants to see their saved items list.\n"
                "  my_link      — wants their personal Miru link.\n"
                "  menu         — user wants to see the menu of a specific named restaurant/pub/cafe.\n"
                "                 Extract: name (the restaurant/pub name exactly as mentioned).\n"
                "  unknown      — anything else (fuel prices, postcodes alone, greetings, etc.).\n\n"
                "Examples (JSON only):\n"
                '{"intent":"recipe","dish":"aperol spritz"}\n'
                '{"intent":"recipe","dish":"spaghetti carbonara"}\n'
                '{"intent":"recipe","dish":"negroni"}\n'
                '{"intent":"menu","name":"Belvedere Arms"}\n'
                '{"intent":"menu","name":"Nando\'s"}\n'
                '{"intent":"train","from":"waterloo","to":"lewisham"}\n'
                '{"intent":"train","from":"reading","to":null}\n'
                '{"intent":"tube","from":null,"to":null,"query":"status"}\n'
                '{"intent":"tube","from":null,"to":null,"query":"jubilee"}\n'
                '{"intent":"tube","from":"canary wharf","to":"oxford circus","query":"journey"}\n'
                '{"intent":"food","food_type":"coffee","postcode":"KT16","cheap":false}\n'
                '{"intent":"food","food_type":"beer","postcode":null,"cheap":true}\n'
                '{"intent":"food","food_type":"coffee","postcode":null,"cheap":false}\n'
                '{"intent":"book_lookup","query":"midnight library"}\n'
                '{"intent":"search_saves","filter":"wine","author":null,"timeframe":"last_week"}\n'
                '{"intent":"worth_it"}\n'
                '{"intent":"shopping_list"}\n'
                '{"intent":"my_saves"}\n'
                '{"intent":"my_link"}\n'
                '{"intent":"unknown"}'
            )}, {"role": "user", "content": body[:300]}]},
            timeout=8,
        ).json()["choices"][0]["message"]["content"].strip()
        result = re.sub(r"^```[a-z]*\n?|```$", "", result.strip()).strip()
        parsed = _json.loads(result)
        return parsed if parsed.get("intent") and parsed["intent"] != "unknown" else None
    except Exception as _e:
        print(f"[intent] classify failed: {_e}")
        return None


def _wa_recipe_card(dish: str, from_number: str = "", return_dict: bool = False) -> str | dict:
    """Generate a compact recipe/cocktail card via Groq for WhatsApp.

    Args:
        dish: Name of the dish or cocktail
        from_number: WhatsApp number (to enable save intent)
        return_dict: If True, return {recipe, explanation, dish_type} for API use

    Returns:
        str: WhatsApp formatted recipe (with save intent footer)
        dict: {recipe, explanation, dish_type} if return_dict=True (for web)
    """
    try:
        prompt = (
            f"Write a recipe for '{dish}'. Use this exact format:\n\n"
            "[emoji] [Name]\n\n"
            "• [ingredient 1 with quantity]\n"
            "• [ingredient 2 with quantity]\n"
            "...\n\n"
            "[Method: 1-2 short sentences]\n"
            "[Glass/Serve line if cocktail]\n\n"
            "Rules: British English. Quantities in metric or ml. "
            "No intro text, no markdown, no asterisks. Under 90 words."
        )
        r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {os.environ.get('GROQ_API_KEY', '')}",
                     "Content-Type": "application/json"},
            json={"model": "llama-3.1-8b-instant", "max_tokens": 200, "temperature": 0.4,
                  "messages": [{"role": "user", "content": prompt}]},
            timeout=10,
        )
        text = r.json()["choices"][0]["message"]["content"].strip()

        # Generate brief explanation (G11: Make clear WHY)
        explain_prompt = (
            f"One-line reason why this is a good recipe for '{dish}'. "
            f"Be brief and friendly (under 60 chars). "
            f"Examples: 'Classic & easy', 'Perfect for weeknights', 'Restaurant-quality at home', 'Tried & tested', 'Seasonal favourite'"
        )
        explain_r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {os.environ.get('GROQ_API_KEY', '')}",
                     "Content-Type": "application/json"},
            json={"model": "llama-3.1-8b-instant", "max_tokens": 50, "temperature": 0.3,
                  "messages": [{"role": "user", "content": explain_prompt}]},
            timeout=8,
        )
        explanation = explain_r.json()["choices"][0]["message"]["content"].strip()

        # Detect if cocktail or food recipe
        dish_lower = dish.lower()
        cocktail_keywords = ["cocktail", "martini", "spritz", "margarita", "negroni", "daiquiri", "mojito", "cosmopolitan", "whiskey", "vodka", "gin", "rum", "beer"]
        is_cocktail = any(kw in dish_lower for kw in cocktail_keywords) or "glass" in text.lower() or "/" in text.lower()
        dish_type = "cocktail" if is_cocktail else "recipe"

        if return_dict:
            return {
                "recipe": text,
                "explanation": explanation,
                "dish_type": dish_type,
                "dish_name": dish
            }

        # Set pending intent so user can reply "save" to save it
        if from_number:
            _set_wa_pending_intent(from_number, {"type": "recipe_save", "title": dish, "text": text, "explanation": explanation, "dish_type": dish_type})

        return text + f"\n\n_{explanation}_\n\n_Reply *save* to keep this, or send another recipe name._"
    except Exception as e:
        app.logger.debug(f"[recipe] Generation failed: {e}")
        if return_dict:
            return {"recipe": "", "explanation": "", "dish_type": "", "error": str(e)}
        return f"Couldn't fetch the recipe for *{dish}* right now — try again in a moment."


def _wa_drink_info_card(drink: str) -> str:
    """Quick cheat-sheet for any cocktail or drink — ingredients, glass, colour, taste."""
    try:
        prompt = (
            f"Give me a quick cheat-sheet for the cocktail or drink '{drink}'. "
            "Use this exact format (no markdown, no asterisks, no intro):\n\n"
            "[emoji] [Name]\n\n"
            "Ingredients: [ingredient 1] · [ingredient 2] · ...\n"
            "Glass: [glass type + any garnish]\n"
            "Colour: [colour]\n"
            "Taste: [1 line — flavour profile]\n"
            "Similar: [1-2 drinks the person might also like]\n\n"
            "Rules: British English. Under 60 words. If it's not a real drink, say so in one line."
        )
        r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {os.environ.get('GROQ_API_KEY', '')}",
                     "Content-Type": "application/json"},
            json={"model": "llama-3.1-8b-instant", "max_tokens": 150, "temperature": 0.3,
                  "messages": [{"role": "user", "content": prompt}]},
            timeout=10,
        )
        return r.json()["choices"][0]["message"]["content"].strip()
    except Exception:
        return f"Couldn't look up *{drink}* right now — try again in a moment."


def _wa_search_saves(from_number: str, filter_type: str, timeframe: str, author: str = "") -> str:
    """Query wa_saves (and my_area_places for restaurants) and format for WhatsApp."""
    from datetime import datetime, timedelta, timezone
    import json as _json

    plain = from_number.replace("whatsapp:", "").strip()
    wa    = f"whatsapp:{plain}" if not plain.startswith("whatsapp:") else plain
    nums  = [from_number, plain, wa]

    # Timeframe → cutoff datetime
    now = datetime.now(timezone.utc)
    cutoff = None
    if timeframe == "today":
        cutoff = now.replace(hour=0, minute=0, second=0, microsecond=0)
    elif timeframe == "yesterday":
        d = (now - timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
        cutoff = d
        end_cutoff = now.replace(hour=0, minute=0, second=0, microsecond=0)
    elif timeframe == "last_week":
        cutoff = now - timedelta(days=7)
    elif timeframe == "last_month":
        cutoff = now - timedelta(days=30)

    # --- Restaurant/place saves: from my_area_places ---
    if filter_type == "restaurants":
        try:
            sb = lib._sb()
            q = sb.table("my_area_places").select("name,address,phone,created_at") \
                .in_("from_number", nums) \
                .in_("emoji", ["🍺", "☕", "🍽️", "🥘"])
            if cutoff:
                q = q.gte("created_at", cutoff.isoformat())
            rows = q.order("created_at", desc=True).limit(10).execute().data or []
            if not rows:
                tf = {"today":"today","yesterday":"yesterday","last_week":"last 7 days","last_month":"last month"}.get(timeframe,"")
                return f"🍽️ No restaurants saved{' ' + tf if tf else ''}."
            lines = []
            for r in rows:
                line = f"🍽️ *{r['name']}*"
                if r.get("address"): line += f"\n   {r['address']}"
                if r.get("phone"):   line += f" · {r['phone']}"
                lines.append(line)
            tf_label = {"today":"today","yesterday":"yesterday","last_week":"this week","last_month":"this month"}.get(timeframe,"")
            header = f"🍽️ *Restaurants saved{' ' + tf_label if tf_label else ''}* ({len(rows)})"
            return header + "\n\n" + "\n\n".join(lines)
        except Exception as e:
            print(f"[search_saves] restaurants: {e}")
            return "Couldn't fetch your restaurant saves right now."

    # --- All other types: from wa_saves ---
    filter_map = {
        "books":    ("url", "book:%"),
        "wine":     ("title", "🍷%"),
        "recipes":  ("title", "🍳%"),
        "menus":    ("title", "%menu%"),
        "videos":   ("title", "📺%"),
        "products": ("title", "📦%"),
    }
    emoji_labels = {
        "books": "📚", "wine": "🍷", "recipes": "🍳",
        "menus": "📋", "videos": "📺", "products": "📦", "all": "📂",
    }

    try:
        sb = lib._sb()
        q = sb.table("wa_saves").select("id,title,url,summary,created_at") \
            .in_("from_number", nums)
        col, pat = filter_map.get(filter_type, (None, None))
        if col and pat:
            q = q.ilike(col, pat)
        if cutoff:
            q = q.gte("created_at", cutoff.isoformat())
        if timeframe == "yesterday" and "end_cutoff" in dir():
            q = q.lt("created_at", end_cutoff.isoformat())
        rows = q.order("created_at", desc=True).limit(10).execute().data or []

        # Filter by author if requested (checks summary JSON)
        if author and filter_type == "books":
            def _matches_author(row):
                try:
                    bk = _json.loads(row.get("summary") or "{}")
                    return author.lower() in (bk.get("author") or "").lower()
                except Exception:
                    return False
            rows = [r for r in rows if _matches_author(r)]

        if not rows:
            tf = {"today":"today","yesterday":"yesterday","last_week":"last 7 days","last_month":"last month"}.get(timeframe,"")
            by = f" by {author}" if author else ""
            return f"{emoji_labels.get(filter_type,'📂')} No {filter_type}{by} saved{' in the ' + tf if tf else ''}."

        lines = []
        for r in rows:
            title = r.get("title") or r.get("url", "?")
            if filter_type == "books":
                try:
                    bk = _json.loads(r.get("summary") or "{}")
                    title = bk.get("title") or title
                    auth  = bk.get("author", "")
                    cr    = bk.get("communityRating") or {}
                    line  = f"📚 *{title}*"
                    if auth: line += f"\n   by {auth}"
                    if cr.get("avg"): line += f" · {'⭐'*round(cr['avg'])} {cr['avg']}/5"
                except Exception:
                    line = f"📚 *{title}*"
            else:
                line = f"{emoji_labels.get(filter_type,'📂')} *{title}*"
            lines.append(line)

        tf_label = {"today":"today","yesterday":"yesterday","last_week":"this week","last_month":"this month"}.get(timeframe,"")
        by = f" by {author.title()}" if author else ""
        header = f"{emoji_labels.get(filter_type,'📂')} *{filter_type.title()}{by}{' — ' + tf_label if tf_label else ''}* ({len(rows)})"
        return header + "\n\n" + "\n\n".join(lines)
    except Exception as e:
        print(f"[search_saves] {filter_type}: {e}")
        return "Couldn't search your saves right now."


@app.route("/whatsapp", methods=["POST"])
def whatsapp_reply():
    try:
        return _whatsapp_reply_inner()
    except Exception as _top_err:
        print(f"[whatsapp] UNHANDLED: {_top_err}", flush=True)
        import traceback; traceback.print_exc()
        _er = MessagingResponse()
        _er.message("Sorry, something went wrong. Please try again in a moment.")
        return str(_er)

def _whatsapp_reply_inner():
    body        = request.form.get("Body", "").strip()
    # Normalise smart/curly quotes — iOS WhatsApp sends ‘ (U+2019) not ‘ (U+0027)
    body = body.replace('\u2018', "'").replace('\u2019', "'").replace('\u201c', '"').replace('\u201d', '"')
    from_number = request.form.get("From", "unknown")
    print(f"WhatsApp from {from_number}: {body}")

    resp = MessagingResponse()

    # ── Conversation memory: load thread, save exchange after every response ──
    _wa_thread = _wa_load_thread(from_number) if from_number != "unknown" else []

    @after_this_request
    def _persist_exchange(response):
        import threading as _thr, re as _re_thr
        _rm = _re_thr.search(r'<Message>(.*?)</Message>',
                             response.get_data(as_text=True), _re_thr.DOTALL)
        if _rm and body and from_number != "unknown" and len(body.strip()) > 3:
            _reply_txt = _rm.group(1).strip()[:500]
            _thr.Thread(target=_wa_save_thread,
                        args=(from_number, body[:300], _reply_txt),
                        daemon=True).start()
        return response

    # ── Location share (Twilio sends Latitude+Longitude for WhatsApp location messages) ──
    _lat = request.form.get("Latitude", "")
    _lon = request.form.get("Longitude", "")
    if _lat and _lon:
        try:
            _loc_lat, _loc_lon = float(_lat), float(_lon)
            _USER_LAST_LOCATION[from_number] = {
                "lat": _loc_lat, "lon": _loc_lon, "ts": time.time()
            }
            # If there's a pending food intent, serve it immediately with live location
            _pending = _get_wa_pending_intent(from_number)
            if _pending and _pending.get("type") == "food":
                _clear_wa_pending_intent(from_number)
                _ftype  = _pending.get("food_type", "food")
                _fcheap = _pending.get("cheap", False)
                _synthetic = f"{'cheap ' if _fcheap else ''}{_ftype}"
                # Location is now in _USER_LAST_LOCATION — _wa_food_find will pick it up
                _food_r = _wa_food_find(_synthetic, from_number)
                resp.message(_food_r or f"📍 Got your location! Send *{_ftype}* again and I'll search right here.")
            else:
                resp.message("📍 Got your location! Send *best steak*, *good coffee* etc. and I'll find it right where you are. Resets in 2 hours.")
            return str(resp)
        except Exception:
            pass

    # ── Image/photo capture (before body checks — body is empty when photo sent) ─
    num_media = int(request.form.get("NumMedia", "0") or 0)
    if num_media > 0:
        media_url  = request.form.get("MediaUrl0", "")
        media_type = request.form.get("MediaContentType0", "image/jpeg")
        if media_url and "image" in media_type:
            reply = _wa_process_image(from_number, media_url, media_type)
            resp.message(reply)
            return str(resp)

    body_lower = body.strip().lower()
    if not body or body_lower in _GREETING_WORDS or body_lower.startswith("join "):
        is_join = body_lower.startswith("join ") or body_lower == "join"
        if is_join or _is_new_user(from_number):
            _SEEN_NUMBERS.add(from_number)
            resp.message(_WELCOME_MSG)
            # Ask for postcode if they don't have one saved yet
            if not _get_wa_home_postcode(from_number):
                _set_wa_pending_intent(from_number, {"type": "setup_postcode"})
                resp.message("📍 *Quick setup — one time only*\n\n"
                           "What's your home postcode?\n"
                           "(e.g. *KT16 0HY*)\n\n"
                           "This helps me:\n"
                           "✓ Show your nearest trains\n"
                           "✓ Find fuel & food nearby\n"
                           "✓ Personalise local info\n\n"
                           "You control this data — reply *clear* anytime to reset.")
        elif body_lower in _HELLO_ONLY:
            # Casual greeting from existing user — short friendly reply, not the full menu
            resp.message(_HELLO_MSG)
        else:
            # Explicit "help" / "menu" / "miru" → full capability list
            resp.message(_HELP_MSG)
        return str(resp)

    # 🥚 Easter egg: bored → suggest something nearby ────────────────────────
    if body_lower in ("bored", "i'm bored", "im bored", "so bored", "what should i do", "entertain me"):
        home_pc = _get_wa_home_postcode(from_number)
        bored_msgs = [
            "🎲 Challenge accepted! Here's what to do:\n\n"
            "1. 🍺 Find a pub and start a tab\n"
            "2. 🎵 Shazam a song you don't know\n"
            "3. 🗺️ Walk somewhere you've never been\n\n"
            + (f"Reply *nearby {home_pc}* for actual places near you!" if home_pc else "Reply *nearby [your postcode]* for ideas near you!"),
        ]
        import random
        resp.message(random.choice(bored_msgs))
        return str(resp)

    # 💡 Idea command — surface random saved tweets ──────────────────────────────
    if body_lower in ("idea", "ideas", "inspire me", "inspire", "surprise me", "random idea"):
        try:
            _sb_i = lib._sb()
            # Pull 50 random-ish from the best signal categories, return 3
            _idea_rows = _sb_i.table("twitter_bookmarks") \
                .select("author_name,author_handle,text,url,category") \
                .in_("category", ["AI & Tech", "Startups & Ideas", "Business & Money",
                                  "Mindset & Life", "Learning & Reading", "Tools"]) \
                .not_.is_("text", "null") \
                .order("saved_at", desc=False) \
                .limit(500).execute().data or []
            import random as _rand
            _picks = _rand.sample(_idea_rows, min(5, len(_idea_rows)))
            if not _picks:
                resp.message("💡 No saved ideas found yet — sync your Twitter bookmarks first.")
                return str(resp)
            _lines = ["💡 *5 ideas from your saves:*\n"]
            for _p in _picks:
                _txt = (_p.get("text") or "").strip()[:200]
                _handle = _p.get("author_handle", "")
                _cat = _p.get("category", "")
                _url = _p.get("url", "")
                _lines.append(f"_{_cat}_\n*@{_handle}*: {_txt}\n{_url}")
            resp.message("\n\n".join(_lines))
        except Exception as _ie:
            print(f"[idea] error: {_ie}")
            resp.message("💡 Couldn't fetch ideas right now — try again in a moment.")
        return str(resp)

    # ── Morning brief opt-out ────────────────────────────────────────────────────
    if body_lower in ("stop brief", "pause brief", "stop morning brief", "no brief"):
        try:
            _sb2 = lib._sb()
            _br2 = _sb2.table("ma_details").select("id,data") \
                .eq("device_id", from_number).eq("type", "v2_prefs").limit(1).execute().data or []
            if _br2:
                _bd2 = {**(_br2[0].get("data") or {}), "brief_paused": True}
                _sb2.table("ma_details").update({"data": _bd2}).eq("id", _br2[0]["id"]).execute()
        except Exception:
            pass
        resp.message("✅ Morning brief paused. Reply *START BRIEF* anytime to resume.")
        return str(resp)
    if body_lower in ("start brief", "resume brief", "start morning brief"):
        try:
            _sb3 = lib._sb()
            _br3 = _sb3.table("ma_details").select("id,data") \
                .eq("device_id", from_number).eq("type", "v2_prefs").limit(1).execute().data or []
            if _br3:
                _bd3 = {**(_br3[0].get("data") or {}), "brief_paused": False}
                _sb3.table("ma_details").update({"data": _bd3}).eq("id", _br3[0]["id"]).execute()
        except Exception:
            pass
        resp.message("✅ Morning brief is back on — you'll get it each morning.")
        return str(resp)

    # ── FIELD WORKER EXPENSE QUERIES ──────────────────────────────────────────
    # Detect: "add expense", "show my expenses", "expense breakdown", etc.
    _expense_triggers = [
        r'\b(add|capture|upload|save|log)\s+(an?\s+)?expense\b',
        r'\b(show|list|get|what)\s+my\s+expenses?\b',
        r'\bexpense\s+(breakdown|summary|report|total)\b',
        r'\b(claim|claimed)\s+expenses?\b',
        r'\bexpense\s+for\s+(june|may|april|march|february|january|this month)\b',
    ]

    if any(re.search(t, body_lower, re.IGNORECASE) for t in _expense_triggers):
        try:
            # Expense handler: capture from WhatsApp text or image
            if "add" in body_lower or "capture" in body_lower or "upload" in body_lower or "save" in body_lower:
                # User wants to add an expense
                resp.message("📋 Send me a receipt photo or text (amount, merchant, category)\n\n"
                            "Example: 'Screwfix £45 for supplies on June 28'\n\n"
                            "Then I'll extract it automatically.")
                return str(resp)
            elif "show" in body_lower or "list" in body_lower or "summary" in body_lower:
                # Show expense summary
                try:
                    import requests as _req_exp
                    summary_url = f"{os.environ.get('MIRU_API_URL', 'http://localhost:5000')}/api/v2/expenses/summary"
                    _params = {"token": token}
                    _resp = _req_exp.get(summary_url, params=_params, timeout=5)
                    if _resp.ok:
                        data = _resp.json()
                        period = data.get("period", "This month")
                        total = data.get("total_amount", 0)
                        vat = data.get("total_vat", 0)
                        count = data.get("receipt_count", 0)

                        msg = f"💼 **{period} Expenses**\n\n"
                        msg += f"Total: £{total:.2f} (VAT: £{vat:.2f})\n"
                        msg += f"Receipts: {count}\n\n"

                        breakdown = data.get("breakdown", {})
                        for cat, info in breakdown.items():
                            msg += f"• {cat}: £{info.get('total', 0):.2f} ({info.get('count', 0)} items)\n"

                        resp.message(msg)
                        return str(resp)
                except Exception as _exp_err:
                    print(f"[expense-query] Summary error: {_exp_err}")
                    resp.message("❌ Error fetching expense summary. Try again later.")
                    return str(resp)
        except Exception as _exp_handler_err:
            print(f"[expense-handler] Error: {_exp_handler_err}")
            # Fall through to other handlers

    # ── RECEIPT INTELLIGENCE QUERIES ───────────────────────────────────────────
    # Detect: "show receipts", "how much did I spend", "spending breakdown", etc.
    _receipt_triggers = [
        r'\b(show|list|get|what)\s+(me\s+)?receipts?\b',
        r'\bhow\s+much\s+(did\s+i\s+)?spend\b',
        r'\bwhat[\'s]?\s+my\s+(total|spending|spend)\b',
        r'\bwhere.*spend\b',
        r'\breceipt.*from\b',
        r'\b(spending|receipts)\b.*\b(june|may|april|march|february|january|this month|this week)\b',
        r'\b(top|biggest|most)\s+(merchant|restaurant|purchase|spend)\b',
        r'\bbreakdown\b.*\b(category|categor)',
        r'\bcoffee\s+(spend|receipt)',
        r'\brestaurant\s+(spend|receipt)',
    ]

    if any(re.search(t, body_lower, re.IGNORECASE) for t in _receipt_triggers):
        try:
            receipt_result = _route_receipt_query(from_number, body)
            if receipt_result and not receipt_result.get("error"):
                answer = receipt_result.get("answer", "No data")
                cached_indicator = " (cached)" if receipt_result.get("cached") else ""
                resp.message(f"💰 {answer}{cached_indicator}")
                return str(resp)
        except Exception as _rq_err:
            print(f"[receipts-query] Error: {_rq_err}", flush=True)
            # Fall through to other handlers if receipt query fails

    # ── Recurring activity capture ─────────────────────────────────────────────
    # Detect: "X runs all year" / "X is all year" / "X all year round" — toggle all_year flag
    _ALL_YEAR_RE = re.compile(
        r'^(.+?)\s+(?:runs?\s+all\s+year|is\s+all\s+year|all\s+year(?:\s+round)?)\s*$',
        re.IGNORECASE
    )
    _all_year_m = _ALL_YEAR_RE.match(body.strip())
    if _all_year_m:
        _ay_name = _all_year_m.group(1).strip().lower()
        try:
            sb = lib._sb()
            _plain = from_number.replace("whatsapp:", "").strip()
            rows = sb.table("ma_details").select("id,data").eq("device_id", _plain) \
                .eq("type", "recurring_activities").limit(1).execute().data or []
            if rows:
                activities = list(rows[0].get("data") or [])
                _matched = [a for a in activities if _ay_name in a.get("activity","").lower()]
                if _matched:
                    for a in activities:
                        if _ay_name in a.get("activity","").lower():
                            a["all_year"] = True
                    sb.table("ma_details").update({"data": activities}).eq("id", rows[0]["id"]).execute()
                    _ay_label = _matched[0].get("activity","").title()
                    resp.message(f"✅ *{_ay_label}* marked as all year — it'll show in your brief during school holidays too.")
                    return str(resp)
        except Exception as _aye:
            app.logger.warning(f"[all_year] {_aye}")

    # Detect: "every Sunday 9am Inaaya cricket Valley End Cricket Club"
    _EVERY_RE = re.compile(
        r'\bevery\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday|mon|tue|wed|thu|fri|sat|sun)\b',
        re.IGNORECASE
    )
    _every_m = _EVERY_RE.search(body)
    if _every_m:
        _ra_day_str = _every_m.group(1).lower()
        _ra_weekday = _DOW_MAP.get(_ra_day_str, -1)
        if _ra_weekday >= 0:
            # Parse the rest with Groq
            try:
                _ra_parsed = _groq_chat(
                    "Extract structured data from a UK parent's activity message. "
                    "Return JSON only: {\"activity\": str, \"time\": \"HH:MM\" or \"\", "
                    "\"child\": str or \"\", \"location\": str or \"\"}. "
                    "time must be 24h HH:MM format or empty string. child is a person's name if mentioned.",
                    [{"role": "user", "content": body}],
                    max_tokens=80, json_mode=True,
                )
                import json as _json
                _ra_data = _json.loads(_ra_parsed)
                _ra_data["weekday"] = _ra_weekday
                _ra_data["day_name"] = _ra_day_str.capitalize()
                _v2_save_recurring(from_number, _ra_data)
                _ra_who   = _ra_data.get("child","")
                _ra_what  = _ra_data.get("activity","activity")
                _ra_time  = _ra_data.get("time","")
                _ra_loc   = _ra_data.get("location","")
                _ra_conf  = f"✅ Got it — {_ra_who + chr(39) + 's ' if _ra_who else ''}{_ra_what}"
                if _ra_time: _ra_conf += f" at {_ra_time}"
                _ra_conf += f" every {_ra_data['day_name']}"
                if _ra_loc:  _ra_conf += f" ({_ra_loc})"
                _ra_conf += ". I'll include it in your morning brief."
                resp.message(_ra_conf)
                return str(resp)
            except Exception as _rae:
                print(f"[recurring] parse error: {_rae}")

    # ── Edit clipping details ──────────────────────────────────────────────────────
    if body_lower.startswith("edit "):
        merchant = body_lower.replace("edit ", "").strip()
        if not merchant:
            resp.message("Say *edit [store name]* — e.g. *edit renaissance*")
            return str(resp)
        try:
            _plain_fn = from_number.replace("whatsapp:", "").strip()
            # Find the clipping
            rows = lib._sb().table("wa_saves").select("id,summary").eq("from_number", _plain_fn)\
                .ilike("summary", f"%{merchant}%").order("created_at", desc=True).limit(1).execute().data or []
            if not rows:
                resp.message(f"No clipping found for '{merchant}'")
                return str(resp)
            # Set pending intent to edit
            _set_wa_pending_intent(from_number, {"type": "edit_amount", "clipping_id": rows[0]["id"], "merchant": merchant})
            resp.message(f"What's the bill amount for {rows[0]['summary'].title()}? (e.g. *36.50*)")
        except Exception as e:
            print(f"[edit] {e}")
            resp.message(f"Error: {e}")
        return str(resp)

    # ── Pending intent: amount reply for edit ───────────────────────────────────────
    _amount_m = re.match(r'^[\d.]+$', body.strip())
    if _amount_m:
        _edit_pending = _get_wa_pending_intent(from_number)
        if _edit_pending and _edit_pending.get("type") == "edit_amount":
            _clear_wa_pending_intent(from_number)
            try:
                amount = float(body.strip())
                clipping_id = _edit_pending.get("clipping_id")
                merchant = _edit_pending.get("merchant", "")
                # Get existing data and update amount
                row = lib._sb().table("wa_saves").select("data").eq("id", clipping_id).maybe_single().execute()
                if row and row.data:
                    data = row.data.get("data") or {}
                    data["total"] = amount
                    lib._sb().table("wa_saves").update({"data": data}).eq("id", clipping_id).execute()
                    resp.message(f"✅ Updated {merchant.title()} — bill amount now £{amount:.2f}")
                else:
                    resp.message("Clipping not found")
            except Exception as e:
                print(f"[edit_amount] {e}")
                resp.message(f"Error: {e}")
            return str(resp)

    # ── Receipt Query Handler ──────────────────────────────────────────────────────
    # Flexible patterns for: "what did i order at X", "last order X", "items from X", etc.
    _query_patterns = [
        r"(?:what|what's).{0,15}(?:did i|i).{0,15}(?:order|eat|have|buy|ord).{0,15}(?:at|in|from) (.+?)(?:\?|$)",
        r"(?:last|recent).{0,10}(?:order|receipt|items).{0,10}(?:at|in|from)? (.+?)(?:\?|$)",
        r"(?:order|items|receipt).{0,10}(?:at|in|from) (.+?)(?:\?|$)",
        r"(?:what|what's).{0,10}(?:at|in|from) (.+?)(?:\?|$)",
        r"^(.+?)(?:\?|$)(?:order|receipt|items|what did i)",  # Fallback: merchant name at start
    ]
    for pattern in _query_patterns:
        match = re.search(pattern, body_lower, re.IGNORECASE)
        if match:
            merchant_query = match.group(1).strip()
            try:
                _plain_fn = from_number.replace("whatsapp:", "").strip()
                # Search receipts for this merchant - order by upload time (created_at), not printed date (shop_date)
                rows = lib._sb().table("receipts").select("merchant,items,total,shop_date,created_at").eq("phone", _plain_fn)\
                    .ilike("merchant", f"%{merchant_query}%").order("created_at", desc=True).limit(3).execute().data or []

                if not rows:
                    resp.message(f"No orders found at '{merchant_query}'. Try a different spelling?")
                    return str(resp)

                # Auto-merge incomplete receipts from same date (items without merchant, or vice versa)
                # Also deduplicate to avoid showing same receipt multiple times
                try:
                    import json as _mj
                    _merged_ids = set()
                    for i, row in enumerate(rows):
                        if row.get("merchant") and not row.get("items") and row.get("shop_date"):
                            # This receipt has merchant but no items - find matching items receipt from SAME DATE
                            items_rows = lib._sb().table("receipts").select("id,items,shop_date").eq("phone", _plain_fn)\
                                .not_("items", "is", "null").eq("shop_date", row.get("shop_date"))\
                                .order("created_at", desc=True).limit(1).execute().data or []
                            if items_rows and items_rows[0].get("items"):
                                # Merge only if same date!
                                merged_items = items_rows[0]["items"]
                                lib._sb().table("receipts").update({"items": merged_items}).eq("id", row["id"]).execute()
                                row["items"] = merged_items
                                # Delete the now-merged items-only receipt
                                lib._sb().table("receipts").delete().eq("id", items_rows[0]["id"]).execute()
                                _merged_ids.add(items_rows[0]["id"])
                                print(f"[receipt_query] auto-merged items for {row.get('merchant')} on {row.get('shop_date')}")
                    # Deduplicate results by merchant + date
                    _seen = set()
                    rows = [r for r in rows if not (f"{r.get('merchant')}_{r.get('shop_date')}" in _seen or _seen.add(f"{r.get('merchant')}_{r.get('shop_date')}"))]
                except Exception as e:
                    print(f"[receipt_query] merge error: {e}")

                # Format results
                msg = f"📋 Orders at {rows[0]['merchant'].title()}:\n\n"
                for row in rows:
                    import json as _qj
                    items = []
                    try:
                        items = _qj.loads(row.get("items", "[]"))
                    except:
                        pass

                    date_str = row.get("shop_date", "")
                    date_display = f" on {date_str}" if date_str else ""
                    total_str = f"£{row.get('total'):.2f}" if row.get("total") else "—"

                    item_names = [i.get("name", "") for i in items if i.get("name")]
                    items_display = ", ".join(item_names[:5]) if item_names else "—"
                    if len(item_names) > 5:
                        items_display += f" +{len(item_names)-5} more"

                    msg += f"💰 {total_str}{date_display}\n"
                    msg += f"🛒 {items_display}\n\n"

                resp.message(msg)
                return str(resp)
            except Exception as e:
                print(f"[receipt_query] {e}")
                resp.message(f"Error looking up orders: {e}")
                return str(resp)

    # ── Merge clippings by merchant ────────────────────────────────────────────────
    if body_lower.startswith("merge "):
        merchant = body_lower.replace("merge ", "").strip()
        if not merchant:
            resp.message("Say *merge [store name]* — e.g. *merge renaissance* or *merge tesco*")
            return str(resp)
        try:
            _plain_fn = from_number.replace("whatsapp:", "").strip()
            # Find all clippings for this merchant
            rows = lib._sb().table("wa_saves").select("*").eq("from_number", _plain_fn)\
                .ilike("summary", f"%{merchant}%").order("created_at", desc=True).execute().data or []
            if not rows:
                resp.message(f"No clippings found for '{merchant}'. Check the spelling!")
                return str(resp)
            if len(rows) < 2:
                resp.message(f"Only found 1 clipping for '{merchant}' — nothing to merge!")
                return str(resp)
            # Merge: combine items + total
            merged_data = {"items": [], "total": None}
            for row in rows:
                data = row.get("data") or {}
                if data.get("items"):
                    merged_data["items"].extend(data.get("items", []))
                if data.get("total") and not merged_data["total"]:
                    merged_data["total"] = data["total"]
            # Keep the first (newest) clipping, delete others
            import json as _fj
            lib._sb().table("wa_saves").update({"data": merged_data}).eq("id", rows[0]["id"]).execute()
            for row in rows[1:]:
                lib._sb().table("wa_saves").delete().eq("id", row["id"]).execute()
            resp.message(f"✅ Merged {len(rows)} {merchant.title()} clippings! Now showing items + total together.")
        except Exception as e:
            print(f"[merge] {e}")
            resp.message(f"Merge failed: {e}")
        return str(resp)

    # ── Too Good To Go ────────────────────────────────────────────────────────────
    if body_lower in ("magic bags", "tgtg", "too good to go", "tgtg setup"):
        existing = None
        try:
            r = lib._sb().table("tgtg_accounts").select("status,email").eq("phone", from_number).maybe_single().execute()
            existing = r.data if r else None
        except Exception:
            pass
        if existing and existing.get("status") == "active":
            resp.message(f"✅ You already have Magic Bag alerts set up ({existing.get('email','')}).\n\nReply *tgtg stop* to pause or *tgtg check* to check now.")
        else:
            resp.message("🍱 *Too Good To Go Magic Bag Alerts*\n\nI'll ping you whenever a discounted bag becomes available near your home postcode.\n\nWhat's your Too Good To Go email address?")
            _set_wa_pending_intent(from_number, {"type": "tgtg_email"})
        return str(resp)

    if body_lower in ("tgtg stop", "stop tgtg", "stop magic bags", "pause tgtg"):
        try:
            lib._sb().table("tgtg_accounts").update({"status": "paused"}).eq("phone", from_number).execute()
        except Exception:
            pass
        resp.message("⏸ Magic Bag alerts paused. Reply *magic bags* anytime to restart.")
        return str(resp)

    if body_lower in ("tgtg done", "tgtg ready", "done tgtg", "clicked"):
        try:
            row = lib._sb().table("tgtg_accounts").select("email,polling_id").eq("phone", from_number).eq("status", "pending").maybe_single().execute()
            if not row or not row.data:
                resp.message("I don't have a pending TGTG login for you. Reply *magic bags* to start again.")
                return str(resp)
            creds = _tgtg_poll_login(row.data["email"], row.data["polling_id"])
            if not creds or not creds.get("access_token"):
                resp.message("❌ Couldn't verify the login yet — have you clicked the link in your email? Try again in a moment.")
                return str(resp)
            lib._sb().table("tgtg_accounts").update({**creds, "status": "active"}).eq("phone", from_number).execute()
            resp.message("✅ *Magic Bag alerts are on!*\n\nI'll WhatsApp you whenever a bag appears near your home postcode. Usually checking every hour.\n\nReply *tgtg stop* anytime to pause.")
        except Exception as e:
            resp.message(f"Something went wrong: {e}")
        return str(resp)

    if body_lower in ("tgtg check", "check tgtg", "check magic bags"):
        try:
            row = lib._sb().table("tgtg_accounts").select("*").eq("phone", from_number).eq("status", "active").maybe_single().execute()
            if not row or not row.data:
                resp.message("No active Magic Bag alerts. Reply *magic bags* to set up.")
                return str(resp)
            r = row.data
            lat, lon = r.get("lat"), r.get("lon")
            if not lat:
                pc = lib._sb().table("my_area_places").select("postcode").eq("from_number", from_number).eq("category", "_home").maybe_single().execute()
                if pc and pc.data:
                    ll = postcode_to_latlon(pc.data["postcode"])
                    if ll and ll[0]: lat, lon = ll
            if not lat:
                resp.message("I need your home postcode first. Reply with your postcode.")
                return str(resp)
            account = {k: r[k] for k in ("access_token","refresh_token","user_id","cookie") if r.get(k)}
            items = _tgtg_get_items(account, lat, lon, r.get("radius_km", 3))
            if not items:
                resp.message("🍱 No Magic Bags available near you right now. I'll ping you when one appears!")
            else:
                lines = []
                for item in items[:5]:
                    store = item.get("store", {}).get("store_name", "Unknown")
                    price = item.get("item", {}).get("price_including_taxes", {})
                    amount = price.get("minor_units", 0) / (10 ** price.get("decimals", 2))
                    avail = item.get("items_available", 0)
                    lines.append(f"🍱 *{store}* — £{amount:.2f} · {avail} left")
                resp.message("*Magic Bags near you right now:*\n\n" + "\n".join(lines))
        except Exception as e:
            resp.message(f"Error checking: {e}")
        return str(resp)

    # ── Pending intent: email reply for TGTG setup ────────────────────────────
    _email_m = re.match(r'^[\w.+\-]+@[\w.\-]+\.[a-z]{2,}$', body.strip(), re.I)
    if _email_m:
        _tgtg_pending = _get_wa_pending_intent(from_number)
        if _tgtg_pending and _tgtg_pending.get("type") == "tgtg_email":
            _clear_wa_pending_intent(from_number)
            _email_addr = body.strip().lower()
            try:
                polling_id = _tgtg_start_login(_email_addr)
                if not polling_id:
                    resp.message("❌ Couldn't reach Too Good To Go — try again in a minute.")
                    return str(resp)
                lib._sb().table("tgtg_accounts").upsert({
                    "phone": from_number.replace("whatsapp:", "").strip(),
                    "email": _email_addr,
                    "polling_id": polling_id,
                    "status": "pending"
                }).execute()
                resp.message(f"✅ Magic link sent to *{_email_addr}*!\n\nClick the link in your email (check spam too), then reply *tgtg done* and I'll activate your alerts.")
            except Exception as e:
                print(f"[tgtg_email] {e}")
                resp.message("Something went wrong setting up TGTG. Try replying *magic bags* to start again.")
            return str(resp)

    # ── Pending intent: number pick for heading_to_pick ─────────────────────────
    _num_pick = re.match(r'^([123])\s*$', body.strip())
    if _num_pick:
        _hpending = _get_wa_pending_intent(from_number)
        if _hpending and _hpending.get("type") == "heading_to_pick":
            _clear_wa_pending_intent(from_number)
            _branches  = _hpending.get("branches", [])
            _dest_name = _hpending.get("destination", "")
            _origin    = _hpending.get("origin", "")
            _idx = int(_num_pick.group(1)) - 1
            if 0 <= _idx < len(_branches):
                _branch = _branches[_idx]
                _label = _branch["name"]  # e.g. "IKEA Wembley", "Costco Farnborough"
                _dest_geo = (_branch["lat"], _branch["lng"]) if _branch.get("lat") else None
                reply = _heading_to_drive_reply(_label, _origin, _label + " UK", dest_geo=_dest_geo, from_number=from_number)
                resp.message(reply)
            else:
                resp.message(f"Didn't catch that — reply 1, 2 or 3 to pick a {_dest_name}.")
            return str(resp)

    # ── Pending intent: postcode reply resolves a stored intent ─────────────────
    _pc_reply = re.match(r'^([A-Z]{1,2}\d{1,2}[A-Z]?(?:\s*\d[A-Z]{2})?)\s*$', body.upper().strip())
    if _pc_reply:
        _pending = _get_wa_pending_intent(from_number)
        if _pending:
            _clear_wa_pending_intent(from_number)
            _ptype = _pending.get("type", "")
            if _ptype == "setup_postcode":
                _pc_val = _pc_reply.group(1).upper()
                try:
                    sb = lib._sb()
                    plain = from_number.replace("whatsapp:", "").strip()
                    sb.table("my_area_places").delete().eq("from_number", plain).eq("category", "_home").execute()
                    sb.table("my_area_places").insert({
                        "name": "__home__", "category": "_home",
                        "postcode": _pc_val.replace(" ", ""),
                        "emoji": "📍", "from_number": plain, "device_id": plain
                    }).execute()
                except Exception as e:
                    print(f"[setup_postcode] {e}")
                _wt = _wa_user_token(from_number)
                resp.message(
                    f"✅ *{_pc_val}* saved as your home.\n\n"
                    f"Now try:\n"
                    f"🚆 _next train_\n"
                    f"⛽ _petrol prices_\n"
                    f"🏡 _places near me_\n\n"
                    f"👉 Open your personalised Miru:\n"
                    f"miru.humanagency.co/?wt={_wt}"
                )
                return str(resp)
            if _ptype == "food":
                _cheap_pfx = "cheap " if _pending.get("cheap") else ""
                _food_body  = f"{_cheap_pfx}{_pending['food_type']} {_pc_reply.group(1)}"
                _food_reply = _wa_food_find(_food_body, from_number)
                resp.message(_food_reply or f"Nothing found near {_pc_reply.group(1)}. Try again!")
                return str(resp)
            elif _ptype == "train":
                _tr = _wa_train_format(_pending.get("from", ""), _pc_reply.group(1))
                if _tr:
                    resp.message(_tr)
                    return str(resp)

    # ── Recipe save — user replies "save" after receiving a recipe ───────────
    _recipe_pending = _get_wa_pending_intent(from_number)
    if _recipe_pending and _recipe_pending.get("type") == "recipe_save" and body_lower.strip() in ("save", "yes", "save it", "save recipe"):
        _clear_wa_pending_intent(from_number)
        _rtitle = _recipe_pending.get("title", "Recipe")
        _rtext  = _recipe_pending.get("text", "")
        try:
            plain = from_number.replace("whatsapp:", "").strip()
            lib._sb().table("wa_saves").insert({
                "from_number": plain,
                "url":         f"recipe:{_rtitle.lower().replace(' ', '_')}",
                "title":       f"🍳 {_rtitle.title()}",
                "summary":     _rtext,
                "status":      "read",
                "category":    "recipe",
            }).execute()
            resp.message(f"✅ *{_rtitle.title()}* saved to your Recipes in Clippings.\n\nView: miru.humanagency.co")
        except Exception as _re:
            resp.message("Couldn't save just now — try again.")
        return str(resp)

    # ── Regular place — user confirms a frequent destination ─────────────────
    _reg_pending = _get_wa_pending_intent(from_number)
    if _reg_pending and _reg_pending.get("type") == "regular_place" and body_lower.strip() in ("regular", "yes", "save", "add regular", "save regular"):
        _clear_wa_pending_intent(from_number)
        _reg_name = _reg_pending.get("name", "")
        _confirm_frequent_place(from_number, _reg_name)
        resp.message(f"✅ *{_reg_name.title()}* saved as a regular. I'll mention it in your brief when it makes sense.")
        return str(resp)

    # ── URL save ──────────────────────────────────────────────────────────────
    url_m = re.search(r'https?://\S+', body)
    if url_m:
        url = url_m.group(0).rstrip(".,)")
        reply = _wa_save_url(from_number, url)
        resp.message(reply)
        return str(resp)

    # ── Digest numbered reply: "1 READ", "2 SKIP", "3 REMIND Monday" ─────────
    digest_m = re.match(r'^([1-9])\s+(READ|SKIP|REMIND\S*(?:\s+\S+)?)\s*$', body.strip(), re.I)
    if digest_m:
        idx = int(digest_m.group(1)) - 1
        cmd = digest_m.group(2).strip().upper()
        # Re-fetch from Supabase if in-memory state was lost (e.g. server restart)
        items = _PENDING_DIGEST.get(from_number)
        if not items:
            try:
                rows = (lib._sb().table("wa_saves").select("id,title,url")
                        .eq("from_number", from_number)
                        .in_("status", ["pending", "remind"])
                        .order("created_at").limit(9).execute().data)
                items = [{"id": r["id"], "title": r.get("title") or "Untitled", "url": r.get("url", "")} for r in rows]
                _PENDING_DIGEST[from_number] = items
            except Exception:
                items = []
        if 0 <= idx < len(items):
            item = items[idx]
            _PENDING_TRIAGE[from_number] = {
                "id": item["id"], "title": item["title"], "url": item["url"],
                "expires": time.time() + 3600,
            }
            reply = _wa_triage_respond(from_number, cmd)
        else:
            reply = "Couldn't find that item — reply LIST to see your saves, or paste the link again."
        resp.message(reply)
        return str(resp)

    # ── Single-item triage reply (after sending a URL) ────────────────────────
    cmd_up = body.strip().upper()
    if cmd_up in ("READ", "SKIP") or cmd_up.startswith("REMIND"):
        reply = _wa_triage_respond(from_number, cmd_up)
        resp.message(reply)
        return str(resp)

    # ── Wine rating reply: "4 Great with pasta" or "3.5 too tannic" ─────────────
    _wine_state = _WINE_RATING_STATE.get(from_number)
    if _wine_state and time.time() < _wine_state.get("expires", 0):
        import re as _wre
        _wm = _wre.match(r'^([1-5](?:[.,]\d)?)\s*(.*)', body.strip(), _wre.DOTALL)
        if _wm:
            _score = _wm.group(1).replace(",", ".")
            _notes = _wm.group(2).strip()
            _WINE_RATING_STATE.pop(from_number, None)
            try:
                _wsid = _wine_state["save_id"]
                _existing = lib._sb().table("wa_saves").select("summary").eq("id", _wsid).execute().data
                _esummary = (_existing[0]["summary"] if _existing else "") or ""
                _rating_line = f"\n\n⭐ My rating: {_score}/5"
                if _notes:
                    _rating_line += f"\n📝 {_notes[:200]}"
                lib._sb().table("wa_saves").update({"summary": _esummary + _rating_line}).eq("id", _wsid).execute()
                lib.saves_sync({"id": _wsid, **(_existing[0] if _existing else {}), "summary": _esummary + _rating_line})
                resp.message(f"✅ Rated *{_wine_state['wine_name']}* {_score}/5!")
            except Exception:
                resp.message("✅ Rating saved!")
            return str(resp)

    # ── QUICK SPEND LOG: "Waitrose 34 at Sunningdale" or "Petrol 45 at Egham" ────────
    import re as _qs_re
    _quick_spend_pat = _qs_re.match(r'^([a-z\s&\']+?)\s+([\d.]+)\s+(?:at|@)\s+([a-z\s]+?)$', body_lower)
    if _quick_spend_pat:
        merchant_raw = _quick_spend_pat.group(1).strip().title()
        amount_str = _quick_spend_pat.group(2).strip()
        location = _quick_spend_pat.group(3).strip().title()
        try:
            amount = float(amount_str)
            category = _receipt_category(merchant_raw)
            title = f"🧾 {merchant_raw} at {location}"
            summary = f"£{amount:.2f}"
            lib._sb().table("wa_saves").insert({
                "from_number": from_number,
                "device_id": from_number,
                "title": title,
                "summary": summary,
                "category": category,
                "created_at": datetime.utcnow().isoformat(),
                "type": "receipt",
                "source": "manual_log"
            }).execute()
            resp.message(f"✅ Logged: {merchant_raw} £{amount:.2f} at {location} ({category})")
            return str(resp)
        except (ValueError, Exception):
            pass

    # ── RECEIPT ITEMS — "whats in it", "what did I order at X", "[merchant] receipt" ─
    import re as _ri_re
    _RECEIPT_ITEMS_PAT = _ri_re.compile(
        r'\b(what(?:\'s|\s+is|\s+was)\s+in\s+it'
        r'|break\s+it\s+down'
        r'|list\s+(?:the\s+)?items'
        r'|show\s+(?:me\s+)?(?:the\s+)?items'
        r'|what(?:\'s|\s+was)\s+in\s+(?:that|the\s+receipt)'
        r'|what\s+did\s+i\s+(?:actually\s+)?buy\s+(?:there|from\s+there)'
        r'|what\s+did\s+i\s+order'
        r'|what\s+(?:was|were)\s+(?:my|the)\s+order'
        r'|show\s+(?:me\s+)?(?:my\s+)?receipt)\b',
        _ri_re.IGNORECASE
    )
    # Also catch "[merchant name] receipt" as a receipt-items request (not spend total)
    _MERCHANT_RECEIPT_RE = _ri_re.compile(
        r'^([a-z][a-z0-9&\s\']{2,30}?)\s+receipt\s*$', _ri_re.IGNORECASE
    )
    _mr_match = _MERCHANT_RECEIPT_RE.match(body_lower)

    if _RECEIPT_ITEMS_PAT.search(body_lower) or _mr_match:
        _ri_pending = _get_wa_pending_intent(from_number)
        _ri_merchant, _ri_date = "", ""
        if _mr_match:
            # "[merchant] receipt" — merchant is explicit in the message
            _ri_merchant = _mr_match.group(1).strip()
        elif _ri_pending and _ri_pending.get("type") == "receipt_items":
            _ri_merchant = _ri_pending.get("merchant_filter", "")
            _ri_date = _ri_pending.get("date_from", "")
            _clear_wa_pending_intent(from_number)
        else:
            # "what did I order at Royal Rasoi" — extract merchant after at/in/from
            _at_match = _ri_re.search(
                r'\b(?:at|in|from|for)\s+([A-Za-z][A-Za-z0-9&\s\']{2,30}?)(?:\s*\??\s*$)',
                body_lower
            )
            if _at_match:
                _ri_merchant = _at_match.group(1).strip()
        resp.message(_wa_receipt_items(from_number, _ri_merchant, _ri_date))
        return str(resp)

    # ── SPENDING / RECEIPTS query — natural language intent detection ─────────
    if _is_spend_query(body_lower):
        spend_reply = _wa_spending_query(from_number, body_lower)
        # Extract category from query for follow-ups (e.g., "chai" → "Coffee & Lunch")
        import re as _spend_re
        for kw, cat in _SPEND_CATEGORY_MAP.items():
            if kw in body_lower:
                try:
                    _set_wa_pending_intent(from_number, {
                        "type": "spend_query_followup",
                        "category": cat,
                        "query": body_lower,
                    })
                except Exception:
                    pass
                break
        resp.message(spend_reply)
        return str(resp)

    # ── SPENDING FOLLOW-UP: "where", "which cafe", etc. after a spend query ─────
    if body_lower in ("where", "where from", "which cafe", "which ones", "which places"):
        _sp_pending = _get_wa_pending_intent(from_number)
        if _sp_pending and _sp_pending.get("type") == "spend_query_followup":
            stores = _sp_pending.get("stores", [])
            category = _sp_pending.get("category", "")
            if stores:
                reply = f"☕ You had {category} at:\n" + "\n".join(f"• {s}" for s in stores)
                resp.message(reply)
                return str(resp)

    if body_lower in ("new", "new save", "new session"):
        _MENU_SESSION.pop(from_number, None)
        resp.message("✅ Started fresh — send your next photo to begin a new save.")
        return str(resp)

    # ── MY LINK command: send the user their personal access link ─────────────
    if body_lower in ("my link", "link", "my saves link", "get link", "access", "my access"):
        wt = _wa_user_token(from_number)
        resp.message(
            f"🔗 Your personal Miru:\n"
            f"miru.humanagency.co/?wt={wt}\n\n"
            f"Tap to open — logs you in automatically on any browser."
        )
        return str(resp)

    # ── MY PLACES command: list or search My Area saved places ────────────────
    if body_lower in ("my places", "my bookmarks", "places", "saved places") or body_lower.startswith("find my "):
        user_token = _wa_user_token(from_number)
        query = ""
        if body_lower.startswith("find my "):
            query = body_lower[len("find my "):].strip()
        try:
            rows = (lib._sb().table("my_area_places")
                    .select("name,address,phone,emoji,opening_hours")
                    .eq("device_id", user_token)
                    .order("created_at").execute().data)
        except Exception:
            rows = []
        if not rows:
            resp.message(
                f"📌 No saved places found.\n\n"
                f"To sync your web bookmarks with WhatsApp, open this link:\n"
                f"miru.humanagency.co/?screen=myarea&token={user_token}\n\n"
                f"Bookmarks you add after opening that link will be searchable here."
            )
            return str(resp)
        if query:
            rows = [r for r in rows if query in r.get("name","").lower() or query in r.get("address","").lower()]
            if not rows:
                resp.message(f"🔍 Nothing found for '{query}' in your saved places.")
                return str(resp)
        lines = [f"📌 My Saved Places ({len(rows)}):"]
        for r in rows[:10]:
            line = f"\n{r.get('emoji','📍')} *{r['name']}*"
            if r.get("address"):  line += f"\n   {r['address']}"
            if r.get("phone"):    line += f"\n   📞 {r['phone']}"
            if r.get("opening_hours"): line += f"\n   🕐 {r['opening_hours']}"
            lines.append(line)
        if len(rows) > 10:
            lines.append(f"\n…and {len(rows)-10} more. Open the app to see all.")
        resp.message("\n".join(lines))
        return str(resp)

    # ── SHOPPING LIST command: extract ingredients from last recipe save ─────
    if cmd_up in ("SHOPPING LIST", "INGREDIENTS", "LIST INGREDIENTS", "RECIPE LIST"):
        plain_number = from_number.replace("whatsapp:", "").strip()
        wa_number    = from_number if from_number.startswith("whatsapp:") else f"whatsapp:{from_number}"
        try:
            rows = (lib._sb().table("wa_saves").select("id,title,url,summary")
                    .in_("from_number", [from_number, plain_number, wa_number])
                    .like("title", "🍳%")
                    .order("created_at", desc=True).limit(1).execute().data)
        except Exception:
            rows = []
        if not rows:
            resp.message("🍳 No recipe saves found. Save a recipe URL first — e.g. send a link from BBC Food or AllRecipes.")
            return str(resp)
        row = rows[0]
        recipe_title = (row.get("title") or "").replace("🍳 ", "").strip()
        recipe_url   = row.get("url", "")
        # Try to fetch fresh page text; fall back to stored summary
        try:
            fetched = _fetch_url_text(recipe_url)
            page_text = fetched.get("text", "") or row.get("summary", "")
        except Exception:
            page_text = row.get("summary", "")
        if not page_text:
            resp.message(f"🍳 Couldn't load *{recipe_title}* — try opening the recipe link directly.")
            return str(resp)
        try:
            ingredients = _groq_chat(
                system=(
                    "Extract the shopping list (ingredients only, no quantities of equipment) "
                    "from this recipe. Format as a plain bullet list with • prefix, one item per line. "
                    "Group by category if helpful (e.g. Produce, Dairy, Meat). "
                    "Max 30 items. No intro or outro text."
                ),
                messages=[{"role": "user", "content": f"Recipe: {recipe_title}\n\n{page_text[:4000]}"}],
                max_tokens=400,
            ).strip()
        except Exception:
            ingredients = ""
        if not ingredients:
            resp.message(f"🍳 Couldn't extract ingredients from *{recipe_title}*. Try opening the recipe link.")
            return str(resp)
        resp.message(f"🛒 *Shopping list — {recipe_title}*\n\n{ingredients}")
        return str(resp)

    # ── WORTH IT / BOOK REVIEW command ────────────────────────────────────────
    # "worth it" alone = review last scanned; handled here. "review [title]" is handled below.
    if cmd_up in ("WORTH IT", "WORTH IT?", "REVIEWS", "BOOK REVIEW", "THOUGHTS"):
        # Books saved via app use plain number; WhatsApp scans use "whatsapp:+..." prefix
        plain_number = from_number.replace("whatsapp:", "").strip()
        wa_number    = from_number if from_number.startswith("whatsapp:") else f"whatsapp:{from_number}"
        try:
            rows = (lib._sb().table("wa_saves").select("id,title,url,summary")
                    .in_("from_number", [from_number, plain_number, wa_number])
                    .like("url", "book:%")
                    .order("created_at", desc=True).limit(1).execute().data)
        except Exception:
            rows = []
        if not rows:
            resp.message("📚 No scanned books found. Scan a book barcode in the Miru app first.")
            return str(resp)
        row = rows[0]
        book_title, book_author, book_desc, book_genre, book_rating = row.get("title", ""), "", "", "", None
        try:
            import json as _json
            bk = _json.loads(row.get("summary") or "{}")
            book_title  = bk.get("title", book_title)
            book_author = bk.get("author", "")
            book_desc   = bk.get("description", "")[:600]
            book_genre  = bk.get("subjects", "") or bk.get("genre", "")
            cr = bk.get("communityRating") or {}
            book_rating = cr.get("avg")
        except Exception:
            pass
        book_label = f"*{book_title}*" + (f" by {book_author}" if book_author else "")

        # Build grounded context from stored data so Groq doesn't hallucinate
        context_lines = [f"Title: {book_title}"]
        if book_author: context_lines.append(f"Author: {book_author}")
        if book_genre:  context_lines.append(f"Genre: {book_genre}")
        if book_rating: context_lines.append(f"Google Books rating: {book_rating}/5")
        if book_desc:   context_lines.append(f"Description: {book_desc}")
        context = "\n".join(context_lines)

        try:
            verdict = _groq_chat(
                system=(
                    "You are a concise book critic. Using ONLY the provided book information (do not invent facts), "
                    "write exactly 4 lines:\n"
                    "Line 1: ✅ Fans say: [what the description/genre suggests readers will love — max 15 words]\n"
                    "Line 2: ⚠️ Critics say: [likely criticism based on genre/style — max 15 words]\n"
                    "Line 3: 🎯 Best for: [who this book suits — max 10 words]\n"
                    "Line 4: 📖 Verdict: Worth it / Skip it / Depends on taste — one sentence reason\n"
                    "If you don't have enough information, be honest and say so on line 1. No other text."
                ),
                messages=[{"role": "user", "content": context}],
                max_tokens=220,
            ).strip()
        except Exception:
            verdict = ""
        if not verdict:
            resp.message(f"📚 Couldn't generate a review for {book_label} right now. Try again shortly.")
            return str(resp)
        rating_line = f"\n⭐ {book_rating}/5 on Google Books" if book_rating else ""
        resp.message(f"📚 {book_label}{rating_line}\n\n{verdict}")
        return str(resp)

    # ── SAVE SONG <title> command ─────────────────────────────────────────────
    _song_prefixes = ("save song ", "song ", "add song ", "music ")
    _sg_prefix = next((p for p in _song_prefixes if body_lower.startswith(p)), None)
    if _sg_prefix:
        sg_query = body[len(_sg_prefix):].strip()
        if not sg_query:
            resp.message("🎵 Tell me what to save — e.g.\n*save song Blinding Lights*")
            return str(resp)
        try:
            _it = requests.get(
                "https://itunes.apple.com/search",
                params={"term": sg_query, "entity": "song", "limit": 1, "country": "GB"},
                timeout=8,
            ).json()
            _track = (_it.get("results") or [None])[0]
        except Exception:
            _track = None
        if not _track:
            # Save raw query as unmatched so user doesn't lose the intent
            _wa_phone_um = from_number.replace("whatsapp:", "")
            try:
                _um_exists = lib._sb().table("music_saves").select("id") \
                    .eq("phone", _wa_phone_um).eq("title", sg_query).execute().data
                if not _um_exists:
                    lib._sb().table("music_saves").insert({
                        "phone":       _wa_phone_um,
                        "title":       sg_query,
                        "artist":      "",
                        "album":       "",
                        "year":        "",
                        "genre":       "",
                        "cover_url":   "",
                        "preview_url": "",
                        "spotify_url": f"unmatched:{sg_query}",
                    }).execute()
            except Exception:
                pass
            resp.message(
                f"💾 Saved *{sg_query}* to your list.\n"
                f"Couldn't match it on iTunes — open My Clippings to search for it.\n"
                f"miru.humanagency.co/?screen=music"
            )
            return str(resp)
        _sg_title   = _track.get("trackName", sg_query)
        _sg_artist  = _track.get("artistName", "")
        _sg_album   = _track.get("collectionName", "")
        _sg_year    = str(_track.get("releaseDate", ""))[:4]
        _sg_genre   = _track.get("primaryGenreName", "")
        _sg_cover   = (_track.get("artworkUrl100") or "").replace("100x100", "300x300")
        _sg_preview = _track.get("previewUrl", "")
        _sg_spotify = f"https://open.spotify.com/search/{requests.utils.quote(_sg_title + ' ' + _sg_artist)}"
        _wa_phone   = from_number.replace("whatsapp:", "")
        try:
            _existing = lib._sb().table("music_saves") \
                .select("id").eq("phone", _wa_phone).eq("title", _sg_title).eq("artist", _sg_artist).execute().data
            if not _existing:
                lib._sb().table("music_saves").insert({
                    "phone":       _wa_phone,
                    "title":       _sg_title,
                    "artist":      _sg_artist,
                    "album":       _sg_album,
                    "year":        _sg_year,
                    "genre":       _sg_genre,
                    "cover_url":   _sg_cover,
                    "preview_url": _sg_preview,
                    "spotify_url": _sg_spotify,
                }).execute()
            _already = bool(_existing)
        except Exception:
            _already = False
        _save_status = "Already in" if _already else "Saved to"
        resp.message(
            f"🎵 *{_sg_title}*\n{_sg_artist}"
            + (f" · {_sg_album}" if _sg_album else "")
            + (f" · {_sg_year}" if _sg_year else "")
            + f"\n\n{'✅' if not _already else '📌'} {_save_status} your Music tab"
            + f"\nmiru.humanagency.co/?screen=music"
        )
        return str(resp)

    # ── BOOK <title or ISBN> command ──────────────────────────────────────────
    _book_prefixes = ("book ", "add book ", "save book ", "find book ")
    _bk_prefix = next((p for p in _book_prefixes if body_lower.startswith(p)), None)
    if _bk_prefix:
        bk_query = body[len(_bk_prefix):].strip()
        if not bk_query:
            resp.message("📚 Tell me what to find — e.g.\n*book The Midnight Library*\nor\n*book 9781399401739*")
            return str(resp)
        # Normalise ISBN: strip dashes/spaces, check 13 or 10 digits
        _isbn_raw = re.sub(r"[\s\-]", "", bk_query)
        if re.match(r"^(978|979)\d{10}$", _isbn_raw) or re.match(r"^\d{10}$", _isbn_raw):
            bk_isbn = _isbn_raw
            bk_info = _lookup_book_by_isbn(bk_isbn)
        else:
            bk_info = _lookup_book_by_title(bk_query)
            bk_isbn = bk_info.get("isbn", "") if bk_info else ""
        if not bk_info or not bk_info.get("title"):
            resp.message(f"📚 Couldn't find *{bk_query}* — try a more specific title or the ISBN printed below the barcode.")
            return str(resp)
        # Save to wa_saves
        try:
            plain_number = from_number.replace("whatsapp:", "").strip()
            existing = (lib._sb().table("wa_saves").select("id")
                        .in_("from_number", [from_number, plain_number])
                        .eq("url", f"book:{bk_isbn}").limit(1).execute().data)
            if existing:
                already = True
            else:
                already = False
                lib._sb().table("wa_saves").insert({
                    "from_number": plain_number,
                    "url":         f"book:{bk_isbn}",
                    "title":       bk_info["title"],
                    "summary":     json.dumps(bk_info),
                    "status":      "wishlist",
                }).execute()
                try:
                    lib.books_upsert(plain_number, {**bk_info, "isbn": bk_isbn, "source": "whatsapp_text"})
                except Exception:
                    pass
        except Exception:
            already = False
        user_token = _wa_user_token(from_number)
        msg = f"📚 *{bk_info['title']}*"
        if bk_info.get("author"):
            msg += f"\nby {bk_info['author']}"
        cr = bk_info.get("communityRating")
        if cr and cr.get("avg"):
            msg += f"\n{'⭐' * round(cr['avg'])} {cr['avg']}/5"
            if cr.get("count"): msg += f" ({cr['count']:,} ratings)"
        if bk_info.get("description"):
            msg += f"\n\n_{bk_info['description'][:220].strip()}…_"
        if already:
            msg += f"\n\n_(already in your books)_"
        else:
            msg += f"\n\n📚 Saved to My Books: miru.humanagency.co/?screen=scan&token={user_token}"
        resp.message(msg)
        return str(resp)

    # ── BOOK NATURAL LANGUAGE — fuzzy intent via Groq ────────────────────────
    # Catches any book-related phrasing not already handled by exact commands above
    _BOOK_NL_RE = re.compile(
        r'\b(?:book|read|reading|review|library|finished|author|novel|isbn|'
        r'worth\s+reading|have\s+i\s+read|did\s+i\s+read|do\s+i\s+have|'
        r'want\s+to\s+read|currently\s+reading|started\s+reading|'
        r'completed|done\s+reading|surrey|chapters?)\b', re.I
    )
    if _BOOK_NL_RE.search(body) and not _bk_prefix and body_lower not in _MY_BOOKS_TRIGGERS \
            and not body_lower.startswith("my books") and not body_lower.startswith("books i ") \
            and cmd_up not in ("WORTH IT", "WORTH IT?", "REVIEWS", "BOOK REVIEW", "THOUGHTS"):
        try:
            _nl_raw = _groq_chat(
                system=(
                    'Extract the book intent from this WhatsApp message. '
                    'Respond with JSON only:\n'
                    '{"intent":"check_read|review|mark_read|mark_reading|mark_wishlist|library_check|add|unknown",'
                    '"title":"book title extracted, or empty string"}\n\n'
                    'Intents:\n'
                    '- check_read: asking if they have read or own a book ("do i have", "have i read", "did i read")\n'
                    '- review: wants a review or opinion ("book review", "reviews", "is it worth reading", "thoughts on")\n'
                    '- mark_read: finished or completed a book ("finished", "done reading", "completed")\n'
                    '- mark_reading: currently reading ("reading", "started reading", "currently reading")\n'
                    '- mark_wishlist: wants to read ("want to read", "want")\n'
                    '- library_check: checking local library availability ("library", "surrey library", "available at library")\n'
                    '- add: adding/saving a book ("add book", "save book")\n'
                    '- unknown: not a book request'
                ),
                messages=[{"role": "user", "content": body}],
                max_tokens=80,
                json_mode=True,
            )
            _nl = json.loads(_nl_raw) if isinstance(_nl_raw, str) else (_nl_raw or {})
            _nl_intent = (_nl.get("intent") or "unknown").strip()
            _nl_title  = (_nl.get("title") or "").strip()
        except Exception:
            _nl_intent, _nl_title = "unknown", ""

        if _nl_intent != "unknown" and _nl_title:
            plain_number = from_number.replace("whatsapp:", "").strip()
            wa_number    = f"whatsapp:{plain_number}"

            if _nl_intent == "check_read":
                hits = lib.books_search(plain_number, _nl_title, hits_per_page=5)
                if not hits: hits = lib.books_search(wa_number, _nl_title, hits_per_page=5)
                if hits:
                    b = hits[0]
                    status_label = {"read": "✅ Yes, you've read it", "reading": "📖 You're currently reading it",
                                    "wishlist": "📌 On your want-to-read list"}.get(b.get("status",""), "📚 In your library")
                    msg = f"{status_label}\n\n*{b.get('title','')}*"
                    if b.get("author"): msg += f"\nby {b['author']}"
                    if b.get("rating"): msg += f"\nYour rating: {'⭐'*int(b['rating'])}"
                else:
                    try:
                        rows = (lib._sb().table("wa_saves")
                                .select("title,url,status")
                                .in_("from_number", [from_number, plain_number, wa_number])
                                .like("url", "book:%").ilike("title", f"%{_nl_title}%")
                                .limit(3).execute().data)
                    except Exception:
                        rows = []
                    if rows:
                        r = rows[0]
                        status_label = {"read": "✅ Yes, you've read it", "reading": "📖 You're currently reading it",
                                        "wishlist": "📌 On your want-to-read list"}.get(r.get("status",""), "📚 In your library")
                        msg = f"{status_label}\n\n*{r.get('title','').replace('📚 ','')}*"
                    else:
                        msg = f"📚 I don't have *{_nl_title}* in your library.\n\nSend *book {_nl_title}* to add it."
                resp.message(msg)
                return str(resp)

            elif _nl_intent == "review":
                bk = _lookup_book_by_title(_nl_title)
                if not bk or not bk.get("title"):
                    resp.message(f"📚 Couldn't find *{_nl_title}* — try the exact title.")
                    return str(resp)
                book_label = f"*{bk['title']}*" + (f" by {bk['author']}" if bk.get("author") else "")
                ctx = [f"Title: {bk['title']}"]
                if bk.get("author"):      ctx.append(f"Author: {bk['author']}")
                if bk.get("subjects"):    ctx.append(f"Genre: {bk['subjects']}")
                if bk.get("description"): ctx.append(f"Description: {bk['description'][:500]}")
                cr = bk.get("communityRating") or {}
                if cr.get("avg"):         ctx.append(f"Google Books rating: {cr['avg']}/5")
                try:
                    verdict = _groq_chat(
                        system=(
                            "You are a concise book critic. Using ONLY the provided information, write exactly 4 lines:\n"
                            "Line 1: ✅ Fans say: [what readers love — max 15 words]\n"
                            "Line 2: ⚠️ Critics say: [likely criticism — max 15 words]\n"
                            "Line 3: 🎯 Best for: [who this suits — max 10 words]\n"
                            "Line 4: 📖 Verdict: Worth it / Skip it / Depends on taste — one sentence reason\nNo other text."
                        ),
                        messages=[{"role": "user", "content": "\n".join(ctx)}],
                        max_tokens=220,
                    ).strip()
                except Exception:
                    verdict = ""
                rating_line = f"\n⭐ {cr['avg']}/5 on Google Books" if cr.get("avg") else ""
                resp.message(f"📚 {book_label}{rating_line}\n\n{verdict}")
                return str(resp)

            elif _nl_intent in ("mark_read", "mark_reading", "mark_wishlist"):
                new_status  = {"mark_read": "read", "mark_reading": "reading", "mark_wishlist": "wishlist"}[_nl_intent]
                status_emoji = {"read": "✅", "reading": "📖", "wishlist": "📌"}[new_status]
                status_word  = {"read": "marked as read", "reading": "marked as reading", "wishlist": "added to want-to-read"}[new_status]
                try:
                    rows = (lib._sb().table("wa_saves").select("id,title,url,summary")
                            .in_("from_number", [from_number, plain_number, wa_number])
                            .like("url", "book:%").ilike("title", f"%{_nl_title}%")
                            .limit(3).execute().data)
                except Exception:
                    rows = []
                if not rows:
                    bk_info = _lookup_book_by_title(_nl_title)
                    if not bk_info or not bk_info.get("title"):
                        resp.message(f"📚 Couldn't find *{_nl_title}*. Try *book {_nl_title}* to add it first.")
                        return str(resp)
                    bk_isbn = bk_info.get("isbn", "")
                    try:
                        lib._sb().table("wa_saves").insert({
                            "from_number": plain_number, "url": f"book:{bk_isbn}",
                            "title": bk_info["title"], "summary": json.dumps(bk_info), "status": new_status,
                        }).execute()
                        lib.books_upsert(plain_number, {**bk_info, "isbn": bk_isbn, "status": new_status, "source": "whatsapp_status"})
                    except Exception:
                        pass
                    resp.message(f"{status_emoji} *{bk_info['title']}* {status_word} and added to your library.")
                    return str(resp)
                row = rows[0]
                try:
                    lib._sb().table("wa_saves").update({"status": new_status}).eq("id", row["id"]).execute()
                    bk_isbn = (row.get("url") or "").replace("book:", "")
                    if bk_isbn:
                        bk_meta = {}
                        try: bk_meta = json.loads(row.get("summary") or "{}")
                        except Exception: pass
                        lib.books_upsert(plain_number, {**bk_meta, "isbn": bk_isbn, "status": new_status})
                except Exception:
                    pass
                title_clean = (row.get("title") or _nl_title).replace("📚 ", "")
                resp.message(f"{status_emoji} *{title_clean}* {status_word}.")
                return str(resp)

            elif _nl_intent == "add":
                bk_info = _lookup_book_by_title(_nl_title)
                if not bk_info or not bk_info.get("title"):
                    resp.message(f"📚 Couldn't find *{_nl_title}* — try a more specific title.")
                    return str(resp)
                bk_isbn = bk_info.get("isbn", "")
                try:
                    existing = (lib._sb().table("wa_saves").select("id")
                                .in_("from_number", [from_number, plain_number])
                                .eq("url", f"book:{bk_isbn}").limit(1).execute().data)
                    already = bool(existing)
                    if not already:
                        lib._sb().table("wa_saves").insert({
                            "from_number": plain_number, "url": f"book:{bk_isbn}",
                            "title": bk_info["title"], "summary": json.dumps(bk_info), "status": "wishlist",
                        }).execute()
                        lib.books_upsert(plain_number, {**bk_info, "isbn": bk_isbn, "source": "whatsapp_text"})
                except Exception:
                    already = False
                user_token = _wa_user_token(from_number)
                msg = f"📚 *{bk_info['title']}*"
                if bk_info.get("author"): msg += f"\nby {bk_info['author']}"
                msg += "\n\n_(already in your books)_" if already else f"\n\n📚 Saved: miru.humanagency.co/?screen=scan&token={user_token}"
                resp.message(msg)
                return str(resp)

            elif _nl_intent == "library_check":
                import urllib.parse
                q = urllib.parse.quote(_nl_title or "")
                ebook_url = f"https://surreycountyuk.overdrive.com/search?query={q}"
                resp.message(
                    f"📚 *{_nl_title}* — Surrey Libraries\n\n"
                    f"📱 *Borrow ebook/audiobook (OverDrive):*\n{ebook_url}\n\n"
                    f"🏛️ *Physical copy — search the catalogue:*\nhttps://libraries.surreycc.gov.uk/bookshelf"
                )
                return str(resp)

    # ── FIND SAVE command: search wa_saves ───────────────────────────────────
    if body_lower.startswith("find save ") or body_lower.startswith("search saves ") or body_lower.startswith("find saves "):
        prefix = next(p for p in ("find save ", "search saves ", "find saves ") if body_lower.startswith(p))
        query = body_lower[len(prefix):].strip()
        if query:
            try:
                hits = lib.saves_search(query, from_number=from_number, hits_per_page=8)
            except Exception:
                hits = []
            if not hits:
                resp.message(f"🔍 Nothing found for \"{query}\" in your saves.\n\nTip: search in the app at miru.humanagency.co")
            else:
                lines = [f"🔍 Saves matching \"{query}\":"]
                for h in hits[:6]:
                    title = h.get("title") or h.get("doc_title") or "Untitled"
                    summary = (h.get("summary") or "")[:120]
                    lines.append(f"\n*{title}*")
                    if summary:
                        lines.append(f"   {summary}")
                resp.message("\n".join(lines))
            return str(resp)

    # ── LIST command: on-demand saves summary ─────────────────────────────────
    if cmd_up == "LIST":
        try:
            rows = (lib._sb().table("wa_saves").select("id,title,url,status")
                    .eq("from_number", from_number)
                    .in_("status", ["pending", "remind"])
                    .order("created_at").limit(9).execute().data)
        except Exception:
            rows = []
        if not rows:
            resp.message("No pending saves. Send any URL to save it.")
        else:
            _PENDING_DIGEST[from_number] = [
                {"id": r["id"], "title": r.get("title") or "Untitled", "url": r.get("url", "")}
                for r in rows
            ]
            lines = [f"📋 {len(rows)} pending:\n"]
            for i, r in enumerate(rows, 1):
                lines.append(f"{i}. {(r.get('title') or r.get('url',''))[:60]}")
            lines.append("\nReply: *1 READ*, *2 SKIP*, *3 REMIND Monday*")
            resp.message("\n".join(lines))
        return str(resp)

    # ── MY BOOKS command ─────────────────────────────────────────────────────
    _MY_BOOKS_TRIGGERS = {
        "my books", "books", "my reading list", "reading list",
        "books i want to read", "my wishlist", "book list",
        "show my books", "list my books",
    }
    if body_lower in _MY_BOOKS_TRIGGERS or body_lower.startswith("my books") or body_lower.startswith("books i "):
        plain_number = from_number.replace("whatsapp:", "").strip()
        wa_number    = f"whatsapp:{plain_number}"
        try:
            rows = (lib._sb().table("wa_saves")
                    .select("title,url,status,created_at")
                    .in_("from_number", [from_number, plain_number, wa_number])
                    .like("url", "book:%")
                    .order("created_at", desc=True).limit(12).execute().data)
        except Exception:
            rows = []
        if not rows:
            user_token = _wa_user_token(from_number)
            resp.message(
                "📚 No books saved yet.\n\n"
                "• Send *book The Midnight Library* to add one\n"
                "• Or scan a barcode: miru.humanagency.co"
            )
        else:
            status_map = {"wishlist": "📌 want", "reading": "📖 reading", "read": "✅ read"}
            lines = [f"📚 Your books ({len(rows)}):"]
            for r in rows[:10]:
                title = (r.get("title") or r.get("url","")).replace("📚 ","")[:50]
                st = status_map.get(r.get("status",""), "")
                lines.append(f"\n{'📚' if not st else st.split()[0]} *{title}*" + (f"  _{st.split(None,1)[-1] if st else ''}_" if st and " " in st else ""))
            if len(rows) > 10:
                lines.append(f"\n…+{len(rows)-10} more. See all: miru.humanagency.co")
            resp.message("\n".join(lines))
        return str(resp)

    # ── BOOKMARKS AI SEARCH ──────────────────────────────────────────────────────
    _BM_PREFIXES = ("search bookmarks ", "find bookmark ", "find in bookmarks ", "bookmark search ", "search my bookmarks ", "find my bookmark ")
    _bm_prefix = next((p for p in _BM_PREFIXES if body_lower.startswith(p)), None)
    if _bm_prefix:
        query = body[len(_bm_prefix):].strip()
        if query:
            try:
                # Fetch user's bookmarks from Supabase
                plain_fn = from_number.replace("whatsapp:", "").strip()
                # Get Chrome bookmarks - try without filter first to see what columns exist
                try:
                    chrome_rows = lib._sb().table("bookmarks").select("*").limit(10).execute().data or []
                    twitter_rows = lib._sb().table("twitter_bookmarks").select("*").limit(10).execute().data or []
                    app.logger.warning(f"[bookmark] Sample bookmarks: {chrome_rows[:1] if chrome_rows else 'empty'}")
                except Exception as e:
                    app.logger.error(f"[bookmark] Query failed: {e}")
                    return _msg_send(resp, f"📚 Bookmarks error: {str(e)[:100]}")

                bookmarks = []
                for bm in chrome_rows:
                    bookmarks.append({"title": bm.get("title", ""), "url": bm.get("url", ""), "category": bm.get("category", ""), "type": "chrome"})
                for tw in twitter_rows:
                    bookmarks.append({"title": tw.get("text", "")[:100], "url": tw.get("url", ""), "category": tw.get("category", ""), "author": tw.get("author_name", ""), "type": "twitter"})

                if not bookmarks:
                    resp.message("📚 No bookmarks found. Save some bookmarks at miru.humanagency.co first!")
                    return str(resp)

                # Call AI search API
                ai_resp = requests.post(
                    "https://miru.humanagency.co/api/bookmarks/search-ai",
                    json={"query": query, "bookmarks": bookmarks},
                    timeout=8
                )
                if ai_resp.status_code != 200:
                    raise Exception("AI search failed")

                data = ai_resp.json()
                results = data.get("results", [])[:5]  # Top 5 for WhatsApp
                analysis = data.get("analysis", {})

                if not results:
                    resp.message(f"📚 No bookmarks match \"{query}\".\n\nTry different keywords or check the learning dashboard at miru.humanagency.co")
                    return str(resp)

                # Format results for WhatsApp
                lines = [f"📚 Bookmarks matching \"{query}\":"]
                if analysis.get("intents"):
                    lines.append(f"_Intent: {', '.join(analysis['intents'])}_")
                if analysis.get("entities", {}).get("locations"):
                    lines.append(f"_📍 {', '.join(analysis['entities']['locations'])}_")

                for i, r in enumerate(results[:4], 1):
                    score = int((r.get("_total_score", 0) or 0) * 100)
                    url = r.get("url", "")
                    if r.get("type") == "twitter":
                        author = r.get("author", "Unknown")
                        text = r.get("title", "")[:80]
                        lines.append(f"\n{i}. *{author}*\n   {text}\n   [{score}%]")
                        if url:
                            lines.append(f"   🔗 {url}")
                    else:
                        title = r.get("title", "Untitled")[:70]
                        lines.append(f"\n{i}. {title}\n   [{score}%]")
                        if url:
                            lines.append(f"   🔗 {url}")

                lines.append(f"\n_See full results with scores at:_ miru.humanagency.co")
                resp.message("\n".join(lines))
                return str(resp)

            except Exception as e:
                print(f"[bookmarks] error: {e}")
                resp.message(f"📚 Search error: {str(e)[:50]}. Try again or use miru.humanagency.co")
                return str(resp)

    # ── MENU LOOKUP — any phrasing with "menu" + venue name ──────────────────
    _MENU_RE = re.compile(
        r"^(?:"
        r"(?:what(?:'?s|is)?\s+)?(?:the\s+)?(?:is\s+)?(?:on\s+(?:the\s+)?)?menu\s+(?:at|for|of|in)\s+|"
        r"(?:show|get|find)\s+(?:me\s+)?(?:the\s+)?menu\s+(?:at|for|of|in)\s+|"
        r"what(?:'?s|is)?\s+(?:on\s+at|serving\s+at|cooking\s+at)\s+|"
        r"menu\s+(?:at|for|of|in|-)?\s*"
        r")",
        re.I
    )
    _menu_match = _MENU_RE.match(body.strip())
    # Also catch bare "menu <venue>" with no preposition
    _bare_menu = re.match(r'^menu\s+(\S.*)', body.strip(), re.I)
    if _menu_match or _bare_menu:
        if _menu_match:
            _menu_venue = body.strip()[_menu_match.end():].strip().rstrip("?").strip()
        else:
            _menu_venue = _bare_menu.group(1).strip().rstrip("?").strip()
        if _menu_venue:
            resp.message("🍽️ Looking up their menu…")
            resp.message(_wa_menu_lookup(_menu_venue, from_number))
            return str(resp)

    # ── PRICE CHECK / COMPARE — strip prefix so "price olive oil" works ──────
    _PRICE_PREFIX_RE = re.compile(
        r'^(?:price\s+|compare\s+prices?\s+|compare\s+|price\s+check\s+|check\s+price\s+(?:of\s+)?|how\s+much\s+is\s+)', re.I
    )
    _price_match = _PRICE_PREFIX_RE.match(body_lower.strip())
    if _price_match:
        product_q = body_lower[_price_match.end():].strip()
        if product_q:
            reply = whatsapp_product_format(product_q)
            resp.message(reply)
            return str(resp)

    # ── Natural-language school queries ──────────────────────────────────────
    _SCHOOL_NL_RE = re.compile(
        r"\b(?:school|class|teacher|term|half[\s-]?term|assembly|parents(?:'|\u2019)?\s*evening|"
        r'sports\s*day|nativity|play\s*rehearsal|inset\s*day|'
        r'what\s+time\s+does\s+(school|class)\s+(start|finish|end|open|close)|'
        r'when\s+does\s+school|school\s+times|school\s+hours|school\s+run|'
        r'school\s+event|school\s+news|school\s+week|what\'s\s+on\s+at\s+school)\b',
        re.I
    )
    if _SCHOOL_NL_RE.search(body) and from_number not in school_service._SETUP_STEPS:
        try:
            # Route natural language school queries to school_service
            # Normalise: if it doesn't start with "school", prepend it so handle_wa_school can route it
            _school_body = body if body_lower.startswith("school") else "school week " + body
            reply = school_service.handle_wa_school(from_number, _school_body)
        except Exception as _e:
            reply = ""
        if reply:
            resp.message(reply)
            return str(resp)

    # ── School comms ──────────────────────────────────────────────────────────
    if body_lower.startswith("school") or from_number in school_service._SETUP_STEPS:
        try:
            reply = school_service.handle_wa_school(from_number, body)
        except Exception as _e:
            print(f"[school] handle_wa_school error: {_e}")
            import traceback; traceback.print_exc()
            reply = f"Sorry, something went wrong with school comms: {_e}"
        if reply:
            resp.message(reply)
            return str(resp)

    postcode, fuel, radius, retailer = parse_sms(body)
    body_words = set(body.lower().split())

    # ── Places query ──────────────────────────────────────────────────────────
    if body_words & _PLACES_WORDS:
        pc_m = re.search(r'([A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2})', body.upper())
        if pc_m:
            places_q = pc_m.group(1).strip()
            # Keep anything that isn't the postcode or a stop word as a service filter
            service_filter = re.sub(
                r'[A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2}', '', body, flags=re.I
            )
            service_filter = re.sub(
                r'\b(?:places|services|local|near|nearby|around)\b', '', service_filter, flags=re.I
            ).strip()
        elif re.search(r'\bme\b|\bmy\s+area\b|\bmy\s+postcode\b', body_lower):
            # "coffee near me" or "GP near me" — try food handler first (uses home postcode)
            _food_r = _wa_food_find(body, from_number)
            if _food_r:
                resp.message(_food_r)
                return str(resp)
            # Not a food query — try home postcode for places
            _home_pc = _get_wa_home_postcode(from_number)
            if _home_pc:
                places_q = _home_pc
                service_filter = re.sub(
                    r'\b(?:places|services|local|near|nearby|around|me|my\s+area|my\s+postcode)\b', '', body, flags=re.I
                ).strip()
                reply = whatsapp_places_format(places_q, service_filter=service_filter)
                resp.message(reply)
                return str(resp)
            service_filter = re.sub(
                r'\b(?:places|services|local|near|nearby|around|me|my\s+area|my\s+postcode)\b', '', body, flags=re.I
            ).strip()
            label = service_filter if service_filter else "local services"
            resp.message(
                f"📍 To find {label} near you, reply with your postcode:\n\n"
                f"  *{label} KT15 3RL*\n\n"
                f"Or set your home postcode at miru.humanagency.co 🏠"
            )
            return str(resp)
        else:
            places_q = re.sub(
                r'\b(?:places|services|local|near|nearby|around)\b', '', body, flags=re.I
            ).strip()
            service_filter = ""
        if places_q:
            cache_key = f"places_wa:{places_q.lower()}:{service_filter.lower()}"
            cached = _WA_CACHE.get(cache_key)
            if cached and (time.time() - cached[0]) < _WA_CACHE_TTL:
                resp.message(cached[1])
                return str(resp)
            reply = whatsapp_places_format(places_q, service_filter=service_filter)
            _WA_CACHE[cache_key] = (time.time(), reply)
            resp.message(reply)
            return str(resp)
        else:
            resp.message("Please include a postcode or place name, e.g.:\nplaces KT1 2BA")
            return str(resp)

    # ── Councillor contact query ───────────────────────────────────────────────
    # ── MP lookup ─────────────────────────────────────────────────────────────
    _MP_NATURAL = re.compile(r'\b(who is my mp|my mp|contact mp|mp contact|who represents me|member of parliament)\b', re.I)
    if body_words & _MP_WORDS or _MP_NATURAL.search(body):
        pc_m = re.search(r'([A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2})', body.upper())
        mp_postcode = pc_m.group(1).replace(" ", "") if pc_m else (postcode or _get_wa_home_postcode(from_number) or "")
        if mp_postcode:
            cache_key = f"mp:{mp_postcode}"
            cached = _WA_CACHE.get(cache_key)
            if cached and (time.time() - cached[0]) < 3600:
                resp.message(cached[1])
                return str(resp)
            reply = _wa_mp_lookup(mp_postcode)
            _WA_CACHE[cache_key] = (time.time(), reply)
            resp.message(reply)
            return str(resp)
        else:
            resp.message("Include your postcode to find your MP, e.g.:\n*my mp KT16 0DA*")
            return str(resp)

    if body_words & _COUNCILLOR_WORDS or body.lower().startswith("councillor"):
        pc_m = re.search(r'([A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2})', body.upper())
        cllr_postcode = pc_m.group(1).replace(" ", "") if pc_m else postcode
        if cllr_postcode:
            cache_key = f"councillor:{cllr_postcode}"
            cached = _WA_CACHE.get(cache_key)
            if cached and (time.time() - cached[0]) < 3600:
                resp.message(cached[1])
                return str(resp)
            reply = _wa_councillor_lookup(cllr_postcode)
            _WA_CACHE[cache_key] = (time.time(), reply)
            resp.message(reply)
            return str(resp)
        else:
            resp.message("Include your postcode to find your councillor, e.g.:\ncouncillor KT16 0DA")
            return str(resp)

    # ── Election results query ─────────────────────────────────────────────────
    if body_words & _RESULTS_WORDS:
        pc_m = re.search(r'([A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2})', body.upper())
        res_postcode = pc_m.group(1).replace(" ", "") if pc_m else None
        if res_postcode:
            cache_key = f"results:{res_postcode}"
            cached = _WA_CACHE.get(cache_key)
            if cached and (time.time() - cached[0]) < 300:  # 5-min cache for results
                resp.message(cached[1])
                return str(resp)
            reply = whatsapp_results_format(res_postcode)
            _WA_CACHE[cache_key] = (time.time(), reply)
            resp.message(reply)
            return str(resp)
        else:
            resp.message("Please include your postcode, e.g.:\nVoting Results SW1A 1AA")
            return str(resp)

    # ── Elections query — election day passed, so always return results ────────
    if body_words & _ELECTION_WORDS:
        pc_m = re.search(r'([A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2})', body.upper())
        elec_postcode = pc_m.group(1).replace(" ", "") if pc_m else None
        if elec_postcode:
            cache_key = f"results:{elec_postcode}"
            cached = _WA_CACHE.get(cache_key)
            if cached and (time.time() - cached[0]) < 300:
                resp.message(cached[1])
                return str(resp)
            reply = whatsapp_results_format(elec_postcode)
            _WA_CACHE[cache_key] = (time.time(), reply)
            resp.message(reply)
            return str(resp)
        else:
            resp.message("Please include your postcode to get election results, e.g.:\nelection KT16 0DA")
            return str(resp)

    # ── Document / receipt / warranty / book-note search ─────────────────────
    _DOC_Q = re.compile(
        r'\b(find|search|look up|show me)\b.{0,30}\b(save|saves|doc|docs|document|receipt|receipts|library|note|notes)\b'
        r'|\b(when did i (buy|purchase)|did i buy|my receipt for|receipt for|how much (did i pay|was|is it)|what did i (buy|pay|spend))\b'
        r'|\b(is .{1,40} (under )?warranty|warranty for|check (my )?warranty|when does .{1,40} warranty expire)\b'
        r'|\bwhat (did|does|is in) (my|the) (document|doc|letter|contract|agreement|receipt|note|lease)\b',
        re.I,
    )
    if _DOC_Q.search(body):
        resp.message(_wa_doc_search(from_number, body))
        return str(resp)

    # ── Book reading note: "note for Atomic Habits: key insight text" ─────────
    _BOOK_NOTE_RE = re.compile(r'^note\s+for\s+(.+?):\s*(.+)', re.I | re.DOTALL)
    _bnm = _BOOK_NOTE_RE.match(body.strip())
    if _bnm:
        _book_title = _bnm.group(1).strip()[:100]
        _note_text  = _bnm.group(2).strip()[:600]
        try:
            lib._sb().table("wa_saves").insert({
                "from_number": from_number,
                "title":       f"📖 {_book_title}",
                "summary":     _note_text,
                "url":         f"book-note:{_book_title.lower().replace(' ','-')}",
                "status":      "pending",
            }).execute()
            resp.message(f"📖 Note saved for *{_book_title}*\n\n_{_note_text[:120]}{'…' if len(_note_text)>120 else ''}_")
        except Exception as _bne:
            resp.message(f"Sorry, couldn't save the note: {_bne}")
        return str(resp)

    # ── Fast save-filter matching (before Groq — catches "X saved last week" etc.) ──
    _SAVE_FILTER_WORDS = {
        "books": "books", "book": "books",
        "wine": "wine", "wines": "wine",
        "recipe": "recipes", "recipes": "recipes",
        "menu": "menus", "menus": "menus",
        "restaurant": "restaurants", "restaurants": "restaurants",
        "video": "videos", "videos": "videos",
        "product": "products", "products": "products",
        "saves": "all", "links": "all",
    }
    _TIMEFRAME_WORDS = {
        "today": "today", "yesterday": "yesterday",
        "last week": "last_week", "this week": "last_week",
        "last month": "last_month", "this month": "last_month",
    }
    # Trigger words that indicate "show me my saved items" context
    _SAVES_CONTEXT = re.compile(
        r'\b(saved|my saves?|show me|see my|list my|get my|find my|all my|i saved|i have saved)\b', re.I
    )
    _bl = body_lower.strip()
    _sf_filter, _sf_timeframe, _sf_author = None, "all", ""
    _by_m = re.search(r'\bby\s+([a-z ]{3,40}?)(?:\s+saved|\s+last|\s+this|\s+today|$)', _bl)
    if _by_m:
        _sf_author = _by_m.group(1).strip()
    for _fw, _fval in _SAVE_FILTER_WORDS.items():
        if re.search(r'\b' + re.escape(_fw) + r'\b', _bl):
            _sf_filter = _fval
            break
    if _sf_filter:
        # Only route here if there's a "saved/show me/my" indicator OR a timeframe word
        _has_timeframe = any(tw in _bl for tw in _TIMEFRAME_WORDS)
        _has_context   = bool(_SAVES_CONTEXT.search(_bl)) or bool(_sf_author)
        if _has_timeframe or _has_context:
            for _tw, _tval in _TIMEFRAME_WORDS.items():
                if _tw in _bl:
                    _sf_timeframe = _tval
                    break
            msg = _wa_search_saves(from_number, _sf_filter, _sf_timeframe, _sf_author)
            resp.message(msg)
            return str(resp)

    # ── "Heading to" → live drive time (before Groq — precise regex match) ────
    _heading_reply = _wa_heading_to(body, from_number)
    if _heading_reply:
        resp.message(_heading_reply)
        return str(resp)

    # ── Brand intel (before Groq — "brand X" / "intel X" / "about X") ──────────
    _brand_m = re.match(r'^(?:brand|intel|about)\s+(.{2,60})$', body.strip(), re.I)
    if _brand_m:
        resp.message(_wa_brand_card(_brand_m.group(1).strip()))
        return str(resp)

    # ── Price check (before Groq — "price X" / "compare X") ────────────────────
    _price_re = re.compile(
        r'^(?:price\s+|compare\s+prices?\s+|compare\s+|price\s+check\s+|check\s+price\s+(?:of\s+)?|how\s+much\s+is\s+)',
        re.I
    )
    if _price_re.match(body.strip()):
        product_q = _price_re.sub("", body.strip(), count=1).strip()
        if product_q:
            resp.message(whatsapp_product_format(product_q))
            return str(resp)

    # ── WFH shortcut — before LLM classifier ────────────────────────────────
    if re.search(r'\bwfh\b|working from home|work from home|wfh today|at home today', body_lower):
        _intent = {"intent": "wfh"}
    else:
        _intent = None

    # ── Natural language fallback — Groq intent classification ───────────────
    if not _intent:
        _intent = _wa_classify_intent(body)
    if _intent:
        _itype = _intent.get("intent")
        if _itype == "book_lookup":
            bk_query = _intent.get("query", "").strip() or body.strip()
            _isbn_raw = re.sub(r"[\s\-]", "", bk_query)
            if re.match(r"^(978|979)\d{10}$", _isbn_raw) or re.match(r"^\d{10}$", _isbn_raw):
                bk_info = _lookup_book_by_isbn(_isbn_raw)
                bk_isbn = _isbn_raw
            else:
                bk_info = _lookup_book_by_title(bk_query)
                bk_isbn = bk_info.get("isbn", "") if bk_info else ""
            if not bk_info or not bk_info.get("title"):
                resp.message(f"📚 Couldn't find *{bk_query}* — try: *book the midnight library* or the ISBN number.")
                return str(resp)
            try:
                plain_number = from_number.replace("whatsapp:", "").strip()
                existing = (lib._sb().table("wa_saves").select("id")
                            .in_("from_number", [from_number, plain_number])
                            .eq("url", f"book:{bk_isbn}").limit(1).execute().data)
                already = bool(existing)
                if not already:
                    lib._sb().table("wa_saves").insert({
                        "from_number": plain_number, "url": f"book:{bk_isbn}",
                        "title": bk_info["title"], "summary": json.dumps(bk_info), "status": "wishlist",
                    }).execute()
                    try: lib.books_upsert(plain_number, {**bk_info, "isbn": bk_isbn, "source": "whatsapp_text"})
                    except Exception: pass
            except Exception: already = False
            user_token = _wa_user_token(from_number)
            msg = f"📚 *{bk_info['title']}*"
            if bk_info.get("author"): msg += f"\nby {bk_info['author']}"
            cr = bk_info.get("communityRating")
            if cr and cr.get("avg"):
                msg += f"\n{'⭐' * round(cr['avg'])} {cr['avg']}/5"
                if cr.get("count"): msg += f" ({cr['count']:,} ratings)"
            if bk_info.get("description"): msg += f"\n\n_{bk_info['description'][:220].strip()}…_"
            msg += f"\n\n📚 {'Already in' if already else 'Saved to'} My Books: miru.humanagency.co/?screen=scan&token={user_token}"
            resp.message(msg)
            return str(resp)
        elif _itype == "drink_info":
            _drink = (_intent.get("drink") or body).strip()
            resp.message(_wa_drink_info_card(_drink))
            return str(resp)
        elif _itype == "recipe":
            _dish = (_intent.get("dish") or body).strip()
            resp.message(_wa_recipe_card(_dish, from_number))
            return str(resp)
        elif _itype == "worth_it":
            body = "WORTH IT"
            cmd_up = "WORTH IT"
            body_lower = "worth it"
        elif _itype == "shopping_list":
            body = "SHOPPING LIST"
            cmd_up = "SHOPPING LIST"
            body_lower = "shopping list"
        elif _itype == "search_saves":
            msg = _wa_search_saves(
                from_number,
                filter_type=_intent.get("filter", "all"),
                timeframe=_intent.get("timeframe", "all"),
                author=_intent.get("author") or "",
            )
            resp.message(msg)
            return str(resp)
        elif _itype == "my_saves":
            body = "LIST"
            cmd_up = "LIST"
            body_lower = "list"
        elif _itype == "my_link":
            body = "MY LINK"
            cmd_up = "MY LINK"
            body_lower = "my link"
        elif _itype == "wfh":
            import datetime as _wdt
            _wfh_date = _wdt.date.today().isoformat()
            _fn_plain = from_number.replace("whatsapp:", "").strip()
            _fn_wa    = f"whatsapp:{_fn_plain}"
            try:
                sb = lib._sb()
                rows = sb.table("ma_details").select("id,data") \
                    .in_("device_id", [_fn_plain, _fn_wa]).eq("type", "v2_prefs").limit(1).execute().data or []
                _prev = (rows[0].get("data") or {}) if rows else {}
                _merged = {**_prev, "wfh_mode": "wfh", "wfh_date": _wfh_date}
                if rows:
                    sb.table("ma_details").update({"data": _merged}).eq("id", rows[0]["id"]).execute()
                else:
                    sb.table("ma_details").insert({"device_id": from_number, "type": "v2_prefs", "label": "home_brief", "data": _merged}).execute()
            except Exception as _we:
                print(f"[wfh] pref save error: {_we}", flush=True)
            resp.message("🏠 Got it — WFH today. No commute content in your brief.")
            return str(resp)
        elif _itype == "train":
            _from_stn = (_intent.get("from") or "").strip()
            _to_stn   = (_intent.get("to") or "").strip()
            # Fallback to saved preferences if not specified
            if not _from_stn:
                _from_stn = (prefs.get("train_from") or "").strip()
            if not _to_stn:
                _to_stn = (prefs.get("train_to") or "").strip()
            if _from_stn:
                _train_reply = _wa_train_format(_from_stn, _to_stn)
                if _train_reply:
                    resp.message(_train_reply)
                    return str(resp)
                resp.message(f"🚂 Couldn't find '{_from_stn}' — try: *train waterloo to lewisham* or set your route in Miru preferences")
                return str(resp)
            else:
                resp.message("🚂 Which stations? Try: *train waterloo to lewisham* or set your default route in Miru.")
                return str(resp)
        elif _itype == "tube":
            _from_stn = (_intent.get("from") or "").strip()
            _to_stn   = (_intent.get("to") or "").strip()
            _query    = (_intent.get("query") or "status").strip()
            if _from_stn and _to_stn:
                resp.message(get_tube_journey(_from_stn, _to_stn))
            else:
                resp.message(handle_tube_command(f"tube {_query}", from_number))
            return str(resp)
        elif _itype == "food":
            _ftype    = (_intent.get("food_type") or "coffee").strip()
            _fpc      = (_intent.get("postcode") or "").strip()
            _fcheap   = _intent.get("cheap", False)
            _synthetic = f"{'cheap ' if _fcheap else ''}{_ftype} {_fpc}".strip()
            _food_reply = _wa_food_find(_synthetic, from_number)
            if _food_reply:
                resp.message(_food_reply)
                return str(resp)
        elif _itype == "menu":
            _venue_name = (_intent.get("name") or "").strip()
            if _venue_name:
                resp.message("🍽️ Looking up their menu…")
                _menu_reply = _wa_menu_lookup(_venue_name, from_number)
                resp.message(_menu_reply)
            else:
                resp.message("Which restaurant? Try: *menu Belvedere Arms* or *what's on at Nando's*")
            return str(resp)

    # ── Re-check commands if intent classifier redirected ─────────────────────
    if cmd_up in ("WORTH IT", "WORTH IT?", "REVIEWS", "BOOK REVIEW", "THOUGHTS"):
        plain_number = from_number.replace("whatsapp:", "").strip()
        wa_number    = from_number if from_number.startswith("whatsapp:") else f"whatsapp:{from_number}"
        try:
            rows = (lib._sb().table("wa_saves").select("id,title,url,summary")
                    .in_("from_number", [from_number, plain_number, wa_number])
                    .like("url", "book:%")
                    .order("created_at", desc=True).limit(1).execute().data)
        except Exception: rows = []
        if not rows:
            resp.message("📚 No books saved yet — send *book <title>* to add one, then ask again.")
            return str(resp)
        row = rows[0]
        bk = {}
        try: bk = json.loads(row.get("summary") or "{}")
        except Exception: pass
        book_label  = bk.get("title") or row.get("title") or "your book"
        book_rating = (bk.get("communityRating") or {}).get("avg")
        description = bk.get("description", "")
        genre       = bk.get("subjects", "")
        author      = bk.get("author", "")
        context = f"Book: {book_label}"
        if author:      context += f"\nAuthor: {author}"
        if genre:       context += f"\nGenre/subjects: {genre}"
        if book_rating: context += f"\nGoogle Books rating: {book_rating}/5"
        if description: context += f"\nDescription: {description[:400]}"
        try:
            from groq import Groq as _Groq2
            verdict = _Groq2(api_key=os.environ.get("GROQ_API_KEY","")).chat.completions.create(
                model="llama3-8b-8192", temperature=0.4,
                system=(
                    "You are a concise book critic. Given book metadata, "
                    "write exactly 4 lines:\n"
                    "Line 1: ✅ Fans say: [what the description/genre suggests readers will love — max 15 words]\n"
                    "Line 2: ⚠️ Critics say: [likely criticism based on genre/style — max 15 words]\n"
                    "Line 3: 🎯 Best for: [who this book suits — max 10 words]\n"
                    "Line 4: 📖 Verdict: Worth it / Skip it / Depends on taste — one sentence reason\n"
                    "If you don't have enough information, be honest and say so on line 1. No other text."
                ),
                messages=[{"role": "user", "content": context}],
                max_tokens=220,
            ).choices[0].message.content.strip()
        except Exception: verdict = ""
        if not verdict:
            resp.message(f"📚 Couldn't generate a review for {book_label} right now.")
            return str(resp)
        rating_line = f"\n⭐ {book_rating}/5 on Google Books" if book_rating else ""
        resp.message(f"📚 {book_label}{rating_line}\n\n{verdict}")
        return str(resp)

    if cmd_up in ("LIST",):
        try:
            plain_number = from_number.replace("whatsapp:", "").strip()
            wa_number    = from_number if from_number.startswith("whatsapp:") else f"whatsapp:{from_number}"
            rows = (lib._sb().table("wa_saves").select("id,title,url,status")
                    .in_("from_number", [from_number, plain_number, wa_number])
                    .in_("status", ["pending", "remind"]).order("created_at", desc=True).limit(9).execute().data)
            if not rows:
                resp.message("📂 No pending saves. Send a link to save something!")
                return str(resp)
            lines = [f"{i+1}. {r.get('title') or r.get('url','?')[:60]}" for i, r in enumerate(rows)]
            resp.message("📂 Your saves:\n" + "\n".join(lines) + "\n\nReply *1 READ*, *2 SKIP*, etc.")
            return str(resp)
        except Exception: pass

    if body_lower in ("my link", "link", "my saves link", "get link", "access", "my access"):
        user_token = _wa_user_token(from_number)
        resp.message(f"🔗 Your personal Miru link:\nmiru.humanagency.co/?screen=saves&token={user_token}")
        return str(resp)

    # ── Train departures query ────────────────────────────────────────────────
    _TRAIN_RE = re.compile(
        r'\b(?:next\s+)?trains?\s+(?:from\s+)?(.+?)(?:\s+to\s+(.+))?$'
        r'|\bnext\s+train\s+(.+?)(?:\s+to\s+(.+))?$',
        re.I
    )
    _tm = _TRAIN_RE.match(body_lower.strip())
    if _tm or re.match(r'^(?:next\s+)?train\b', body_lower.strip()):
        # Parse from/to station names
        if _tm:
            from_stn = (_tm.group(1) or _tm.group(3) or "").strip().lower()
            to_stn   = (_tm.group(2) or _tm.group(4) or "").strip().lower()
        else:
            from_stn = re.sub(r'^(?:next\s+)?train\s+(?:from\s+)?', '', body_lower.strip()).strip()
            to_stn = ""
        # "next train to Waterloo" → from_stn="to waterloo"; fix: strip leading "to "
        if not to_stn and from_stn.startswith("to "):
            to_stn, from_stn = from_stn[3:].strip(), ""
        # Strip "to X" from from_stn if not already split
        if not to_stn and " to " in from_stn:
            parts = from_stn.split(" to ", 1)
            from_stn, to_stn = parts[0].strip(), parts[1].strip()
        if from_stn or to_stn:
            wa_train_reply = _wa_train_format(from_stn, to_stn)
            if wa_train_reply:
                resp.message(wa_train_reply)
                return str(resp)

    # ── Tube query ───────────────────────────────────────────────────────────
    if body_lower.strip().startswith("tube"):
        resp.message(handle_tube_command(body, from_number))
        return str(resp)

    # ── Food & drink discovery ───────────────────────────────────────────────
    _food_reply = _wa_food_find(body, from_number)
    if _food_reply:
        resp.message(_food_reply)
        return str(resp)

    # ── General question → Miru AI chat with conversation memory ─────────────────
    _QUESTION_OPENERS = {"what","why","how","when","where","who","which","tell","explain",
                         "is","are","do","does","will","would","could","should","can"}
    _bl_words_q = body_lower.split()
    # Catch remaining context-sharing statements: "I'm at X", "Just got to X" etc
    _STATEMENT_OPENERS = {"i'm","im","i've","i've","i am","i have","just","we're","we are"}
    _looks_like_statement = (
        len(_bl_words_q) >= 3
        and _bl_words_q[0] in _STATEMENT_OPENERS
        and not re.search(r'\b[A-Z]{1,2}\d{1,2}\s*\d[A-Z]{2}\b', body.upper())
    )
    _looks_like_question = (
        "?" in body and len(_bl_words_q) >= 3
    ) or (
        _bl_words_q and _bl_words_q[0] in _QUESTION_OPENERS and len(_bl_words_q) >= 4
        and not re.search(r'\b[A-Z]{1,2}\d{1,2}\s*\d[A-Z]{2}\b', body.upper())  # no postcode
    )
    if _looks_like_question or _looks_like_statement:
        _chat_reply = _wa_general_chat(from_number, body, _wa_thread)
        resp.message(_chat_reply)
        return str(resp)

    # ── Guard: conversational replies must not fall through to product search ────
    _CONVERSATIONAL = frozenset({
        "already there","its there","already set","already done","set already","its already there",
        "ok","okay","k","ok thanks","ok cool","ok great","thanks","thank you","ty","cheers","ta",
        "got it","cool","great","good","fine","alright","sure","right","noted","sorted","done",
        "yes","no","nope","yep","yeah","nah","correct","exactly","perfect",
        "hmm","hm","oh","ah","wait","really","seriously","come on","lol","haha",
        "already","never mind","nevermind","forget it","ignore that",
    })
    _bl = body_lower.strip()
    if _bl in _CONVERSATIONAL or (
            len(_bl.split()) <= 4 and not any(c.isdigit() for c in _bl) and
            _bl.split()[0] in {"already","ok","okay","yes","no","yeah","nope","thanks","cool",
                                "done","right","hmm","oh","sure","got","alright","wait","never",
                                "sorted","cheers","fine","great","noted","nah","correct","lol"}):
        _pending_check = _get_wa_pending_intent(from_number)
        if _pending_check:
            # They said something conversational while we're waiting for their postcode
            _clear_wa_pending_intent(from_number)
        resp.message(_CLARIFY_MSG)
        return str(resp)

    # ── "fuel near [me]" / "petrol near me" — use saved home postcode ──────────
    if re.match(r'^(?:fuel|petrol|diesel)\s+near(?:\s+me)?\s*$', body_lower):
        _home_pc2 = _get_wa_home_postcode(from_number)
        if _home_pc2:
            postcode = _home_pc2.replace(" ", "")
        else:
            resp.message("Just send your postcode to find fuel, e.g. *KT15 petrol*")
            return str(resp)

    # ── Drink info — "what's in a Negroni", "what is a mojito" ──────────────────
    _COCKTAIL_NAMES = {"negroni","martini","mojito","margarita","aperol","spritz","daiquiri",
                       "cosmopolitan","old fashioned","boulevardier","manhattan","gimlet","paloma",
                       "bellini","mimosa","pina colada","pisco sour","espresso martini",
                       "white russian","black russian","long island","pornstar martini","french 75",
                       "whisky sour","whiskey sour","bramble","sidecar","aviation","aperol spritz"}
    _di_m = re.search(r"what(?:'s|\s+is)\s+(?:in\s+)?(?:a\s+|an\s+)?([a-z\s]+?)(?:\?|$)", body_lower)
    if _di_m:
        _di_name = _di_m.group(1).strip()
        if any(c in body_lower for c in _COCKTAIL_NAMES):
            resp.message(_wa_drink_info_card(_di_name))
            return str(resp)

    # ── Recipe / cocktail recipe — intercept before product search ───────────────
    if re.search(r'\brecipe\b|\bhow\s+to\s+make\b|\bhow\s+do\s+i\s+make\b|\bingredients\s+for\b', body_lower):
        _dish = re.sub(r'\s*\brecipe\b.*', '', body_lower, flags=re.I).strip()
        _dish = re.sub(r'^(how\s+to\s+make|how\s+do\s+i\s+make|ingredients\s+for)\s+', '', _dish, flags=re.I).strip()
        if not _dish:
            _dish = body_lower.replace("recipe", "").strip()
        if _dish:
            resp.message(_wa_recipe_card(_dish, from_number))
            return str(resp)

    # Decide: fuel query or product query
    # Product query if: no postcode at all, OR postcode present but there's
    # substantial non-fuel text alongside it
    is_product = False
    product_name = None
    if not postcode:
        # No postcode found — treat whole message as product
        is_product = True
        product_name = body
    else:
        # Postcode found — check how much text remains after removing postcode + fuel words
        remaining = re.sub(r'[A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2}', '', body.upper()).strip()
        extra_words = [w for w in remaining.split() if w.lower() not in _FUEL_WORDS and not w.isdigit()]
        if extra_words:
            is_product = True
            product_name, _ = _split_product_postcode(body)

    if is_product and product_name and len(product_name.strip()) > 1:
        # Don't treat question/conversational messages as product queries — redirect to HELP
        _pn_words = product_name.strip().split()
        _question_starters = {"what","why","how","when","who","can","could","would","should",
                               "is","are","do","does","help","please","show","tell","get","give"}
        if _pn_words and (_pn_words[0].lower() in _question_starters or "?" in product_name):
            resp.message(_CLARIFY_MSG)
            return str(resp)
        # Don't treat venue/place names as products — they have no SKU
        _PLACE_SUFFIXES = {
            "club","fc","cricket","golf","tennis","rugby","leisure","centre","center",
            "park","ground","arena","stadium","theatre","theater","church","school",
            "college","university","hospital","hotel","pub","inn","manor","hall",
            "farm","estate","court","place","road","street","lane","avenue","drive",
        }
        _pn_lower_words = {w.lower() for w in _pn_words}
        if _pn_lower_words & _PLACE_SUFFIXES or len(_pn_words) >= 4:
            resp.message(_CLARIFY_MSG)
            return str(resp)
        _, loc_postcode = _split_product_postcode(body)
        cache_key = f"product:{product_name.lower().strip()}:{loc_postcode or ''}"
        cached = _WA_CACHE.get(cache_key)
        if cached and (time.time() - cached[0]) < _WA_CACHE_TTL:
            resp.message(cached[1])
            return str(resp)
        reply = whatsapp_product_format(product_name.strip(), loc_postcode)
        _WA_CACHE[cache_key] = (time.time(), reply)
        resp.message(reply)
        return str(resp)

    # Fuel query
    if not postcode:
        resp.message(_CLARIFY_MSG)
        return str(resp)

    cache_key = f"fuel:{postcode}:{fuel}:{radius}:{retailer or ''}"
    cached = _WA_CACHE.get(cache_key)
    if cached and (time.time() - cached[0]) < _WA_CACHE_TTL:
        print(f"WhatsApp cache hit for {cache_key}")
        resp.message(cached[1])
        return str(resp)

    reply = whatsapp_search_and_format(postcode, fuel, radius, retailer)
    _WA_CACHE[cache_key] = (time.time(), reply)
    resp.message(reply)
    return str(resp)


@app.route("/debug/postcode/<postcode>")
def debug_postcode(postcode):
    import requests as req
    results = {}
    latlon = postcode_to_latlon(postcode)
    results["latlon"] = latlon
    if not latlon:
        return jsonify(results)
    lat, lon = latlon

    # Raw Land Registry response
    pc = postcode.strip().replace(" ", "%20")
    lr_url = (f"https://landregistry.data.gov.uk/data/ppi/transaction-record.json"
              f"?propertyAddress.postcode={pc}&_pageSize=5&_sort=-transactionDate")
    try:
        r = req.get(lr_url, timeout=8, headers={"User-Agent": "Mozilla/5.0"})
        results["lr_status"] = r.status_code
        results["lr_raw"] = r.text[:500]
    except Exception as e:
        results["lr_error"] = str(e)

    # Raw Overpass response
    radius_m = 5000
    query = f'[out:json][timeout:8];(node["amenity"="pub"](around:{radius_m},{lat},{lon}););out body 3;'
    try:
        r2 = req.post("https://overpass-api.de/api/interpreter",
                      data=query, timeout=9,
                      headers={"User-Agent": "Mozilla/5.0"})
        results["osm_status"] = r2.status_code
        results["osm_raw"] = r2.text[:300]
    except Exception as e:
        results["osm_error"] = str(e)

    return jsonify(results)


