@app.route("/api/school/week-ahead")
def api_school_week_ahead():
    """Timeline of everything happening this week for the user."""
    import datetime as _dt
    wa = request.args.get("wa", "").strip()
    token = request.args.get("token", "").strip()

    if not wa:
        wa = (request.cookies.get("miru_saves_phone") or "").strip()
    if not wa:
        return jsonify({"error": "wa required"}), 400

    from_number = _v2_resolve(wa)
    now = _dt.datetime.now(_zi.ZoneInfo("Europe/London"))
    today = now.date()
    week_start = today
    week_end = today + _dt.timedelta(days=6)

    try:
        events = []

        # === SCHOOL EVENTS ONLY ===
        sb = lib._sb()
        school_rows = sb.table("school_events").select("*") \
            .eq("from_number", from_number) \
            .gte("event_date", today.isoformat()) \
            .lte("event_date", week_end.isoformat()) \
            .order("event_date", desc=False).execute().data or []

        for ev in school_rows:
            date_str = ev.get("event_date", "")
            if date_str:
                dt = _dt.datetime.fromisoformat(date_str)
                events.append({
                    "type": "school",
                    "date": date_str,
                    "time": dt.strftime("%H:%M") if "T" in date_str else None,
                    "title": ev.get("event_title", "School Event"),
                    "child": ev.get("child_name", ""),
                    "emoji": "🏫",
                    "sort_key": (dt.date(), dt.time() if "T" in date_str else _dt.time.max)
                })

        # Sort by date/time
        events.sort(key=lambda e: e["sort_key"])

        # Group by day
        by_day = {}
        for ev in events:
            date = ev["date"][:10]  # YYYY-MM-DD
            if date not in by_day:
                by_day[date] = []
            by_day[date].append(ev)

        return jsonify({
            "success": True,
            "week": {
                "start": week_start.isoformat(),
                "end": week_end.isoformat(),
                "today": today.isoformat(),
            },
            "by_day": by_day,
            "events_count": len(events),
        })

    except Exception as e:
        print(f"[week-ahead] error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/home/week-summary")
def api_home_week_summary():
    """Weekly summary: spend, saves, patterns, activities."""
    import datetime as _dt
    wa = request.args.get("wa", "").strip()
    token = request.args.get("token", "").strip()

    if not wa:
        wa = (request.cookies.get("miru_saves_phone") or "").strip()
    if not wa:
        return jsonify({"error": "wa required"}), 400

    from_number = _v2_resolve(wa)
    now = _dt.datetime.now(_zi.ZoneInfo("Europe/London"))
    today = now.date()
    week_start = today - _dt.timedelta(days=today.weekday())  # Monday
    week_end = week_start + _dt.timedelta(days=6)  # Sunday
    last_week_start = week_start - _dt.timedelta(days=7)
    last_week_end = week_start - _dt.timedelta(days=1)

    try:
        sb = lib._sb()

        # === THIS WEEK ===
        this_week = {
            "period": f"{week_start.strftime('%b %d')} — {week_end.strftime('%b %d')}",
            "spend": 0,
            "saves": 0,
            "activities": [],
        }

        # Spend this week
        spend_rows = sb.table("receipts").select("total") \
            .eq("phone", from_number.replace("whatsapp:", "")) \
            .gte("shop_date", week_start.isoformat()) \
            .lte("shop_date", week_end.isoformat()).execute().data or []
        this_week["spend"] = sum(float(r.get("total", 0) or 0) for r in spend_rows)

        # Saves this week
        saves_rows = sb.table("saves").select("id") \
            .eq("phone", from_number.replace("whatsapp:", "")) \
            .gte("created_at", week_start.isoformat()) \
            .lte("created_at", week_end.isoformat()).execute().data or []
        this_week["saves"] = len(saves_rows)

        # Activities this week (recurring activities)
        recurring = sb.table("recurring_activities").select("activity") \
            .eq("from_number", from_number) \
            .gte("last_done", week_start.isoformat()).execute().data or []
        this_week["activities"] = [r.get("activity", "") for r in recurring if r.get("activity")][:5]

        # === LAST WEEK ===
        last_week = {
            "period": f"{last_week_start.strftime('%b %d')} — {last_week_end.strftime('%b %d')}",
            "spend": 0,
            "saves": 0,
            "top_places": [],
        }

        # Spend last week
        spend_rows = sb.table("receipts").select("total,merchant") \
            .eq("phone", from_number.replace("whatsapp:", "")) \
            .gte("shop_date", last_week_start.isoformat()) \
            .lte("shop_date", last_week_end.isoformat()).execute().data or []
        last_week["spend"] = sum(float(r.get("total", 0) or 0) for r in spend_rows)

        # Top places last week
        from collections import Counter
        merchants = [r.get("merchant", "") for r in spend_rows if r.get("merchant")]
        top_places = Counter(merchants).most_common(3)
        last_week["top_places"] = [{"name": m[0], "visits": m[1]} for m in top_places]

        # Saves last week
        saves_rows = sb.table("saves").select("id") \
            .eq("phone", from_number.replace("whatsapp:", "")) \
            .gte("created_at", last_week_start.isoformat()) \
            .lte("created_at", last_week_end.isoformat()).execute().data or []
        last_week["saves"] = len(saves_rows)

        # === TREND ===
        week_over_week = "up" if this_week["spend"] > last_week["spend"] else "down" if this_week["spend"] < last_week["spend"] else "flat"
        spend_change = abs(this_week["spend"] - last_week["spend"])
        spend_pct = round((spend_change / last_week["spend"] * 100) if last_week["spend"] > 0 else 0)

        # === CHECK IF SCHOOLS SET UP ===
        school_profiles = sb.table("school_profiles").select("id") \
            .eq("from_number", from_number).execute().data or []
        has_schools = len(school_profiles) > 0

        return jsonify({
            "success": True,
            "this_week": this_week,
            "last_week": last_week,
            "trend": {
                "direction": week_over_week,
                "amount": spend_change,
                "percent": spend_pct,
            },
            "has_schools": has_schools,
        })

    except Exception as e:
        print(f"[week-summary] error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/school/diag")
def school_diag():
    """Admin diagnostic: show profile/token/event state without sending anything."""
    token = request.args.get("token", "")
    if token != os.environ.get("DIGEST_TOKEN", ""):
        return jsonify({"error": "Unauthorized"}), 401
    try:
        profiles = lib._sb().table("school_profiles") \
            .select("id,from_number,child_name,school_name,sender_emails,gmail_refresh_token,active") \
            .execute().data or []
        # Check token validity without doing a full poll
        out = []
        for p in profiles:
            rtok = p.pop("gmail_refresh_token", None)
            token_status = "none"
            if rtok:
                try:
                    import requests as _rq
                    tr = _rq.post("https://oauth2.googleapis.com/token", data={
                        "client_id":     os.environ.get("GMAIL_WEB_CLIENT_ID") or os.environ.get("GMAIL_CLIENT_ID",""),
                        "client_secret": os.environ.get("GMAIL_WEB_CLIENT_SECRET") or os.environ.get("GMAIL_CLIENT_SECRET",""),
                        "refresh_token": rtok,
                        "grant_type":    "refresh_token",
                    }, timeout=8)
                    token_status = "valid" if "access_token" in tr.json() else f"error:{tr.json().get('error','?')}"
                except Exception as _te:
                    token_status = f"exception:{_te}"
            elif os.environ.get("GMAIL_REFRESH_TOKEN"):
                token_status = "env_var_fallback"
            recent = lib._sb().table("school_events").select("id,created_at,event_title") \
                .eq("profile_id", p["id"]).order("created_at", desc=True).limit(3).execute().data or []
            out.append({**p, "token_status": token_status,
                        "recent_events": [{"title": e["event_title"], "at": e["created_at"]} for e in recent]})
        env_token = bool(os.environ.get("GMAIL_REFRESH_TOKEN"))
        return jsonify({"profiles": out, "env_gmail_token": env_token,
                        "web_client_id": bool(os.environ.get("GMAIL_WEB_CLIENT_ID"))})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/school/poll")
def school_poll():
    """Poll Gmail for new school emails and store events.
    Call every 6h via cron-job.org: GET /api/school/poll?token=YOUR_DIGEST_TOKEN
    """
    token = request.args.get("token", "")
    if not token or token != os.environ.get("DIGEST_TOKEN", ""):
        return jsonify({"error": "Unauthorized"}), 401
    days_back = int(request.args.get("days_back", 14))
    force     = request.args.get("force", "").lower() in ("1", "true", "yes")
    import threading
    threading.Thread(
        target=school_service.poll_all_profiles,
        kwargs={"days_back": days_back, "force": force, "on_error": _school_gmail_token_alert},
        daemon=True,
    ).start()
    return jsonify({"status": "started", "days_back": days_back, "force": force})


