@app.route("/api/receipt/followup")
def receipt_followup():
    """Ambient agent: send a proactive WhatsApp ~15 min after a receipt scan.
    Call every 5 min via cron-job.org: GET /api/receipt/followup?token=YOUR_DIGEST_TOKEN
    """
    token = request.args.get("token", "")
    if not token or token != os.environ.get("DIGEST_TOKEN", ""):
        return jsonify({"error": "Unauthorized"}), 401

    import datetime as _fdt
    cutoff_early = (_fdt.datetime.utcnow() - _fdt.timedelta(minutes=15)).isoformat()
    cutoff_late  = (_fdt.datetime.utcnow() - _fdt.timedelta(hours=2)).isoformat()

    try:
        pending = (lib._sb().table("wa_saves")
                   .select("id,from_number,summary,category,created_at")
                   .eq("status", "followup_pending")
                   .lte("created_at", cutoff_early + "Z")
                   .gte("created_at", cutoff_late + "Z")
                   .order("created_at")
                   .limit(10)
                   .execute().data or [])
    except Exception as e:
        return jsonify({"error": str(e)}), 500

    sent, skipped = 0, 0
    for row in pending:
        phone     = row.get("from_number", "")
        merchant  = row.get("summary", "")
        category  = row.get("category", "")
        row_id    = row["id"]

        if not phone or not merchant:
            skipped += 1
            _mark_followup_done(row_id)
            continue

        try:
            plain = phone.replace("whatsapp:", "").strip()

            # This visit's total
            prior = (lib._sb().table("receipts")
                     .select("shop_date,total,items")
                     .eq("phone", plain)
                     .ilike("merchant", f"%{merchant.split()[0]}%")
                     .order("shop_date", desc=True)
                     .limit(5).execute().data or [])
            visit_count = len(prior)
            first_visit = visit_count <= 1
            this_total  = prior[0].get("total") if prior else None

            # Pull actual item names from the most recent receipt
            import json as _fj
            _raw_items = []
            try:
                _raw_items = _fj.loads(prior[0].get("items") or "[]") if prior else []
            except Exception:
                pass
            item_names = [i.get("name","").strip() for i in _raw_items if i.get("name","").strip()]

            # Skip petrol stations and pharmacies — no warm comment to make
            _skip_cats = {"Fuel", "Pharmacy", "Health"}
            if category in _skip_cats:
                skipped += 1
                _mark_followup_done(row_id)
                continue

            # Infer experience type from merchant name for the warm opener
            _name_lower = merchant.lower()
            if any(w in _name_lower for w in ("coffee", "costa", "starbucks", "cafe", "caffe", "brew")):
                experience = "coffee"
            elif any(w in _name_lower for w in ("chai", "vadapav", "vada", "krishna", "rasoi", "curry",
                                                  "indian", "tandoor", "spice", "masala", "biryani")):
                experience = "Indian food or chai"
            elif any(w in _name_lower for w in ("pizza", "peri", "burger", "chicken", "kfc", "mcdonald",
                                                  "subway", "kebab", "wrap", "nando")):
                experience = "fast food or takeaway"
            elif any(w in _name_lower for w in ("pub", "bar", "inn", "arms", "tavern", "brewery")):
                experience = "pub visit"
            elif any(w in _name_lower for w in ("tesco", "waitrose", "sainsbury", "asda", "aldi",
                                                  "lidl", "morrisons", "marks", "coop", "co-op")):
                experience = "supermarket shop"
            elif category == "Dining":
                experience = "meal out"
            else:
                experience = "visit"

            total_str = f"£{this_total:.2f}" if this_total else None
            visit_note = "first time" if first_visit else f"{visit_count} visits now"

            items_str = ", ".join(item_names[:4]) if item_names else ""

            ctx_parts = [
                f"The user just visited '{merchant}'.",
                f"They ordered: {items_str}." if items_str else f"It was a {experience}.",
                f"They spent {total_str} there." if total_str else "",
                f"This is their {visit_note} to this place.",
                "Write ONE short WhatsApp message from their personal assistant Miru.",
                "Reference a specific dish or item by name if available — not a generic category like 'curry' or 'Indian food'.",
                f"Example: 'Hope the Chicken Chettinadu was good — you spent {total_str} at {merchant}'." if items_str and total_str else "",
                "Lead with the food/drink/experience, end with the spend.",
                "Tone: warm, human, not try-hard. Max 20 words. No exclamation marks. One emoji max.",
                "Do not ask a question. Just notice and comment.",
            ]

            groq_r = requests.post(
                "https://api.groq.com/openai/v1/chat/completions",
                headers={"Authorization": f"Bearer {os.environ.get('GROQ_API_KEY','')}",
                         "Content-Type": "application/json"},
                json={"model": "llama-3.1-8b-instant", "max_tokens": 60, "temperature": 0.7,
                      "messages": [{"role": "user", "content": " ".join(ctx_parts)}]},
                timeout=10,
            )
            nudge = groq_r.json()["choices"][0]["message"]["content"].strip().strip('"')

            wa_to = f"whatsapp:{plain}" if not plain.startswith("whatsapp:") else plain
            _wa_send_proactive(wa_to, nudge)
            sent += 1
        except Exception as ex:
            print(f"[receipt_followup] error for {phone}: {ex}")
            skipped += 1

        _mark_followup_done(row_id)

    return jsonify({"sent": sent, "skipped": skipped})


def _mark_followup_done(row_id):
    try:
        lib._sb().table("wa_saves").update({"status": "followup_sent"}).eq("id", row_id).execute()
    except Exception:
        pass


_school_token_alert_sent: dict = {}  # from_number → last alert timestamp

def _school_gmail_token_alert(from_number: str, profiles: list):
    """Send a WhatsApp alert when Gmail token is revoked. Rate-limited to once per 24h."""
    import time
    now = time.time()
    last = _school_token_alert_sent.get(from_number, 0)
    if now - last < 86400:
        return
    _school_token_alert_sent[from_number] = now

    child_names = ", ".join(p["child_name"] for p in profiles if p.get("child_name")) or "your child"
    wa_number = from_number.replace("whatsapp:", "")
    msg = (
        f"⚠️ *Miru school comms paused*\n\n"
        f"Miru lost access to your Gmail and can no longer fetch school emails for {child_names}.\n\n"
        f"Tap below to reconnect (takes 30 seconds):\n"
        f"https://miru.humanagency.co/school/settings?wa={wa_number}"
    )
    try:
        twilio_client.messages.create(
            body=msg,
            from_=os.environ.get("TWILIO_WHATSAPP_NUMBER", ""),
            to=from_number,
        )
        print(f"[school] token alert sent to {from_number}")
    except Exception as e:
        print(f"[school] token alert send failed for {from_number}: {e}")


def _normalise_from_number(raw: str) -> str:
    """Convert user-entered number (+447...) to whatsapp:+447... stored format."""
    import re as _re
    digits = _re.sub(r"[^\d+]", "", raw.strip())
    if not digits.startswith("+"):
        if digits.startswith("07"):
            digits = "+44" + digits[1:]
        elif digits.startswith("44"):
            digits = "+" + digits
        else:
            digits = "+" + digits
    if digits.startswith("whatsapp:"):
        return digits
    return "whatsapp:" + digits


def _get_school_wa():
    """Return (from_number, err_response). Reads X-School-WA header, normalises
    to whatsapp:+... format, validates it exists in school_profiles."""
    raw = (request.headers.get("X-School-WA") or "").strip()
    if not raw:
        return None, (jsonify({"error": "WA number required", "auth": True}), 401)
    wa = _normalise_from_number(raw)
    try:
        rows = (lib._sb().table("school_profiles")
                .select("id").eq("from_number", wa).eq("active", True)
                .limit(1).execute().data or [])
    except Exception:
        rows = []
    if not rows:
        return None, (jsonify({"error": "No account found for this number", "auth": True}), 401)
    return wa, None


@app.route("/api/school/events")
def api_school_events():
    """Return school events for the requesting parent (scoped by WA number)."""
    wa, err = _get_school_wa()
    if err:
        return err
    days_ahead = int(request.args.get("days", 30))
    days_back  = int(request.args.get("back", 30))
    profile_id = request.args.get("profile_id", "")
    from datetime import date, timedelta
    past    = (date.today() - timedelta(days=days_back)).isoformat()
    horizon = (date.today() + timedelta(days=days_ahead)).isoformat()
    try:
        profiles_raw = (lib._sb().table("school_profiles")
                    .select("id,school_name,child_name,class_name,teacher_name,year_group,address,phone,class_wa_group,gmail_refresh_token,sender_emails")
                    .eq("from_number", wa).eq("active", True).execute().data or [])
        profiles = []
        for p in profiles_raw:
            gmail_connected = bool(p.pop("gmail_refresh_token", None))
            oauth_url = _school_oauth_url(p["id"]) if not gmail_connected else None
            p["gmail_connected"] = gmail_connected
            p["oauth_url"] = oauth_url
            profiles.append(p)
        allowed_ids = {p["id"] for p in profiles}
        if not allowed_ids:
            return jsonify({"events": [], "profiles": []})

        def _add_profile_filter(q):
            if profile_id and profile_id in allowed_ids:
                return q.eq("profile_id", profile_id)
            # Filter to only this parent's profiles
            return q.in_("profile_id", list(allowed_ids))

        dated = (_add_profile_filter(
                    lib._sb().table("school_events").select("*")
                    .gte("event_date", past).lte("event_date", horizon))
                 .order("event_date").execute().data or [])
        undated = (_add_profile_filter(
                    lib._sb().table("school_events").select("*")
                    .is_("event_date", "null").gte("created_at", past))
                   .order("created_at", desc=True).execute().data or [])
        all_events = dated + undated
        last_synced = None
        if all_events:
            last_synced = max((e.get("created_at") or "") for e in all_events) or None

        # Enrich events with school_name from profiles
        profile_map = {p["id"]: p.get("school_name", "") for p in profiles}
        for event in all_events:
            pid = event.get("profile_id")
            if pid and pid in profile_map:
                event["school_name"] = profile_map[pid]

        return jsonify({"events": all_events, "profiles": profiles, "last_synced": last_synced})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/school/dedup", methods=["POST"])
def api_school_dedup():
    """Remove fuzzy duplicate school events scoped to requesting parent's WA number."""
    wa, err = _get_school_wa()
    if err:
        return err
    import re as _re

    _stops = {"a","an","the","and","or","for","to","of","in","on","at","is","with",
              "about","from","your","session","drop","first","parent","support"}

    def _words(t):
        return [w for w in _re.sub(r"[^a-z0-9]", " ", (t or "").lower()).split()
                if len(w) > 2 and w not in _stops]

    def _overlap(a, b):
        wa2, wbArr = set(_words(a)), _words(b)
        if not wa2 and not wbArr:
            return 0
        common = sum(1 for w in wbArr if w in wa2)
        return common / max(len(wa2), len(wbArr), 1)

    def _richness(e):
        return (200 if e.get("action_needed") else 0) + len(e.get("description") or "") + len(e.get("action_needed") or "")

    try:
        profiles = (lib._sb().table("school_profiles")
                    .select("id").eq("from_number", wa).eq("active", True).execute().data or [])
        allowed_ids = [p["id"] for p in profiles]
        if not allowed_ids:
            return jsonify({"deleted": 0, "ids": []})
        all_events = (lib._sb().table("school_events").select("*")
                      .in_("profile_id", allowed_ids).execute().data or [])
        to_delete = []

        # Group by profile_id + event_date, then fuzzy-dedup within each group
        from collections import defaultdict
        groups = defaultdict(list)
        for e in all_events:
            key = (e.get("profile_id", ""), e.get("event_date") or "__undated__")
            groups[key].append(e)

        for (pid, dt), evts in groups.items():
            if len(evts) < 2:
                continue
            used = set()
            # Undated: higher overlap threshold to avoid false positives
            threshold = 0.5 if dt == "__undated__" else 0.35
            for i in range(len(evts)):
                if i in used:
                    continue
                cluster = [evts[i]]
                for j in range(i + 1, len(evts)):
                    if j in used:
                        continue
                    if _overlap(evts[i]["event_title"], evts[j]["event_title"]) >= threshold:
                        cluster.append(evts[j])
                        used.add(j)
                if len(cluster) > 1:
                    cluster.sort(key=_richness, reverse=True)
                    for dup in cluster[1:]:
                        to_delete.append(dup["id"])
                used.add(i)

        if to_delete:
            for _id in to_delete:
                lib._sb().table("school_events").delete().eq("id", _id).execute()

        return jsonify({"deleted": len(to_delete), "ids": to_delete})
    except Exception as e:
        return jsonify({"error": str(e)}), 500



