@app.route("/api/books/search")
def api_books_search():
    phone = (request.args.get("phone") or "").strip()
    q     = (request.args.get("q") or "").strip()
    if not phone or not q:
        return jsonify({"results": []})
    hits = lib.books_search(phone, q)
    if not hits:
        rows = lib._sb().table("wa_saves") \
            .select("url,title,summary") \
            .eq("from_number", phone) \
            .like("url", "book:%") \
            .order("created_at", desc=True) \
            .limit(500).execute().data
        q_words = [w.lower() for w in q.split() if len(w) > 1]
        for row in rows:
            try:
                bk = json.loads(row["summary"] or "{}")
            except Exception:
                bk = {}
            bk.setdefault("isbn", row["url"].replace("book:", ""))
            bk.setdefault("title", row["title"] or "")
            text = f"{bk.get('title','')} {bk.get('author','')}".lower()
            if any(w in text for w in q_words):
                hits.append(bk)
    return jsonify({"results": hits[:30]})


@app.route("/api/books/synthesise", methods=["POST"])
def api_books_synthesise():
    """Generate a personalised learning synthesis from a book's reading notes."""
    data  = request.get_json(force=True, silent=True) or {}
    title  = (data.get("title")  or "").strip()
    author = (data.get("author") or "").strip()
    notes  = data.get("notes") or []
    if not notes:
        return jsonify({"error": "no notes to synthesise"}), 400
    api_key = os.environ.get("ANTHROPIC_API_KEY", "")
    if not api_key:
        return jsonify({"error": "AI not configured"}), 503
    notes_text = "\n\n".join([
        f"[{'Scan' if n.get('type')=='scan' else 'Note'} — {n.get('ts','')}]\n{n.get('text','').strip()}"
        for n in notes if n.get("text","").strip()
    ])
    prompt = f"""You are reading someone's private notes from the book "{title}" by {author}.

These are things they chose to capture — their highlights, scanned pages, and personal thoughts:

{notes_text}

Write a synthesis of what they learned from this book. Cover:
- The key ideas that clearly landed with them
- Any arguments, frameworks, or data they found compelling
- What seemed to surprise or challenge their thinking
- Their overall takeaway

Write it in second person ("You discovered…", "The book shifted your thinking on…"). Ground everything in their actual notes — don't add ideas they didn't capture. 150–250 words."""
    try:
        import anthropic as _ant
        client = _ant.Anthropic(api_key=api_key)
        resp = client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=512,
            messages=[{"role": "user", "content": prompt}]
        )
        return jsonify({"synthesis": resp.content[0].text.strip()})
    except Exception as e:
        print(f"[books/synthesise] error: {e}", flush=True)
        return jsonify({"error": str(e)}), 500


@app.route("/api/books/scan-note", methods=["POST"])
def api_books_scan_note():
    """Transcribe text or describe a graph/chart from a scanned book page using Claude Vision."""
    if "image" not in request.files:
        return jsonify({"error": "image required"}), 400
    api_key = os.environ.get("ANTHROPIC_API_KEY", "")
    if not api_key:
        return jsonify({"error": "Vision AI not configured"}), 503
    img_file = request.files["image"]
    img_bytes = img_file.read()
    if not img_bytes:
        return jsonify({"error": "empty image"}), 400
    import base64 as _b64
    import anthropic as _ant
    mime = img_file.mimetype or "image/jpeg"
    if mime not in ("image/jpeg", "image/png", "image/gif", "image/webp"):
        mime = "image/jpeg"
    img_data = _b64.standard_b64encode(img_bytes).decode("utf-8")
    try:
        client = _ant.Anthropic(api_key=api_key)
        resp = client.messages.create(
            model="claude-haiku-4-5-20251001",
            max_tokens=1024,
            messages=[{
                "role": "user",
                "content": [
                    {"type": "image", "source": {"type": "base64", "media_type": mime, "data": img_data}},
                    {"type": "text", "text": (
                        "This is a scan from a book the user is reading.\n\n"
                        "If this is a page of TEXT: transcribe it exactly as written, preserving paragraphs. "
                        "Do not summarise — give the actual words.\n\n"
                        "If this is a GRAPH, CHART, TABLE or DIAGRAM: describe what it shows clearly. "
                        "Cover: what is being measured, the key data points or trends, and what conclusion the visual communicates. "
                        "Be specific and useful — write it so someone who cannot see the image fully understands it.\n\n"
                        'Reply with JSON only: {"type": "transcription" or "description", "text": "..."}'
                    )}
                ]
            }]
        )
        import re as _re
        raw = resp.content[0].text.strip()
        m = _re.search(r'\{.*\}', raw, _re.DOTALL)
        result = json.loads(m.group(0)) if m else {"type": "transcription", "text": raw}

        # Upload image to Supabase Storage so user keeps the original scan
        image_url = ""
        try:
            ext = mime.split("/")[-1].replace("jpeg", "jpg")
            path = f"book-scans/{int(time.time() * 1000)}.{ext}"
            lib._sb().storage.from_("saves-images").upload(
                path, img_bytes, {"content-type": mime, "upsert": "true"}
            )
            image_url = lib._sb().storage.from_("saves-images").get_public_url(path)
        except Exception as _ue:
            print(f"[books/scan-note] storage upload failed: {_ue}", flush=True)

        return jsonify({"text": result.get("text", ""), "type": result.get("type", "transcription"), "image_url": image_url})
    except Exception as e:
        print(f"[books/scan-note] error: {e}", flush=True)
        return jsonify({"error": str(e)}), 500


