# ── PM Intel ──────────────────────────────────────────────────────────────────

@app.route("/pm")
def pm_home():
    return render_template("pm.html")


def _sb_pm():
    from supabase import create_client
    return create_client(os.environ["SUPABASE_URL"], os.environ["SUPABASE_KEY"])


@app.route("/api/pm/projects", methods=["GET", "POST"])
def api_pm_projects():
    try:
        sb = _sb_pm()
        if request.method == "POST":
            data = request.json or {}
            name = (data.get("name") or "").strip()
            if not name:
                return jsonify({"error": "Name required"}), 400
            row = sb.table("pm_projects").insert({
                "name": name,
                "proj_type": data.get("proj_type", "IT Transformation"),
                "phase": int(data.get("phase", 1)),
                "description": data.get("description", ""),
            }).execute()
            return jsonify({"ok": True, "project": row.data[0]})
        rows = sb.table("pm_projects").select("*").order("created_at", desc=True).execute()
        return jsonify(rows.data or [])
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/pm/projects/<project_id>", methods=["PATCH", "DELETE"])
def api_pm_project(project_id):
    try:
        sb = _sb_pm()
        if request.method == "DELETE":
            sb.table("pm_docs").delete().eq("project_id", project_id).execute()
            sb.table("pm_projects").delete().eq("id", project_id).execute()
            return jsonify({"ok": True})
        sb.table("pm_projects").update(request.json or {}).eq("id", project_id).execute()
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/pm/docs", methods=["GET", "POST"])
def api_pm_docs():
    try:
        sb = _sb_pm()
        if request.method == "POST":
            data = request.json or {}
            row = sb.table("pm_docs").insert({
                "project_id": data.get("project_id"),
                "phase": int(data.get("phase", 1)),
                "doc_type": data.get("doc_type", "note"),
                "title": data.get("title", ""),
                "content": data.get("content", ""),
                "ai_summary": data.get("ai_summary", ""),
                "status": data.get("status", "draft"),
            }).execute()
            return jsonify({"ok": True, "doc": row.data[0]})
        project_id = request.args.get("project_id")
        q = sb.table("pm_docs").select("*").order("created_at", desc=True)
        if project_id:
            q = q.eq("project_id", project_id)
        return jsonify(q.execute().data or [])
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/pm/docs/<doc_id>", methods=["PATCH", "DELETE"])
def api_pm_doc(doc_id):
    try:
        sb = _sb_pm()
        if request.method == "DELETE":
            sb.table("pm_docs").delete().eq("id", doc_id).execute()
            return jsonify({"ok": True})
        sb.table("pm_docs").update(request.json or {}).eq("id", doc_id).execute()
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/pm/analyse", methods=["POST"])
def api_pm_analyse():
    data = request.json or {}
    action = data.get("action", "summarise")
    content = (data.get("content") or "").strip()
    context = (data.get("context") or "").strip()
    if not content:
        return jsonify({"error": "Content required"}), 400
    groq_key = os.environ.get("GROQ_API_KEY", "")
    if not groq_key:
        return jsonify({"error": "AI not configured"}), 500

    PROMPTS = {
        "boscard": (
            "You are a senior programme manager. Generate a complete BOSCARD from the brief below.\n"
            "Output clean markdown with these sections:\n"
            "## Benefits\nWhat value does this deliver to the business?\n"
            "## Objectives\n3-5 SMART, measurable objectives\n"
            "## Scope\n**In scope:** ...\n**Out of scope:** ...\n"
            "## Constraints\nTime, budget, resource, regulatory limits\n"
            "## Assumptions\nKey assumptions being made\n"
            "## Risks\nTop 5 risks with (High/Med/Low) probability and impact\n"
            "## Dependencies\nInternal and external dependencies\n\nBrief:\n"
        ),
        "raid": (
            "You are a programme manager. Extract ALL RAID items from the text below.\n"
            "Output clean markdown tables:\n"
            "## Risks\n| ID | Description | Prob | Impact | Owner | Mitigation |\n|---|---|---|---|---|---|\n"
            "## Assumptions\n| ID | Description | Owner | Validation |\n|---|---|---|---|\n"
            "## Issues\n| ID | Description | Priority | Owner | Resolution |\n|---|---|---|---|---|\n"
            "## Dependencies\n| ID | Description | Type | Owner | Due |\n|---|---|---|---|---|\n\nText:\n"
        ),
        "status": (
            "You are a programme manager. Write a formal Weekly Status Report from the notes below.\n"
            "Format:\n**Week ending:** [date if mentioned, else 'w/e [today]']\n"
            "**Overall RAG:** 🟢 Green / 🟡 Amber / 🔴 Red — [one-line reason]\n"
            "**Executive Summary:** [2-3 sentences]\n\n"
            "**Accomplishments this week:**\n- [bullet]\n\n"
            "**Planned next week:**\n- [bullet]\n\n"
            "**Risks & Issues:**\n| Item | RAG | Owner | Action |\n|---|---|---|---|\n\n"
            "**Decisions required:**\n- [bullet or 'None this week']\n\nNotes:\n"
        ),
        "pir": (
            "You are a programme manager writing a Post-Implementation Review.\n"
            "Structure the input into:\n"
            "## Executive Summary\n"
            "## Objectives vs Actuals\n| Objective | Target | Achieved | RAG |\n|---|---|---|---|\n"
            "## What Went Well\n- [bullets]\n"
            "## Areas for Improvement\n- [bullets]\n"
            "## Recommendations for Future Projects\n- [bullets]\n"
            "## Benefits Realised\n\nInput:\n"
        ),
        "tsa": (
            "You are an IT separation programme manager reviewing a TSA document.\n"
            "Produce:\n## TSA Summary\nServices, exit dates, SLAs\n"
            "## Open Actions\n| Action | Owner | Due | Status |\n|---|---|---|---|\n"
            "## Exit Risk Areas\nServices at risk of delayed exit\n"
            "## Recommendations\nNext steps and critical path items\n\nContent:\n"
        ),
        "summarise": (
            "Summarise the following document for a senior executive. Output:\n"
            "**One-line summary** (max 20 words)\n"
            "**Key Points** (5 bullets max)\n"
            "**Decisions / Actions needed** (if any)\n"
            "**RAG Status** (Green/Amber/Red with reason, if inferable)\n\nDocument:\n"
        ),
        "raci": (
            "You are a programme manager. Generate a RACI matrix from the content below.\n"
            "List all activities/deliverables as rows. List stakeholder roles as columns.\n"
            "Use R=Responsible, A=Accountable, C=Consulted, I=Informed.\n"
            "Output as a markdown table.\n\nContent:\n"
        ),
    }

    prompt_text = PROMPTS.get(action, PROMPTS["summarise"])
    if context:
        prompt_text = f"Project context: {context}\n\n" + prompt_text

    try:
        r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {groq_key}", "Content-Type": "application/json"},
            json={
                "model": "llama-3.3-70b-versatile",
                "messages": [{"role": "user", "content": prompt_text + content}],
                "temperature": 0.25,
                "max_tokens": 2000,
            },
            timeout=35,
        )
        if r.status_code != 200:
            return jsonify({"error": f"AI error {r.status_code}"}), 500
        result = r.json()["choices"][0]["message"]["content"].strip()
        return jsonify({"result": result})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/pm/assess", methods=["POST"])
def api_pm_assess():
    data = request.json or {}
    problem = (data.get("problem") or "").strip()
    if not problem:
        return jsonify({"error": "Problem description required"}), 400
    groq_key = os.environ.get("GROQ_API_KEY", "")
    if not groq_key:
        return jsonify({"error": "AI not configured"}), 500

    prompt = (
        "You are a senior programme manager reviewing a brief before committing to a full pack. "
        "Your job: read critically, spot gaps, challenge assumptions, surface what's missing. "
        "Do NOT generate a full pack yet — just assess.\n\n"
        "Return ONLY valid JSON:\n"
        "{\n"
        '  "feasibility": "green|amber|red",\n'
        '  "feasibility_reason": "1 honest sentence on confidence level",\n'
        '  "project_name": "concise project name",\n'
        '  "project_type": "IT Transformation|Digital Build|Process Improvement|De-merger|ERP Implementation|RFP / Procurement|Vendor Engagement|Discovery & Research|Other",\n'
        '  "lifecycle_type": "standard|rfp|vendor|discovery",\n'
        '  "lifecycle_note": "one sentence explaining which lifecycle this follows and why",\n'
        '  "challenges": [\n'
        '    "Specific question that would materially change scope, timeline or approach",\n'
        '    "Another question — 3 to 5 total"\n'
        '  ],\n'
        '  "assumptions": [\n'
        '    "I am assuming X, which would affect Y if wrong",\n'
        '    "2 to 3 assumptions total"\n'
        '  ]\n'
        "}\n\n"
        "Lifecycle detection rules:\n"
        "- rfp: brief mentions RFP, tender, procurement, vendor selection, market engagement, ITT\n"
        "- vendor: brief mentions pitching to a specific vendor, existing vendor, SOW, proof of concept with named supplier\n"
        "- discovery: brief mentions user research, interviews, use case discovery, understanding the problem, hypothesis validation\n"
        "- standard: everything else — IT transformation, digital build, ERP, de-merger, process improvement\n\n"
        "Challenge rules:\n"
        "- Ask 3-5 questions specific to THIS brief, not generic PM questions\n"
        "- Probe: scope boundary, ownership, timeline realism, success metrics, key dependencies\n"
        "- Don't ask what's already stated in the brief\n"
        "- If the brief is vague, challenge the vagueness directly\n\n"
        "Brief:\n"
    )

    try:
        r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {groq_key}", "Content-Type": "application/json"},
            json={
                "model": "llama-3.3-70b-versatile",
                "messages": [{"role": "user", "content": prompt + problem}],
                "temperature": 0.2,
                "max_tokens": 1200,
            },
            timeout=30,
        )
        if r.status_code != 200:
            return jsonify({"error": f"AI error {r.status_code}"}), 500
        raw = r.json()["choices"][0]["message"]["content"].strip()
        if raw.startswith("```"):
            raw = raw.split("```")[1]
            if raw.startswith("json"):
                raw = raw[4:]
            raw = raw.strip()
        import json as _json
        parsed = _json.loads(raw)
        return jsonify(parsed)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/pm/refine", methods=["POST"])
def api_pm_refine():
    import json as _json
    data = request.json or {}
    section     = (data.get("section") or "").strip()
    instruction = (data.get("instruction") or "").strip()
    context     = data.get("context") or {}
    if not section or not instruction or not context:
        return jsonify({"error": "section, instruction and context required"}), 400
    groq_key = os.environ.get("GROQ_API_KEY", "")
    if not groq_key:
        return jsonify({"error": "AI not configured"}), 500

    section_content = {
        "vision":      context.get("vision", ""),
        "boscard":     context.get("boscard", ""),
        "requirements":_json.dumps(context.get("requirements", {})),
        "use_cases":   _json.dumps(context.get("use_cases", [])),
        "plan":        _json.dumps(context.get("plan", {})),
        "risks":       _json.dumps(context.get("risks", [])),
        "actions":     _json.dumps(context.get("actions", [])),
        "jira_epics":  _json.dumps(context.get("jira_epics", [])),
    }.get(section, "")

    return_formats = {
        "vision":       '{"vision": "rewritten vision paragraph"}',
        "boscard":      '{"boscard": "## Benefits\\n- ...\\n## Objectives\\n- SMART objective\\n## Scope\\n**In:** ...\\n**Out:** ...\\n## Constraints\\n- ...\\n## Assumptions\\n- ...\\n## Risks\\n- Risk (H/M/L)\\n## Dependencies\\n- ..."}',
        "requirements": '{"requirements": {"functional": ["FR1: ...", "FR2: ..."], "non_functional": ["NFR1: Performance — ...", "NFR2: Security — ..."]}}',
        "use_cases":    '{"use_cases": [{"id": "UC1", "actor": "...", "action": "...", "outcome": "..."}]}',
        "plan":         '{"plan": {"phases": [{"name": "...", "duration": "...", "activities": ["...", "..."]}]}}',
        "risks":        '{"risks": [{"risk": "...", "prob": "High|Med|Low", "impact": "High|Med|Low", "mitigation": "..."}]}',
        "actions":      '{"actions": ["First concrete action", "Second action", "Third action"]}',
        "jira_epics":   '{"jira_epics": [{"epic": "Epic name", "stories": ["Story 1", "Story 2"]}]}',
    }
    return_fmt = return_formats.get(section, f'{{"{section}": ...}}')

    prompt = (
        f"You are refining the '{section}' section of a programme pack.\n\n"
        f"Project: {context.get('project_name','Unknown')} ({context.get('project_type','')})\n"
        f"Vision: {str(context.get('vision',''))[:300]}\n\n"
        f"Current {section}:\n{section_content}\n\n"
        f"Refinement instruction: {instruction}\n\n"
        f"Return ONLY valid JSON with just the updated section:\n{return_fmt}\n"
    )

    try:
        r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {groq_key}", "Content-Type": "application/json"},
            json={
                "model": "llama-3.3-70b-versatile",
                "messages": [{"role": "user", "content": prompt}],
                "temperature": 0.3,
                "max_tokens": 2500,
            },
            timeout=45,
        )
        if r.status_code != 200:
            return jsonify({"error": f"AI error {r.status_code}"}), 500
        raw = r.json()["choices"][0]["message"]["content"].strip()
        if raw.startswith("```"):
            raw = raw.split("```")[1]
            if raw.startswith("json"):
                raw = raw[4:]
            raw = raw.strip()
        parsed = _json.loads(raw)
        return jsonify(parsed)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/pm/intake", methods=["POST"])
def api_pm_intake():
    """Agentic parallel generation: 3 specialist agents run concurrently, results merged."""
    data = request.json or {}
    problem = (data.get("problem") or "").strip()
    if not problem:
        return jsonify({"error": "Problem description required"}), 400
    groq_key = os.environ.get("GROQ_API_KEY", "")
