def _resolve_place_name(postcode: str) -> dict:
    """
    Look up human-readable place name for a UK postcode.
    Uses postcodes.io for lat/lon + county, then Nominatim for local name.
    Returns {"postcode", "place_name", "county", "display_label"}.
    """
    postcode = postcode.strip().replace(" ", "").upper()
    # 1. postcodes.io — lat/lon + county
    pc_data = {}
    try:
        r = requests.get(f"https://api.postcodes.io/postcodes/{postcode}", timeout=8,
                         headers={"User-Agent": "MiruApp/1.0 (miru.humanagency.co)"})
        j = r.json()
        if j.get("status") == 200:
            pc_data = j["result"]
    except Exception:
        pass

    lat = pc_data.get("latitude")
    lon = pc_data.get("longitude")
    _raw_county = pc_data.get("admin_county") or ""
    # Filter out postcodes.io pseudo-county entries (e.g. "(pseudo) England (UA/MD/LB)")
    county = _raw_county if _raw_county and "(pseudo)" not in _raw_county.lower() and "ua/md/lb" not in _raw_county.lower() else ""

    # 2. Nominatim reverse geocode — local place name
    place_name = ""
    if lat and lon:
        try:
            nr = requests.get(
                "https://nominatim.openstreetmap.org/reverse",
                params={"lat": lat, "lon": lon, "format": "json", "zoom": 14, "addressdetails": 1},
                timeout=8,
                headers={"User-Agent": "MiruApp/1.0 (miru.humanagency.co)"},
            )
            addr = nr.json().get("address", {})
            # Pick the most local recognisable name
            place_name = (addr.get("suburb") or addr.get("town") or
                          addr.get("village") or addr.get("hamlet") or
                          addr.get("city_district") or addr.get("city") or "")
        except Exception:
            pass

    # 3. Build display label
    if place_name and county:
        display_label = f"{place_name} · {county}"
    elif place_name:
        display_label = place_name
    elif county:
        display_label = county
    else:
        display_label = ""

    return {"postcode": postcode, "place_name": place_name, "county": county, "display_label": display_label}


@app.route("/api/place-name")
def api_place_name():
    """Return human-readable area name for a postcode, cached in Supabase."""
    postcode = request.args.get("postcode", "").strip().replace(" ", "").upper()
    if not postcode:
        return jsonify({"error": "postcode required"}), 400

    sb = lib._sb()
    # Check cache
    try:
        row = sb.table("postcode_place_names").select("*").eq("postcode", postcode).maybe_single().execute()
        if row and row.data:
            return jsonify(row.data)
    except Exception:
        pass

    # Cache miss — resolve and store
    result = _resolve_place_name(postcode)
    try:
        sb.table("postcode_place_names").upsert(result).execute()
    except Exception:
        pass
    return jsonify(result)


@app.route("/api/place-name/seed", methods=["POST"])
def api_place_name_seed():
    """One-time seeder: resolve place names for all saved home postcodes."""
    if request.headers.get("X-Admin-Token") != "miru-digest-2026":
        return jsonify({"error": "Forbidden"}), 403

    sb = lib._sb()
    # Get all distinct home postcodes
    try:
        rows = sb.table("my_area_places").select("postcode").eq("category", "_home").execute()
        postcodes = list({r["postcode"].strip().replace(" ", "").upper()
                          for r in (rows.data or []) if r.get("postcode")})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

    results = []
    import time
    for pc in postcodes:
        # Skip if already cached
        try:
            existing = sb.table("postcode_place_names").select("postcode").eq("postcode", pc).maybe_single().execute()
            if existing and existing.data:
                results.append({"postcode": pc, "status": "cached"})
                continue
        except Exception:
            pass

        result = _resolve_place_name(pc)
        try:
            sb.table("postcode_place_names").upsert(result).execute()
        except Exception as e:
            result["error"] = str(e)
        results.append({**result, "status": "resolved"})
        time.sleep(1.1)  # Nominatim rate limit: 1 req/sec

    return jsonify({"seeded": len(results), "results": results})


@app.route("/api/places/near-me")
def api_places_near_me():
    """Any named venue within 200m via Overpass — used by the nearby FAB."""
    try:
        lat = float(request.args.get("lat", ""))
        lng = float(request.args.get("lng", ""))
    except (ValueError, TypeError):
        return jsonify({"error": "lat/lng required"}), 400
    radius = min(int(request.args.get("radius", 5000)), 10000)
    query = (
        f"[out:json][timeout:15];"
        f"("
        f"node(around:{radius},{lat},{lng})[name][shop];"
        f"node(around:{radius},{lat},{lng})[name][amenity];"
        f"node(around:{radius},{lat},{lng})[name][tourism];"
        f"node(around:{radius},{lat},{lng})[name][leisure];"
        f"way(around:{radius},{lat},{lng})[name][shop];"
        f"way(around:{radius},{lat},{lng})[name][amenity];"
        f");"
        f"out center 20;"
    )
    try:
        r = requests.post("https://overpass-api.de/api/interpreter",
                          data={"data": query}, timeout=9)
        elements = r.json().get("elements", [])
        seen, results = set(), []
        for el in elements:
            tags = el.get("tags", {})
            name = tags.get("name", "").strip()
            if not name or name in seen:
                continue
            seen.add(name)
            if el.get("type") == "node":
                elat, elon = el.get("lat"), el.get("lon")
            else:
                c = el.get("center", {})
                elat, elon = c.get("lat"), c.get("lon")
            raw_type = (tags.get("shop") or tags.get("amenity") or
                        tags.get("tourism") or tags.get("leisure") or "").lower()
            category, _ = _VENUE_SHOP_MAP.get(raw_type, (raw_type.replace("_", " ").title(), ""))
            dist_m = round(haversine_km(lat, lng, elat, elon) * 1000) if elat and elon else 9999
            results.append({"name": name, "type": raw_type, "category": category, "distance_m": dist_m})
        results.sort(key=lambda x: x["distance_m"])
        return jsonify({"places": results[:15]})
    except Exception as e:
        return jsonify({"error": str(e), "places": []}), 500


@app.route("/api/ev/nearby")
def api_ev_nearby():
    """Nearest EV charging stations via OpenStreetMap Overpass (free, no key)."""
    postcode = request.args.get("postcode", "").strip().upper()
    lat_s = request.args.get("lat", "").strip()
    lon_s = request.args.get("lon", "").strip()

    lat, lon = None, None
    if lat_s and lon_s:
        try: lat, lon = float(lat_s), float(lon_s)
        except ValueError: pass
    if lat is None and postcode:
        ll = postcode_to_latlon(postcode)
        if ll: lat, lon = ll

    if lat is None:
        return jsonify({"error": "postcode or lat/lon required"}), 400

    from search import _sb_cache_get, _sb_cache_set
    cache_key = f"ev:{round(lat,3)},{round(lon,3)}"
    cached = _sb_cache_get(cache_key)
    if cached and cached.get("chargers"):
        return jsonify(cached)

    try:
        query = f"""[out:json][timeout:12];node["amenity"="charging_station"](around:1500,{lat},{lon});out body;"""
        elements = _overpass_query(query)

        chargers = []
        for el in elements:
            tags = el.get("tags", {})
            name = tags.get("name") or tags.get("operator") or tags.get("network") or "Charging Point"
            # Count sockets
            sockets = []
            for tag, label in [("socket:type2","Type 2"), ("socket:type2_combo","CCS"), ("socket:chademo","CHAdeMO"), ("socket:type1","Type 1")]:
                if tags.get(tag):
                    try:
                        n = int(tags[tag])
                        sockets.append(f"{n}× {label}" if n > 1 else label)
                    except (ValueError, TypeError):
                        sockets.append(label)
            capacity = tags.get("capacity", "")
            try: capacity = int(capacity)
            except (ValueError, TypeError): capacity = None
            operator = tags.get("operator") or tags.get("network") or ""
            fee = tags.get("fee", "")
            dist_m = round(haversine_km(lat, lon, el["lat"], el["lon"]) * 1000)
            chargers.append({
                "name": name,
                "operator": operator,
                "sockets": sockets,
                "capacity": capacity,
                "fee": fee,
                "dist_m": dist_m,
                "lat": el["lat"],
                "lon": el["lon"],
            })

        chargers.sort(key=lambda c: c["dist_m"])
        chargers = chargers[:6]
        result = {"chargers": chargers, "lat": lat, "lon": lon}
        if chargers:  # don't cache empty — retry next time
            _sb_cache_set(cache_key, result)
        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


