@app.route("/admin/migrate-restaurant-types")
def admin_migrate_restaurant_types():
    """Migrate existing receipts with restaurant type classification."""
    try:
        from restaurant_classifier import classify_restaurant

        sb = lib._sb()

        # First, try to add the restaurant_type column if it doesn't exist
        try:
            # Test query to see if column exists
            sb.table("receipts").select("restaurant_type").limit(1).execute()
        except:
            # Column doesn't exist - return message to user
            return jsonify({
                "success": False,
                "message": "restaurant_type column doesn't exist in receipts table",
                "action": "Add 'restaurant_type' column to receipts table in Supabase first (type: text)"
            }), 400

        # Get all receipts
        receipts = sb.table("receipts").select("*").execute().data or []

        updated = 0
        for receipt in receipts:
            merchant = receipt.get("merchant", "")
            if not merchant:
                continue

            rtype = classify_restaurant(merchant)

            # Skip if already tagged or unknown
            if receipt.get("restaurant_type") or rtype == "unknown":
                continue

            # Update receipt with type
            sb.table("receipts").update({
                "restaurant_type": rtype
            }).eq("id", receipt["id"]).execute()

            updated += 1

        return jsonify({"success": True, "migrated": updated, "total": len(receipts)})

    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


